window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["MAL"]={"book":"MAL","editions":{"hbo-source":[[1,1,"מַשָּׂ֥א דְבַר־יְהוָ֖ה אֶל־יִשְׂרָאֵ֑ל בְּ⁠יַ֖ד מַלְאָכִֽי׃","maşá֥̇̂ʼ dĕbar-yĕhwá֖h ʼel-yişĕ̂ráʼé֑l bĕ̇⁠ya֖d malĕʼákiֽy׃"],[1,2,"אָהַ֤בְתִּי אֶתְ⁠כֶם֙ אָמַ֣ר יְהוָ֔ה וַ⁠אֲמַרְתֶּ֖ם בַּ⁠מָּ֣ה אֲהַבְתָּ֑⁠נוּ הֲ⁠לוֹא־אָ֨ח עֵשָׂ֤ו לְ⁠יַֽעֲקֹב֙ נְאֻם־יְהוָ֔ה וָ⁠אֹהַ֖ב אֶֽת־יַעֲקֹֽב׃","ʼáha֤bĕţi̇y ʼeţĕ⁠kem֙ ʼáma֣r yĕhwá֔h wa⁠ʼàmarĕţė֖m bȧ⁠má֣̇h ʼàhabĕţá֑̇⁠nẇ hà⁠lwòʼ-ʼá֨ẖ ʻéşá֤̂w lĕ⁠yaֽʻàqòb֙ nĕʼum-yĕhwá֔h wá⁠ʼòha֖b ʼeֽţ-yaʻàqòֽb׃"],[1,3,"וְ⁠אֶת־עֵשָׂ֖ו שָׂנֵ֑אתִי וָ⁠אָשִׂ֤ים אֶת־הָרָי⁠ו֙ שְׁמָמָ֔ה וְ⁠אֶת־נַחֲלָת֖⁠וֹ לְ⁠תַנּ֥וֹת מִדְבָּֽר׃","wĕ⁠ʼeţ-ʻéşá֖̂w şá̂né֑ʼţiy wá⁠ʼáşî֤ym ʼeţ-háráy⁠w֙ şĕ̌mámá֔h wĕ⁠ʼeţ-naẖàláţ֖⁠wò lĕ⁠ţaṅ֥wòţ midĕbáֽ̇r׃"],[1,4,"כִּֽי־תֹאמַ֨ר אֱד֜וֹם רֻשַּׁ֗שְׁנוּ וְ⁠נָשׁוּב֙ וְ⁠נִבְנֶ֣ה חֳרָב֔וֹת כֹּ֤ה אָמַר֙ יְהוָ֣ה צְבָא֔וֹת הֵ֥מָּה יִבְנ֖וּ וַ⁠אֲנִ֣י אֶהֱר֑וֹס וְ⁠קָרְא֤וּ לָ⁠הֶם֙ גְּב֣וּל רִשְׁעָ֔ה וְ⁠הָ⁠עָ֛ם אֲשֶׁר־זָעַ֥ם יְהוָ֖ה עַד־עוֹלָֽם׃","kiֽ̇y-ţòʼma֨r ʼèd֜wòm ruşȧ̌֗şĕ̌nẇ wĕ⁠náş̌ẇb֙ wĕ⁠nibĕne֣h ẖoráb֔wòţ kò֤̇h ʼámar֙ yĕhwá֣h ẕĕbáʼ֔wòţ hé֥má̇h yibĕn֖ẇ wa⁠ʼàni֣y ʼehèr֑wòs wĕ⁠qárĕʼ֤ẇ lá⁠hem֙ gĕ̇b֣ẇl rişĕ̌ʻá֔h wĕ⁠há⁠ʻá֛m ʼàşěr-záʻa֥m yĕhwá֖h ʻad-ʻwòláֽm׃"],[1,5,"וְ⁠עֵינֵי⁠כֶ֖ם תִּרְאֶ֑ינָה וְ⁠אַתֶּ֤ם תֹּֽאמְרוּ֙ יִגְדַּ֣ל יְהוָ֔ה מֵ⁠עַ֖ל לִ⁠גְב֥וּל יִשְׂרָאֵֽל׃","wĕ⁠ʻéynéy⁠ke֖m ţi̇rĕʼe֑ynáh wĕ⁠ʼaţė֤m ţòֽ̇ʼmĕrẇ֙ yigĕdȧ֣l yĕhwá֔h mé⁠ʻa֖l li⁠gĕb֥ẇl yişĕ̂ráʼéֽl׃"],[1,6,"בֵּ֛ן יְכַבֵּ֥ד אָ֖ב וְ⁠עֶ֣בֶד אֲדֹנָ֑י⁠ו וְ⁠אִם־אָ֣ב אָ֣נִי אַיֵּ֣ה כְבוֹדִ֡⁠י וְ⁠אִם־אֲדוֹנִ֣ים אָנִי֩ אַיֵּ֨ה מוֹרָאִ֜⁠י אָמַ֣ר ׀ יְהוָ֣ה צְבָא֗וֹת לָ⁠כֶם֙ הַ⁠כֹּֽהֲנִים֙ בּוֹזֵ֣י שְׁמִ֔⁠י וַ⁠אֲמַרְתֶּ֕ם בַּ⁠מֶּ֥ה בָזִ֖ינוּ אֶת־שְׁמֶֽ⁠ךָ׃","bé֛̇n yĕkabé֥̇d ʼá֖b wĕ⁠ʻe֣bed ʼàdòná֑y⁠w wĕ⁠ʼim-ʼá֣b ʼá֣niy ʼayé֣̇h kĕbwòdi֡⁠y wĕ⁠ʼim-ʼàdwòni֣ym ʼániy֩ ʼayé̇֨h mwòráʼi֜⁠y ʼáma֣r ׀ yĕhwá֣h ẕĕbáʼ֗wòţ lá⁠kem֙ ha⁠kòֽ̇hàniym֙ ḃwòzé֣y şĕ̌mi֔⁠y wa⁠ʼàmarĕţė֕m bȧ⁠mė֥h bázi֖ynẇ ʼeţ-şĕ̌meֽ⁠ká׃"],[1,7,"מַגִּישִׁ֤ים עַֽל־מִזְבְּחִ⁠י֙ לֶ֣חֶם מְגֹאָ֔ל וַ⁠אֲמַרְתֶּ֖ם בַּ⁠מֶּ֣ה גֵֽאַלְנ֑וּ⁠ךָ בֶּ⁠אֱמָרְ⁠כֶ֕ם שֻׁלְחַ֥ן יְהוָ֖ה נִבְזֶ֥ה הֽוּא׃","magi̇yşǐ֤ym ʻaֽl-mizĕbĕ̇ẖi⁠y֙ le֣ẖem mĕgòʼá֔l wa⁠ʼàmarĕţė֖m bȧ⁠mė֣h géֽʼalĕn֑ẇ⁠ká bė⁠ʼèmárĕ⁠ke֕m şǔlĕẖa֥n yĕhwá֖h nibĕze֥h hֽẇʼ׃"],[1,8,"וְ⁠כִֽי־תַגִּשׁ֨וּ⁠ן עִוֵּ֤ר לִ⁠זְבֹּ֨חַ֙ אֵ֣ין רָ֔ע וְ⁠כִ֥י תַגִּ֛ישׁוּ פִּסֵּ֥חַ וְ⁠חֹלֶ֖ה אֵ֣ין רָ֑ע הַקְרִיבֵ֨⁠הוּ נָ֜א לְ⁠פֶחָתֶ֗⁠ךָ הֲ⁠יִּרְצְ⁠ךָ֙ א֚וֹ הֲ⁠יִשָּׂ֣א פָנֶ֔י⁠ךָ אָמַ֖ר יְהוָ֥ה צְבָאֽוֹת׃","wĕ⁠kiֽy-ţagi̇ş̌֨ẇ⁠n ʻiwé֤̇r li⁠zĕbò̇֨ẖa֙ ʼé֣yn rá֔ʻ wĕ⁠ki֥y ţagi֛̇yş̌ẇ pi̇sé֥̇ẖa wĕ⁠ẖòle֖h ʼé֣yn rá֑ʻ haqĕriybé֨⁠hẇ ná֜ʼ lĕ⁠peẖáţe֗⁠ká hà⁠yi̇rĕẕĕ⁠ká֙ ʼ֚wò hà⁠yişá֣̇̂ʼ páne֔y⁠ká ʼáma֖r yĕhwá֥h ẕĕbáʼֽwòţ׃"],[1,9,"וְ⁠עַתָּ֛ה חַלּוּ־נָ֥א פְנֵי־אֵ֖ל וִֽ⁠יחָנֵ֑⁠נוּ מִ⁠יֶּדְ⁠כֶם֙ הָ֣יְתָה זֹּ֔את הֲ⁠יִשָּׂ֤א מִ⁠כֶּם֙ פָּנִ֔ים אָמַ֖ר יְהוָ֥ה צְבָאֽוֹת׃","wĕ⁠ʻaţá֛̇h ẖal̇ẇ-ná֥ʼ pĕnéy-ʼé֖l wiֽ⁠yẖáné֑⁠nẇ mi⁠yėdĕ⁠kem֙ há֣yĕţáh zò̇֔ʼţ hà⁠yişá֤̇̂ʼ mi⁠kėm֙ pá̇ni֔ym ʼáma֖r yĕhwá֥h ẕĕbáʼֽwòţ׃"],[1,10,"מִ֤י גַם־בָּ⁠כֶם֙ וְ⁠יִסְגֹּ֣ר דְּלָתַ֔יִם וְ⁠לֹֽא־תָאִ֥ירוּ מִזְבְּחִ֖⁠י חִנָּ֑ם אֵֽין־לִ֨⁠י חֵ֜פֶץ בָּ⁠כֶ֗ם אָמַר֙ יְהוָ֣ה צְבָא֔וֹת וּ⁠מִנְחָ֖ה לֹֽא־אֶרְצֶ֥ה מִ⁠יֶּדְ⁠כֶֽם׃","mi֤y gam-bá̇⁠kem֙ wĕ⁠yisĕgò֣̇r dĕ̇láţa֔yim wĕ⁠lòֽʼ-ţáʼi֥yrẇ mizĕbĕ̇ẖi֖⁠y ẖiná֑̇m ʼéֽyn-li֨⁠y ẖé֜peẕ bá̇⁠ke֗m ʼámar֙ yĕhwá֣h ẕĕbáʼ֔wòţ ẇ⁠minĕẖá֖h lòֽʼ-ʼerĕẕe֥h mi⁠yėdĕ⁠keֽm׃"],[1,11,"כִּ֣י מִ⁠מִּזְרַח־שֶׁ֜מֶשׁ וְ⁠עַד־מְבוֹא֗⁠וֹ גָּד֤וֹל שְׁמִ⁠י֙ בַּ⁠גּוֹיִ֔ם וּ⁠בְ⁠כָל־מָק֗וֹם מֻקְטָ֥ר מֻגָּ֛שׁ לִ⁠שְׁמִ֖⁠י וּ⁠מִנְחָ֣ה טְהוֹרָ֑ה כִּֽי־גָד֤וֹל שְׁמִ⁠י֙ בַּ⁠גּוֹיִ֔ם אָמַ֖ר יְהוָ֥ה צְבָאֽוֹת׃","ki֣̇y mi⁠mi̇zĕraẖ-şě֜meş̌ wĕ⁠ʻad-mĕbwòʼ֗⁠wò gá̇d֤wòl şĕ̌mi⁠y֙ bȧ⁠ġwòyi֔m ẇ⁠bĕ⁠kál-máq֗wòm muqĕtá֥r mugá֛̇ş̌ li⁠şĕ̌mi֖⁠y ẇ⁠minĕẖá֣h tĕhwòrá֑h kiֽ̇y-gád֤wòl şĕ̌mi⁠y֙ bȧ⁠ġwòyi֔m ʼáma֖r yĕhwá֥h ẕĕbáʼֽwòţ׃"],[1,12,"וְ⁠אַתֶּ֖ם מְחַלְּלִ֣ים אוֹת֑⁠וֹ בֶּ⁠אֱמָרְ⁠כֶ֗ם שֻׁלְחַ֤ן אֲדֹנָ⁠י֙ מְגֹאָ֣ל ה֔וּא וְ⁠נִיב֖⁠וֹ נִבְזֶ֥ה אָכְלֽ⁠וֹ׃","wĕ⁠ʼaţė֖m mĕẖalĕ̇li֣ym ʼwòţ֑⁠wò bė⁠ʼèmárĕ⁠ke֗m şǔlĕẖa֤n ʼàdòná⁠y֙ mĕgòʼá֣l h֔ẇʼ wĕ⁠niyb֖⁠wò nibĕze֥h ʼákĕlֽ⁠wò׃"],[1,13,"וַ⁠אֲמַרְתֶּם֩ הִנֵּ֨ה מַ⁠תְּלָאָ֜ה וְ⁠הִפַּחְתֶּ֣ם אוֹת֗⁠וֹ אָמַר֙ יְהוָ֣ה צְבָא֔וֹת וַ⁠הֲבֵאתֶ֣ם גָּז֗וּל וְ⁠אֶת־הַ⁠פִּסֵּ֨חַ֙ וְ⁠אֶת־הַ֣⁠חוֹלֶ֔ה וַ⁠הֲבֵאתֶ֖ם אֶת־הַ⁠מִּנְחָ֑ה הַ⁠אֶרְצֶ֥ה אוֹתָ֛⁠הּ מִ⁠יֶּדְ⁠כֶ֖ם אָמַ֥ר יְהוָֽה׃ס","wa⁠ʼàmarĕţėm֩ hiné̇֨h ma⁠ţĕ̇láʼá֜h wĕ⁠hipȧẖĕţė֣m ʼwòţ֗⁠wò ʼámar֙ yĕhwá֣h ẕĕbáʼ֔wòţ wa⁠hàbéʼţe֣m gá̇z֗ẇl wĕ⁠ʼeţ-ha⁠pi̇sé̇֨ẖa֙ wĕ⁠ʼeţ-ha֣⁠ẖwòle֔h wa⁠hàbéʼţe֖m ʼeţ-ha⁠mi̇nĕẖá֑h ha⁠ʼerĕẕe֥h ʼwòţá֛⁠ḣ mi⁠yėdĕ⁠ke֖m ʼáma֥r yĕhwáֽh׃s"],[1,14,"וְ⁠אָר֣וּר נוֹכֵ֗ל וְ⁠יֵ֤שׁ בְּ⁠עֶדְר⁠וֹ֙ זָכָ֔ר וְ⁠נֹדֵ֛ר וְ⁠זֹבֵ֥חַ מָשְׁחָ֖ת לַֽ⁠אדֹנָ֑⁠י כִּי֩ מֶ֨לֶךְ גָּד֜וֹל אָ֗נִי אָמַר֙ יְהוָ֣ה צְבָא֔וֹת וּ⁠שְׁמִ֖⁠י נוֹרָ֥א בַ⁠גּוֹיִֽם׃","wĕ⁠ʼár֣ẇr nwòké֗l wĕ⁠yé֤ş̌ bĕ̇⁠ʻedĕr⁠wò֙ záká֔r wĕ⁠nòdé֛r wĕ⁠zòbé֥ẖa máşĕ̌ẖá֖ţ laֽ⁠ʼdòná֑⁠y ki̇y֩ me֨lekĕ gá̇d֜wòl ʼá֗niy ʼámar֙ yĕhwá֣h ẕĕbáʼ֔wòţ ẇ⁠şĕ̌mi֖⁠y nwòrá֥ʼ ba⁠ġwòyiֽm׃"],[2,1,"וְ⁠עַתָּ֗ה אֲלֵי⁠כֶ֛ם הַ⁠מִּצְוָ֥ה הַ⁠זֹּ֖את הַ⁠כֹּהֲנִֽים׃","wĕ⁠ʻaţá̇֗h ʼàléy⁠ke֛m ha⁠mi̇ẕĕwá֥h ha⁠zò֖̇ʼţ ha⁠kò̇hàniֽym׃"],[2,2,"אִם־לֹ֣א תִשְׁמְע֡וּ וְ⁠אִם־לֹא֩ תָשִׂ֨ימוּ עַל־לֵ֜ב לָ⁠תֵ֧ת כָּב֣וֹד לִ⁠שְׁמִ֗⁠י אָמַר֙ יְהוָ֣ה צְבָא֔וֹת וְ⁠שִׁלַּחְתִּ֤י בָ⁠כֶם֙ אֶת־הַ⁠מְּאֵרָ֔ה וְ⁠אָרוֹתִ֖י אֶת־בִּרְכֽוֹתֵי⁠כֶ֑ם וְ⁠גַם֙ אָרוֹתִ֔י⁠הָ כִּ֥י אֵינְ⁠כֶ֖ם שָׂמִ֥ים עַל־לֵֽב׃","ʼim-lò֣ʼ ţişĕ̌mĕʻ֡ẇ wĕ⁠ʼim-lòʼ֩ ţáşî֨ymẇ ʻal-lé֜b lá⁠ţé֧ţ ká̇b֣wòd li⁠şĕ̌mi֗⁠y ʼámar֙ yĕhwá֣h ẕĕbáʼ֔wòţ wĕ⁠şǐlȧẖĕţi֤̇y bá⁠kem֙ ʼeţ-ha⁠mĕ̇ʼérá֔h wĕ⁠ʼárwòţi֖y ʼeţ-bi̇rĕkֽwòţéy⁠ke֑m wĕ⁠gam֙ ʼárwòţi֔y⁠há ki֥̇y ʼéynĕ⁠ke֖m şá̂mi֥ym ʻal-léֽb׃"],[2,3,"הִנְ⁠נִ֨י גֹעֵ֤ר לָ⁠כֶם֙ אֶת־הַ⁠זֶּ֔רַע וְ⁠זֵרִ֤יתִי פֶ֨רֶשׁ֙ עַל־פְּנֵי⁠כֶ֔ם פֶּ֖רֶשׁ חַגֵּי⁠כֶ֑ם וְ⁠נָשָׂ֥א אֶתְ⁠כֶ֖ם אֵלָֽי⁠ו׃","hinĕ⁠ni֨y gòʻé֤r lá⁠kem֙ ʼeţ-ha⁠zė֔raʻ wĕ⁠zéri֤yţiy pe֨reş̌֙ ʻal-pĕ̇néy⁠ke֔m pė֖reş̌ ẖagé̇y⁠ke֑m wĕ⁠náşá֥̂ʼ ʼeţĕ⁠ke֖m ʼéláֽy⁠w׃"],[2,4,"וִֽ⁠ידַעְתֶּ֕ם כִּ֚י שִׁלַּ֣חְתִּי אֲלֵי⁠כֶ֔ם אֵ֖ת הַ⁠מִּצְוָ֣ה הַ⁠זֹּ֑את לִֽ⁠הְי֤וֹת בְּרִיתִ⁠י֙ אֶת־לֵוִ֔י אָמַ֖ר יְהוָ֥ה צְבָאֽוֹת׃","wiֽ⁠ydaʻĕţė֕m ki֚̇y şǐlȧ֣ẖĕţi̇y ʼàléy⁠ke֔m ʼé֖ţ ha⁠mi̇ẕĕwá֣h ha⁠zò֑̇ʼţ liֽ⁠hĕy֤wòţ bĕ̇riyţi⁠y֙ ʼeţ-léwi֔y ʼáma֖r yĕhwá֥h ẕĕbáʼֽwòţ׃"],[2,5,"בְּרִיתִ֣⁠י ׀ הָיְתָ֣ה אִתּ֗⁠וֹ הַֽ⁠חַיִּים֙ וְ⁠הַ֨⁠שָּׁל֔וֹם וָ⁠אֶתְּנֵֽ⁠ם־ל֥⁠וֹ מוֹרָ֖א וַ⁠יִּֽירָאֵ֑⁠נִי וּ⁠מִ⁠פְּנֵ֥י שְׁמִ֖⁠י נִחַ֥ת הֽוּא׃","bĕ̇riyţi֣⁠y ׀ háyĕţá֣h ʼiţ̇֗⁠wò haֽ⁠ẖayi̇ym֙ wĕ⁠ha֨⁠şá̇̌l֔wòm wá⁠ʼeţĕ̇néֽ⁠m-l֥⁠wò mwòrá֖ʼ wa⁠yiֽ̇yráʼé֑⁠niy ẇ⁠mi⁠pĕ̇né֥y şĕ̌mi֖⁠y niẖa֥ţ hֽẇʼ׃"],[2,6,"תּוֹרַ֤ת אֱמֶת֙ הָיְתָ֣ה בְּ⁠פִ֔י⁠הוּ וְ⁠עַוְלָ֖ה לֹא־נִמְצָ֣א בִ⁠שְׂפָתָ֑י⁠ו בְּ⁠שָׁל֤וֹם וּ⁠בְ⁠מִישׁוֹר֙ הָלַ֣ךְ אִתִּ֔⁠י וְ⁠רַבִּ֖ים הֵשִׁ֥יב מֵ⁠עָוֺֽן׃","ţ̇wòra֤ţ ʼèmeţ֙ háyĕţá֣h bĕ̇⁠pi֔y⁠hẇ wĕ⁠ʻawĕlá֖h lòʼ-nimĕẕá֣ʼ bi⁠şĕ̂páţá֑y⁠w bĕ̇⁠şá̌l֤wòm ẇ⁠bĕ⁠miyş̌wòr֙ hála֣kĕ ʼiţi̇֔⁠y wĕ⁠rabi֖̇ym héşǐ֥yb mé⁠ʻáwֺֽn׃"],[2,7,"כִּֽי־שִׂפְתֵ֤י כֹהֵן֙ יִשְׁמְרוּ־דַ֔עַת וְ⁠תוֹרָ֖ה יְבַקְשׁ֣וּ מִ⁠פִּ֑י⁠הוּ כִּ֛י מַלְאַ֥ךְ יְהוָֽה־צְבָא֖וֹת הֽוּא׃","kiֽ̇y-şîpĕţé֤y kòhén֙ yişĕ̌mĕrẇ-da֔ʻaţ wĕ⁠ţwòrá֖h yĕbaqĕş֣̌ẇ mi⁠pi֑̇y⁠hẇ ki֛̇y malĕʼa֥kĕ yĕhwáֽh-ẕĕbáʼ֖wòţ hֽẇʼ׃"],[2,8,"וְ⁠אַתֶּם֙ סַרְתֶּ֣ם מִן־הַ⁠דֶּ֔רֶךְ הִכְשַׁלְתֶּ֥ם רַבִּ֖ים בַּ⁠תּוֹרָ֑ה שִֽׁחַתֶּם֙ בְּרִ֣ית הַ⁠לֵּוִ֔י אָמַ֖ר יְהוָ֥ה צְבָאֽוֹת׃","wĕ⁠ʼaţėm֙ sarĕţė֣m min-ha⁠dė֔rekĕ hikĕşǎlĕţė֥m rabi֖̇ym bȧ⁠ţ̇wòrá֑h şǐֽẖaţėm֙ bĕ̇ri֣yţ ha⁠lé̇wi֔y ʼáma֖r yĕhwá֥h ẕĕbáʼֽwòţ׃"],[2,9,"וְ⁠גַם־אֲנִ֞י נָתַ֧תִּי אֶתְ⁠כֶ֛ם נִבְזִ֥ים וּ⁠שְׁפָלִ֖ים לְ⁠כָל־הָ⁠עָ֑ם כְּ⁠פִ֗י אֲשֶׁ֤ר אֵֽינְ⁠כֶם֙ שֹׁמְרִ֣ים אֶת־דְּרָכַ֔⁠י וְ⁠נֹשְׂאִ֥ים פָּנִ֖ים בַּ⁠תּוֹרָֽה׃פ","wĕ⁠gam-ʼàni֞y náţa֧ţi̇y ʼeţĕ⁠ke֛m nibĕzi֥ym ẇ⁠şĕ̌páli֖ym lĕ⁠kál-há⁠ʻá֑m kĕ̇⁠pi֗y ʼàşě֤r ʼéֽynĕ⁠kem֙ şò̌mĕri֣ym ʼeţ-dĕ̇ráka֔⁠y wĕ⁠nòşĕ̂ʼi֥ym pá̇ni֖ym bȧ⁠ţ̇wòráֽh׃p"],[2,10,"הֲ⁠ל֨וֹא אָ֤ב אֶחָד֙ לְ⁠כֻלָּ֔⁠נוּ הֲ⁠ל֛וֹא אֵ֥ל אֶֽחָ֖ד בְּרָאָ֑⁠נוּ מַדּ֗וּעַ נִבְגַּד֙ אִ֣ישׁ בְּ⁠אָחִ֔י⁠ו לְ⁠חַלֵּ֖ל בְּרִ֥ית אֲבֹתֵֽי⁠נוּ׃","hà⁠l֨wòʼ ʼá֤b ʼeẖád֙ lĕ⁠kulá̇֔⁠nẇ hà⁠l֛wòʼ ʼé֥l ʼeֽẖá֖d bĕ̇ráʼá֑⁠nẇ maḋ֗ẇʻa nibĕgȧd֙ ʼi֣yş̌ bĕ̇⁠ʼáẖi֔y⁠w lĕ⁠ẖalé֖̇l bĕ̇ri֥yţ ʼàbòţéֽy⁠nẇ׃"],[2,11,"בָּגְדָ֣ה יְהוּדָ֔ה וְ⁠תוֹעֵבָ֛ה נֶעֶשְׂתָ֥ה בְ⁠יִשְׂרָאֵ֖ל וּ⁠בִ⁠ירֽוּשָׁלִָ֑ם כִּ֣י ׀ חִלֵּ֣ל יְהוּדָ֗ה קֹ֤דֶשׁ יְהוָה֙ אֲשֶׁ֣ר אָהֵ֔ב וּ⁠בָעַ֖ל בַּת־אֵ֥ל נֵכָֽר׃","bá̇gĕdá֣h yĕhẇdá֔h wĕ⁠ţwòʻébá֛h neʻeşĕ̂ţá֥h bĕ⁠yişĕ̂ráʼé֖l ẇ⁠bi⁠yrֽẇşá̌liá֑m ki֣̇y ׀ ẖilé֣̇l yĕhẇdá֗h qò֤deş̌ yĕhwáh֙ ʼàşě֣r ʼáhé֔b ẇ⁠báʻa֖l bȧţ-ʼé֥l nékáֽr׃"],[2,12,"יַכְרֵ֨ת יְהוָ֜ה לָ⁠אִ֨ישׁ אֲשֶׁ֤ר יַעֲשֶׂ֨⁠נָּה֙ עֵ֣ר וְ⁠עֹנֶ֔ה מֵ⁠אָהֳלֵ֖י יַֽעֲקֹ֑ב וּ⁠מַגִּ֣ישׁ מִנְחָ֔ה לַֽ⁠יהוָ֖ה צְבָאֽוֹת׃פ","yakĕré֨ţ yĕhwá֜h lá⁠ʼi֨yş̌ ʼàşě֤r yaʻàşê֨⁠ná̇h֙ ʻé֣r wĕ⁠ʻòne֔h mé⁠ʼáholé֖y yaֽʻàqò֑b ẇ⁠magi֣̇yş̌ minĕẖá֔h laֽ⁠yhwá֖h ẕĕbáʼֽwòţ׃p"],[2,13,"וְ⁠זֹאת֙ שֵׁנִ֣ית תַּֽעֲשׂ֔וּ כַּסּ֤וֹת דִּמְעָה֙ אֶת־מִזְבַּ֣ח יְהוָ֔ה בְּכִ֖י וַֽ⁠אֲנָקָ֑ה מֵ⁠אֵ֣ין ע֗וֹד פְּנוֹת֙ אֶל־הַ⁠מִּנְחָ֔ה וְ⁠לָ⁠קַ֥חַת רָצ֖וֹן מִ⁠יֶּדְ⁠כֶֽם׃","wĕ⁠zòʼţ֙ şé̌ni֣yţ ţȧֽʻàş̂֔ẇ kȧṡ֤wòţ di̇mĕʻáh֙ ʼeţ-mizĕbȧ֣ẖ yĕhwá֔h bĕ̇ki֖y waֽ⁠ʼànáqá֑h mé⁠ʼé֣yn ʻ֗wòd pĕ̇nwòţ֙ ʼel-ha⁠mi̇nĕẖá֔h wĕ⁠lá⁠qa֥ẖaţ ráẕ֖wòn mi⁠yėdĕ⁠keֽm׃"],[2,14,"וַ⁠אֲמַרְתֶּ֖ם עַל־מָ֑ה עַ֡ל כִּי־יְהוָה֩ הֵעִ֨יד בֵּינְ⁠ךָ֜ וּ⁠בֵ֣ין ׀ אֵ֣שֶׁת נְעוּרֶ֗י⁠ךָ אֲשֶׁ֤ר אַתָּה֙ בָּגַ֣דְתָּה בָּ֔⁠הּ וְ⁠הִ֥יא חֲבֶרְתְּ⁠ךָ֖ וְ⁠אֵ֥שֶׁת בְּרִיתֶֽ⁠ךָ׃","wa⁠ʼàmarĕţė֖m ʻal-má֑h ʻa֡l ki̇y-yĕhwáh֩ héʻi֨yd bé̇ynĕ⁠ká֜ ẇ⁠bé֣yn ׀ ʼé֣şěţ nĕʻẇre֗y⁠ká ʼàşě֤r ʼaţá̇h֙ bá̇ga֣dĕţá̇h bá̇֔⁠ḣ wĕ⁠hi֥yʼ ẖàberĕţĕ̇⁠ká֖ wĕ⁠ʼé֥şěţ bĕ̇riyţeֽ⁠ká׃"],[2,15,"וְ⁠לֹא־אֶחָ֣ד עָשָׂ֗ה וּ⁠שְׁאָ֥ר ר֨וּחַ֙ ל֔⁠וֹ וּ⁠מָה֙ הָֽ⁠אֶחָ֔ד מְבַקֵּ֖שׁ זֶ֣רַע אֱלֹהִ֑ים וְ⁠נִשְׁמַרְתֶּם֙ בְּ⁠ר֣וּחֲ⁠כֶ֔ם וּ⁠בְ⁠אֵ֥שֶׁת נְעוּרֶ֖י⁠ךָ אַל־יִבְגֹּֽד׃","wĕ⁠lòʼ-ʼeẖá֣d ʻáşá̂֗h ẇ⁠şĕ̌ʼá֥r r֨ẇẖa֙ l֔⁠wò ẇ⁠máh֙ háֽ⁠ʼeẖá֔d mĕbaqé֖̇ş̌ ze֣raʻ ʼèlòhi֑ym wĕ⁠nişĕ̌marĕţėm֙ bĕ̇⁠r֣ẇẖà⁠ke֔m ẇ⁠bĕ⁠ʼé֥şěţ nĕʻẇre֖y⁠ká ʼal-yibĕgòֽ̇d׃"],[2,16,"כִּֽי־שָׂנֵ֣א שַׁלַּ֗ח אָמַ֤ר יְהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל וְ⁠כִסָּ֤ה חָמָס֙ עַל־לְבוּשׁ֔⁠וֹ אָמַ֖ר יְהוָ֣ה צְבָא֑וֹת וְ⁠נִשְׁמַרְתֶּ֥ם בְּ⁠רוּחֲ⁠כֶ֖ם וְ⁠לֹ֥א תִבְגֹּֽדוּ׃ס","kiֽ̇y-şá̂né֣ʼ şǎlȧ֗ẖ ʼáma֤r yĕhwáh֙ ʼèlòhé֣y yişĕ̂ráʼé֔l wĕ⁠kisá֤̇h ẖámás֙ ʻal-lĕbẇş̌֔⁠wò ʼáma֖r yĕhwá֣h ẕĕbáʼ֑wòţ wĕ⁠nişĕ̌marĕţė֥m bĕ̇⁠rẇẖà⁠ke֖m wĕ⁠lò֥ʼ ţibĕgòֽ̇dẇ׃s"],[2,17,"הוֹגַעְתֶּ֤ם יְהוָה֙ בְּ⁠דִבְרֵי⁠כֶ֔ם וַ⁠אֲמַרְתֶּ֖ם בַּ⁠מָּ֣ה הוֹגָ֑עְנוּ בֶּ⁠אֱמָרְ⁠כֶ֗ם כָּל־עֹ֨שֵׂה רָ֜ע ט֣וֹב ׀ בְּ⁠עֵינֵ֣י יְהוָ֗ה וּ⁠בָ⁠הֶם֙ ה֣וּא חָפֵ֔ץ א֥וֹ אַיֵּ֖ה אֱלֹהֵ֥י הַ⁠מִּשְׁפָּֽט׃","hwògaʻĕţė֤m yĕhwáh֙ bĕ̇⁠dibĕréy⁠ke֔m wa⁠ʼàmarĕţė֖m bȧ⁠má֣̇h hwògá֑ʻĕnẇ bė⁠ʼèmárĕ⁠ke֗m ká̇l-ʻò֨şé̂h rá֜ʻ t֣wòb ׀ bĕ̇⁠ʻéyné֣y yĕhwá֗h ẇ⁠bá⁠hem֙ h֣ẇʼ ẖápé֔ẕ ʼ֥wò ʼayé֖̇h ʼèlòhé֥y ha⁠mi̇şĕ̌páֽ̇t׃"],[3,1,"הִנְ⁠נִ֤י שֹׁלֵחַ֙ מַלְאָכִ֔⁠י וּ⁠פִנָּה־דֶ֖רֶךְ לְ⁠פָנָ֑⁠י וּ⁠פִתְאֹם֩ יָב֨וֹא אֶל־הֵיכָל֜⁠וֹ הָ⁠אָד֣וֹן ׀ אֲשֶׁר־אַתֶּ֣ם מְבַקְשִׁ֗ים וּ⁠מַלְאַ֨ךְ הַ⁠בְּרִ֜ית אֲשֶׁר־אַתֶּ֤ם חֲפֵצִים֙ הִנֵּה־בָ֔א אָמַ֖ר יְהוָ֥ה צְבָאֽוֹת׃","hinĕ⁠ni֤y şò̌léẖa֙ malĕʼáki֔⁠y ẇ⁠piná̇h-de֖rekĕ lĕ⁠páná֑⁠y ẇ⁠piţĕʼòm֩ yáb֨wòʼ ʼel-héykál֜⁠wò há⁠ʼád֣wòn ׀ ʼàşěr-ʼaţė֣m mĕbaqĕşǐ֗ym ẇ⁠malĕʼa֨kĕ ha⁠bĕ̇ri֜yţ ʼàşěr-ʼaţė֤m ẖàpéẕiym֙ hiné̇h-bá֔ʼ ʼáma֖r yĕhwá֥h ẕĕbáʼֽwòţ׃"],[3,2,"וּ⁠מִ֤י מְכַלְכֵּל֙ אֶת־י֣וֹם בּוֹא֔⁠וֹ וּ⁠מִ֥י הָ⁠עֹמֵ֖ד בְּ⁠הֵרָֽאוֹת֑⁠וֹ כִּֽי־הוּא֙ כְּ⁠אֵ֣שׁ מְצָרֵ֔ף וּ⁠כְ⁠בֹרִ֖ית מְכַבְּסִֽים׃","ẇ⁠mi֤y mĕkalĕké̇l֙ ʼeţ-y֣wòm ḃwòʼ֔⁠wò ẇ⁠mi֥y há⁠ʻòmé֖d bĕ̇⁠héráֽʼwòţ֑⁠wò kiֽ̇y-hẇʼ֙ kĕ̇⁠ʼé֣ş̌ mĕẕáré֔p ẇ⁠kĕ⁠bòri֖yţ mĕkabĕ̇siֽym׃"],[3,3,"וְ⁠יָשַׁ֨ב מְצָרֵ֤ף וּ⁠מְטַהֵר֙ כֶּ֔סֶף וְ⁠טִהַ֤ר אֶת־בְּנֵֽי־לֵוִי֙ וְ⁠זִקַּ֣ק אֹתָ֔⁠ם כַּ⁠זָּהָ֖ב וְ⁠כַ⁠כָּ֑סֶף וְ⁠הָיוּ֙ לַֽ⁠יהוָ֔ה מַגִּישֵׁ֥י מִנְחָ֖ה בִּ⁠צְדָקָֽה׃","wĕ⁠yáşǎ֨b mĕẕáré֤p ẇ⁠mĕtahér֙ kė֔sep wĕ⁠tiha֤r ʼeţ-bĕ̇néֽy-léwiy֙ wĕ⁠ziqȧ֣q ʼòţá֔⁠m kȧ⁠zá̇há֖b wĕ⁠ka⁠ká֑̇sep wĕ⁠háyẇ֙ laֽ⁠yhwá֔h magi̇yşé֥̌y minĕẖá֖h bi̇⁠ẕĕdáqáֽh׃"],[3,4,"וְ⁠עָֽרְבָה֙ לַֽ⁠יהוָ֔ה מִנְחַ֥ת יְהוּדָ֖ה וִ⁠ירֽוּשָׁלִָ֑ם כִּ⁠ימֵ֣י עוֹלָ֔ם וּ⁠כְ⁠שָׁנִ֖ים קַדְמֹנִיּֽוֹת׃","wĕ⁠ʻáֽrĕbáh֙ laֽ⁠yhwá֔h minĕẖa֥ţ yĕhẇdá֖h wi⁠yrֽẇşá̌liá֑m ki̇⁠ymé֣y ʻwòlá֔m ẇ⁠kĕ⁠şá̌ni֖ym qadĕmòniẏֽwòţ׃"],[3,5,"וְ⁠קָרַבְתִּ֣י אֲלֵי⁠כֶם֮ לַ⁠מִּשְׁפָּט֒ וְ⁠הָיִ֣יתִי ׀ עֵ֣ד מְמַהֵ֗ר בַּֽ⁠מְכַשְּׁפִים֙ וּ⁠בַ⁠מְנָ֣אֲפִ֔ים וּ⁠בַ⁠נִּשְׁבָּעִ֖ים לַ⁠שָּׁ֑קֶר וּ⁠בְ⁠עֹשְׁקֵ֣י שְׂכַר־שָׂ֠כִיר אַלְמָנָ֨ה וְ⁠יָת֤וֹם וּ⁠מַטֵּי־גֵר֙ וְ⁠לֹ֣א יְרֵא֔וּ⁠נִי אָמַ֖ר יְהוָ֥ה צְבָאֽוֹת׃","wĕ⁠qárabĕţi֣̇y ʼàléy⁠kem֮ la⁠mi̇şĕ̌pá̇t֒ wĕ⁠háyi֣yţiy ׀ ʻé֣d mĕmahé֗r bȧֽ⁠mĕkaşĕ̇̌piym֙ ẇ⁠ba⁠mĕná֣ʼàpi֔ym ẇ⁠ba⁠ni̇şĕ̌bá̇ʻi֖ym la⁠şá֑̇̌qer ẇ⁠bĕ⁠ʻòşĕ̌qé֣y şĕ̂kar-şá̂֠kiyr ʼalĕmáná֨h wĕ⁠yáţ֤wòm ẇ⁠maté̇y-gér֙ wĕ⁠lò֣ʼ yĕréʼ֔ẇ⁠niy ʼáma֖r yĕhwá֥h ẕĕbáʼֽwòţ׃"],[3,6,"כִּ֛י אֲנִ֥י יְהוָ֖ה לֹ֣א שָׁנִ֑יתִי וְ⁠אַתֶּ֥ם בְּנֵֽי־יַעֲקֹ֖ב לֹ֥א כְלִיתֶֽם׃","ki֛̇y ʼàni֥y yĕhwá֖h lò֣ʼ şá̌ni֑yţiy wĕ⁠ʼaţė֥m bĕ̇néֽy-yaʻàqò֖b lò֥ʼ kĕliyţeֽm׃"],[3,7,"לְ⁠מִ⁠ימֵ֨י אֲבֹתֵי⁠כֶ֜ם סַרְתֶּ֤ם מֵֽ⁠חֻקַּ⁠י֙ וְ⁠לֹ֣א שְׁמַרְתֶּ֔ם שׁ֤וּבוּ אֵלַ⁠י֙ וְ⁠אָשׁ֣וּבָה אֲלֵי⁠כֶ֔ם אָמַ֖ר יְהוָ֣ה צְבָא֑וֹת וַ⁠אֲמַרְתֶּ֖ם בַּ⁠מֶּ֥ה נָשֽׁוּב׃","lĕ⁠mi⁠ymé֨y ʼàbòţéy⁠ke֜m sarĕţė֤m méֽ⁠ẖuqȧ⁠y֙ wĕ⁠lò֣ʼ şĕ̌marĕţė֔m ş֤̌ẇbẇ ʼéla⁠y֙ wĕ⁠ʼáş֣̌ẇbáh ʼàléy⁠ke֔m ʼáma֖r yĕhwá֣h ẕĕbáʼ֑wòţ wa⁠ʼàmarĕţė֖m bȧ⁠mė֥h náşֽ̌ẇb׃"],[3,8,"הֲ⁠יִקְבַּ֨ע אָדָ֜ם אֱלֹהִ֗ים כִּ֤י אַתֶּם֙ קֹבְעִ֣ים אֹתִ֔⁠י וַ⁠אֲמַרְתֶּ֖ם בַּ⁠מֶּ֣ה קְבַעֲנ֑וּ⁠ךָ הַֽ⁠מַּעֲשֵׂ֖ר וְ⁠הַ⁠תְּרוּמָֽה׃","hà⁠yiqĕbȧ֨ʻ ʼádá֜m ʼèlòhi֗ym ki֤̇y ʼaţėm֙ qòbĕʻi֣ym ʼòţi֔⁠y wa⁠ʼàmarĕţė֖m bȧ⁠mė֣h qĕbaʻàn֑ẇ⁠ká haֽ⁠mȧʻàşé֖̂r wĕ⁠ha⁠ţĕ̇rẇmáֽh׃"],[3,9,"בַּ⁠מְּאֵרָה֙ אַתֶּ֣ם נֵֽאָרִ֔ים וְ⁠אֹתִ֖⁠י אַתֶּ֣ם קֹבְעִ֑ים הַ⁠גּ֖וֹי כֻּלּֽ⁠וֹ׃","bȧ⁠mĕ̇ʼéráh֙ ʼaţė֣m néֽʼári֔ym wĕ⁠ʼòţi֖⁠y ʼaţė֣m qòbĕʻi֑ym ha⁠ġ֖wòy ku̇lֽ̇⁠wò׃"],[3,10,"הָבִ֨יאוּ אֶת־כָּל־הַֽ⁠מַּעֲשֵׂ֜ר אֶל־בֵּ֣ית הָ⁠אוֹצָ֗ר וִ⁠יהִ֥י טֶ֨רֶף֙ בְּ⁠בֵיתִ֔⁠י וּ⁠בְחָנ֤וּ⁠נִי נָא֙ בָּ⁠זֹ֔את אָמַ֖ר יְהוָ֣ה צְבָא֑וֹת אִם־לֹ֧א אֶפְתַּ֣ח לָ⁠כֶ֗ם אֵ֚ת אֲרֻבּ֣וֹת הַ⁠שָּׁמַ֔יִם וַ⁠הֲרִיקֹתִ֥י לָ⁠כֶ֛ם בְּרָכָ֖ה עַד־בְּלִי־דָֽי׃","hábi֨yʼẇ ʼeţ-ká̇l-haֽ⁠mȧʻàşé̂֜r ʼel-bé֣̇yţ há⁠ʼwòẕá֗r wi⁠yhi֥y te֨rep֙ bĕ̇⁠béyţi֔⁠y ẇ⁠bĕẖán֤ẇ⁠niy náʼ֙ bá̇⁠zò֔ʼţ ʼáma֖r yĕhwá֣h ẕĕbáʼ֑wòţ ʼim-lò֧ʼ ʼepĕţȧ֣ẖ lá⁠ke֗m ʼé֚ţ ʼàruḃ֣wòţ ha⁠şá̇̌ma֔yim wa⁠hàriyqòţi֥y lá⁠ke֛m bĕ̇ráká֖h ʻad-bĕ̇liy-dáֽy׃"],[3,11,"וְ⁠גָעַרְתִּ֤י לָ⁠כֶם֙ בָּֽ⁠אֹכֵ֔ל וְ⁠לֹֽא־יַשְׁחִ֥ת לָ⁠כֶ֖ם אֶת־פְּרִ֣י הָ⁠אֲדָמָ֑ה וְ⁠לֹא־תְשַׁכֵּ֨ל לָ⁠כֶ֤ם הַ⁠גֶּ֨פֶן֙ בַּ⁠שָּׂדֶ֔ה אָמַ֖ר יְהוָ֥ה צְבָאֽוֹת׃","wĕ⁠gáʻarĕţi֤̇y lá⁠kem֙ báֽ̇⁠ʼòké֔l wĕ⁠lòֽʼ-yaşĕ̌ẖi֥ţ lá⁠ke֖m ʼeţ-pĕ̇ri֣y há⁠ʼàdámá֑h wĕ⁠lòʼ-ţĕşǎké̇֨l lá⁠ke֤m ha⁠gė֨pen֙ bȧ⁠şá̇̂de֔h ʼáma֖r yĕhwá֥h ẕĕbáʼֽwòţ׃"],[3,12,"וְ⁠אִשְּׁר֥וּ אֶתְ⁠כֶ֖ם כָּל־הַ⁠גּוֹיִ֑ם כִּֽי־תִהְי֤וּ אַתֶּם֙ אֶ֣רֶץ חֵ֔פֶץ אָמַ֖ר יְהוָ֥ה צְבָאֽוֹת׃ס","wĕ⁠ʼişĕ̇̌r֥ẇ ʼeţĕ⁠ke֖m ká̇l-ha⁠ġwòyi֑m kiֽ̇y-ţihĕy֤ẇ ʼaţėm֙ ʼe֣reẕ ẖé֔peẕ ʼáma֖r yĕhwá֥h ẕĕbáʼֽwòţ׃s"],[3,13,"חָזְק֥וּ עָלַ֛⁠י דִּבְרֵי⁠כֶ֖ם אָמַ֣ר יְהוָ֑ה וַ⁠אֲמַרְתֶּ֕ם מַה־נִּדְבַּ֖רְנוּ עָלֶֽי⁠ךָ׃","ẖázĕq֥ẇ ʻála֛⁠y di̇bĕréy⁠ke֖m ʼáma֣r yĕhwá֑h wa⁠ʼàmarĕţė֕m mah-ni̇dĕbȧ֖rĕnẇ ʻáleֽy⁠ká׃"],[3,14,"אֲמַרְתֶּ֕ם שָׁ֖וְא עֲבֹ֣ד אֱלֹהִ֑ים וּ⁠מַה־בֶּ֗צַע כִּ֤י שָׁמַ֨רְנוּ֙ מִשְׁמַרְתּ֔⁠וֹ וְ⁠כִ֤י הָלַ֨כְנוּ֙ קְדֹ֣רַנִּ֔ית מִ⁠פְּנֵ֖י יְהוָ֥ה צְבָאֽוֹת׃","ʼàmarĕţė֕m şá֖̌wĕʼ ʻàbò֣d ʼèlòhi֑ym ẇ⁠mah-bė֗ẕaʻ ki֤̇y şá̌ma֨rĕnẇ֙ mişĕ̌marĕţ̇֔⁠wò wĕ⁠ki֤y hála֨kĕnẇ֙ qĕdò֣rani̇֔yţ mi⁠pĕ̇né֖y yĕhwá֥h ẕĕbáʼֽwòţ׃"],[3,15,"וְ⁠עַתָּ֕ה אֲנַ֖חְנוּ מְאַשְּׁרִ֣ים זֵדִ֑ים גַּם־נִבְנוּ֙ עֹשֵׂ֣י רִשְׁעָ֔ה גַּ֧ם בָּחֲנ֛וּ אֱלֹהִ֖ים וַ⁠יִּמָּלֵֽטוּ׃","wĕ⁠ʻaţá̇֕h ʼàna֖ẖĕnẇ mĕʼaşĕ̇̌ri֣ym zédi֑ym gȧm-nibĕnẇ֙ ʻòşé֣̂y rişĕ̌ʻá֔h gȧ֧m bá̇ẖàn֛ẇ ʼèlòhi֖ym wa⁠yi̇má̇léֽtẇ׃"],[3,16,"אָ֧ז נִדְבְּר֛וּ יִרְאֵ֥י יְהוָ֖ה אִ֣ישׁ אֶת־רֵעֵ֑⁠הוּ וַ⁠יַּקְשֵׁ֤ב יְהוָה֙ וַ⁠יִּשְׁמָ֔ע וַ֠⁠יִּכָּתֵב סֵ֣פֶר זִכָּר֤וֹן לְ⁠פָנָי⁠ו֙ לְ⁠יִרְאֵ֣י יְהוָ֔ה וּ⁠לְ⁠חֹשְׁבֵ֖י שְׁמֽ⁠וֹ׃","ʼá֧z nidĕbĕ̇r֛ẇ yirĕʼé֥y yĕhwá֖h ʼi֣yş̌ ʼeţ-réʻé֑⁠hẇ wa⁠yȧqĕşé֤̌b yĕhwáh֙ wa⁠yi̇şĕ̌má֔ʻ wa֠⁠yi̇ká̇ţéb sé֣per ziká̇r֤wòn lĕ⁠pánáy⁠w֙ lĕ⁠yirĕʼé֣y yĕhwá֔h ẇ⁠lĕ⁠ẖòşĕ̌bé֖y şĕ̌mֽ⁠wò׃"],[3,17,"וְ⁠הָ֣יוּ לִ֗⁠י אָמַר֙ יְהוָ֣ה צְבָא֔וֹת לַ⁠יּ֕וֹם אֲשֶׁ֥ר אֲנִ֖י עֹשֶׂ֣ה סְגֻלָּ֑ה וְ⁠חָמַלְתִּ֣י עֲלֵי⁠הֶ֔ם כַּֽ⁠אֲשֶׁר֙ יַחְמֹ֣ל אִ֔ישׁ עַל־בְּנ֖⁠וֹ הָ⁠עֹבֵ֥ד אֹתֽ⁠וֹ׃","wĕ⁠há֣yẇ li֗⁠y ʼámar֙ yĕhwá֣h ẕĕbáʼ֔wòţ la⁠ẏ֕wòm ʼàşě֥r ʼàni֖y ʻòşê֣h sĕgulá֑̇h wĕ⁠ẖámalĕţi֣̇y ʻàléy⁠he֔m kȧֽ⁠ʼàşěr֙ yaẖĕmò֣l ʼi֔yş̌ ʻal-bĕ̇n֖⁠wò há⁠ʻòbé֥d ʼòţֽ⁠wò׃"],[3,18,"וְ⁠שַׁבְתֶּם֙ וּ⁠רְאִיתֶ֔ם בֵּ֥ין צַדִּ֖יק לְ⁠רָשָׁ֑ע בֵּ֚ין עֹבֵ֣ד אֱלֹהִ֔ים לַ⁠אֲשֶׁ֖ר לֹ֥א עֲבָדֽ⁠וֹ׃ס","wĕ⁠şǎbĕţėm֙ ẇ⁠rĕʼiyţe֔m bé֥̇yn ẕadi֖̇yq lĕ⁠ráşá֑̌ʻ bé֚̇yn ʻòbé֣d ʼèlòhi֔ym la⁠ʼàşě֖r lò֥ʼ ʻàbádֽ⁠wò׃s"],[4,1,"כִּֽי־הִנֵּ֤ה הַ⁠יּוֹם֙ בָּ֔א בֹּעֵ֖ר כַּ⁠תַּנּ֑וּר וְ⁠הָי֨וּ כָל־זֵדִ֜ים וְ⁠כָל־עֹשֵׂ֤ה רִשְׁעָה֙ קַ֔שׁ וְ⁠לִהַ֨ט אֹתָ֜⁠ם הַ⁠יּ֣וֹם הַ⁠בָּ֗א אָמַר֙ יְהוָ֣ה צְבָא֔וֹת אֲשֶׁ֛ר לֹא־יַעֲזֹ֥ב לָ⁠הֶ֖ם שֹׁ֥רֶשׁ וְ⁠עָנָֽף׃","kiֽ̇y-hiné֤̇h ha⁠ẏwòm֙ bá̇֔ʼ bò̇ʻé֖r kȧ⁠ţȧṅ֑ẇr wĕ⁠háy֨ẇ kál-zédi֜ym wĕ⁠kál-ʻòşé֤̂h rişĕ̌ʻáh֙ qa֔ş̌ wĕ⁠liha֨t ʼòţá֜⁠m ha⁠ẏ֣wòm ha⁠bá̇֗ʼ ʼámar֙ yĕhwá֣h ẕĕbáʼ֔wòţ ʼàşě֛r lòʼ-yaʻàzò֥b lá⁠he֖m şò֥̌reş̌ wĕ⁠ʻánáֽp׃"],[4,2,"וְ⁠זָרְחָ֨ה לָ⁠כֶ֜ם יִרְאֵ֤י שְׁמִ⁠י֙ שֶׁ֣מֶשׁ צְדָקָ֔ה וּ⁠מַרְפֵּ֖א בִּ⁠כְנָפֶ֑י⁠הָ וִֽ⁠יצָאתֶ֥ם וּ⁠פִשְׁתֶּ֖ם כְּ⁠עֶגְלֵ֥י מַרְבֵּֽק׃","wĕ⁠zárĕẖá֨h lá⁠ke֜m yirĕʼé֤y şĕ̌mi⁠y֙ şě֣meş̌ ẕĕdáqá֔h ẇ⁠marĕpé֖̇ʼ bi̇⁠kĕnápe֑y⁠há wiֽ⁠yẕáʼţe֥m ẇ⁠pişĕ̌ţė֖m kĕ̇⁠ʻegĕlé֥y marĕbéֽ̇q׃"],[4,3,"וְ⁠עַסּוֹתֶ֣ם רְשָׁעִ֔ים כִּֽי־יִהְי֣וּ אֵ֔פֶר תַּ֖חַת כַּפּ֣וֹת רַגְלֵי⁠כֶ֑ם בַּ⁠יּוֹם֙ אֲשֶׁ֣ר אֲנִ֣י עֹשֶׂ֔ה אָמַ֖ר יְהוָ֥ה צְבָאֽוֹת׃פ","wĕ⁠ʻaṡwòţe֣m rĕşá̌ʻi֔ym kiֽ̇y-yihĕy֣ẇ ʼé֔per ţȧ֖ẖaţ kȧṗ֣wòţ ragĕléy⁠ke֑m bȧ⁠ẏwòm֙ ʼàşě֣r ʼàni֣y ʻòşê֔h ʼáma֖r yĕhwá֥h ẕĕbáʼֽwòţ׃p"],[4,4,"זִכְר֕וּ תּוֹרַ֖ת מֹשֶׁ֣ה עַבְדִּ֑⁠י אֲשֶׁר֩ צִוִּ֨יתִי אוֹת֤⁠וֹ בְ⁠חֹרֵב֙ עַל־כָּל־יִשְׂרָאֵ֔ל חֻקִּ֖ים וּ⁠מִשְׁפָּטִֽים׃","zikĕr֕ẇ ţ̇wòra֖ţ mòşě֣h ʻabĕdi֑̇⁠y ʼàşěr֩ ẕiwi̇֨yţiy ʼwòţ֤⁠wò bĕ⁠ẖòréb֙ ʻal-ká̇l-yişĕ̂ráʼé֔l ẖuqi֖̇ym ẇ⁠mişĕ̌pá̇tiֽym׃"],[4,5,"הִנֵּ֤ה אָֽנֹכִי֙ שֹׁלֵ֣חַ לָ⁠כֶ֔ם אֵ֖ת אֵלִיָּ֣ה הַ⁠נָּבִ֑יא לִ⁠פְנֵ֗י בּ֚וֹא י֣וֹם יְהוָ֔ה הַ⁠גָּד֖וֹל וְ⁠הַ⁠נּוֹרָֽא׃","hiné֤̇h ʼáֽnòkiy֙ şò̌lé֣ẖa lá⁠ke֔m ʼé֖ţ ʼéliyá֣̇h ha⁠ná̇bi֑yʼ li⁠pĕné֗y ḃ֚wòʼ y֣wòm yĕhwá֔h ha⁠gá̇d֖wòl wĕ⁠ha⁠ṅwòráֽʼ׃"],[4,6,"וְ⁠הֵשִׁ֤יב לֵב־אָבוֹת֙ עַל־בָּנִ֔ים וְ⁠לֵ֥ב בָּנִ֖ים עַל־אֲבוֹתָ֑⁠ם פֶּן־אָב֕וֹא וְ⁠הִכֵּיתִ֥י אֶת־הָ⁠אָ֖רֶץ חֵֽרֶם׃","wĕ⁠héşǐ֤yb léb-ʼábwòţ֙ ʻal-bá̇ni֔ym wĕ⁠lé֥b bá̇ni֖ym ʻal-ʼàbwòţá֑⁠m pėn-ʼáb֕wòʼ wĕ⁠hiké̇yţi֥y ʼeţ-há⁠ʼá֖reẕ ẖéֽrem׃"]],"fra-lsg1910":[[1,1,"Oracle, parole de l'Éternel à Israël par Malachie.","Oracle, parole de l'Éternel à Israël par Malachie."],[1,2,"Je vous ai aimés, dit l'Éternel. Et vous dites: En quoi nous as-tu aimés? Ésaü n'est-il pas frère de Jacob? dit l'Éternel. Cependant j'ai aimé Jacob,","Je vous ai aimés, dit l'Éternel. Et vous dites: En quoi nous as-tu aimés? Ésaü n'est-il pas frère de Jacob? dit l'Éternel. Cependant j'ai aimé Jacob,"],[1,3,"Et j'ai eu de la haine pour Ésaü, J'ai fait de ses montagnes une solitude, J'ai livré son héritage aux chacals du désert.","Et j'ai eu de la haine pour Ésaü, J'ai fait de ses montagnes une solitude, J'ai livré son héritage aux chacals du désert."],[1,4,"Si Édom dit: Nous sommes détruits, Nous relèverons les ruines! Ainsi parle l'Éternel des armées: Qu'ils bâtissent, je renverserai, Et on les appellera pays de la méchanceté, Peuple contre lequel l'Éternel est irrité pour toujours.","Si Édom dit: Nous sommes détruits, Nous relèverons les ruines! Ainsi parle l'Éternel des armées: Qu'ils bâtissent, je renverserai, Et on les appellera pays de la méchanceté, Peuple contre lequel l'Éternel est irrité pour toujours."],[1,5,"Vos yeux le verront, Et vous direz: Grand est l'Éternel Par delà les frontières d'Israël!","Vos yeux le verront, Et vous direz: Grand est l'Éternel Par delà les frontières d'Israël!"],[1,6,"Un fils honore son père, et un serviteur son maître. Si je suis père, où est l'honneur qui m'est dû? Si je suis maître, où est la crainte qu'on a de moi? Dit l'Éternel des armées à vous, sacrificateurs, Qui méprisez mon nom, Et qui dites: En quoi avons-nous méprisé ton nom?","Un fils honore son père, et un serviteur son maître. Si je suis père, où est l'honneur qui m'est dû? Si je suis maître, où est la crainte qu'on a de moi? Dit l'Éternel des armées à vous, sacrificateurs, Qui méprisez mon nom, Et qui dites: En quoi avons-nous méprisé ton nom?"],[1,7,"Vous offrez sur mon autel des aliments impurs, Et vous dites: En quoi t'avons-nous profané? C'est en disant: La table de l'Éternel est méprisable!","Vous offrez sur mon autel des aliments impurs, Et vous dites: En quoi t'avons-nous profané? C'est en disant: La table de l'Éternel est méprisable!"],[1,8,"Quand vous offrez en sacrifice une bête aveugle, n'est-ce pas mal? Quand vous en offrez une boiteuse ou infirme, n'est-ce pas mal? Offre-la donc à ton gouverneur! Te recevra-t-il bien, te fera-t-il bon accueil? Dit l'Éternel des armées.","Quand vous offrez en sacrifice une bête aveugle, n'est-ce pas mal? Quand vous en offrez une boiteuse ou infirme, n'est-ce pas mal? Offre-la donc à ton gouverneur! Te recevra-t-il bien, te fera-t-il bon accueil? Dit l'Éternel des armées."],[1,9,"Priez Dieu maintenant, pour qu'il ait pitié de nous! C'est de vous que cela vient: Vous recevra-t-il favorablement? Dit l'Éternel des armées.","Priez Dieu maintenant, pour qu'il ait pitié de nous! C'est de vous que cela vient: Vous recevra-t-il favorablement? Dit l'Éternel des armées."],[1,10,"Lequel de vous fermera les portes, Pour que vous n'allumiez pas en vain le feu sur mon autel? Je ne prends aucun plaisir en vous, dit l'Éternel des armées, Et les offrandes de votre main ne me sont point agréables.","Lequel de vous fermera les portes, Pour que vous n'allumiez pas en vain le feu sur mon autel? Je ne prends aucun plaisir en vous, dit l'Éternel des armées, Et les offrandes de votre main ne me sont point agréables."],[1,11,"Car depuis le lever du soleil jusqu'à son couchant, Mon nom est grand parmi les nations, Et en tout lieu on brûle de l'encens en l'honneur de mon nom Et l'on présente des offrandes pures; Car grand est mon nom parmi les nations, Dit l'Éternel des armées.","Car depuis le lever du soleil jusqu'à son couchant, Mon nom est grand parmi les nations, Et en tout lieu on brûle de l'encens en l'honneur de mon nom Et l'on présente des offrandes pures; Car grand est mon nom parmi les nations, Dit l'Éternel des armées."],[1,12,"Mais vous, vous le profanez, En disant: La table de l'Éternel est souillée, Et ce qu'elle rapporte est un aliment méprisable.","Mais vous, vous le profanez, En disant: La table de l'Éternel est souillée, Et ce qu'elle rapporte est un aliment méprisable."],[1,13,"Vous dites: Quelle fatigue! et vous le dédaignez, Dit l'Éternel des armées; Et cependant vous amenez ce qui est dérobé, boiteux ou infirme, Et ce sont les offrandes que vous faites! Puis-je les agréer de vos mains? dit l'Éternel.","Vous dites: Quelle fatigue! et vous le dédaignez, Dit l'Éternel des armées; Et cependant vous amenez ce qui est dérobé, boiteux ou infirme, Et ce sont les offrandes que vous faites! Puis-je les agréer de vos mains? dit l'Éternel."],[1,14,"Maudit soit le trompeur qui a dans son troupeau un mâle, Et qui voue et sacrifie au Seigneur une bête chétive! Car je suis un grand roi, dit l'Éternel des armées, Et mon nom est redoutable parmi les nations.","Maudit soit le trompeur qui a dans son troupeau un mâle, Et qui voue et sacrifie au Seigneur une bête chétive! Car je suis un grand roi, dit l'Éternel des armées, Et mon nom est redoutable parmi les nations."],[2,1,"Maintenant, à vous cet ordre, sacrificateurs!","Maintenant, à vous cet ordre, sacrificateurs!"],[2,2,"Si vous n'écoutez pas, si vous ne prenez pas à coeur De donner gloire à mon nom, dit l'Éternel des armées, J'enverrai parmi vous la malédiction, et je maudirai vos bénédictions; Oui, je les maudirai, parce que vous ne l'avez pas à coeur.","Si vous n'écoutez pas, si vous ne prenez pas à coeur De donner gloire à mon nom, dit l'Éternel des armées, J'enverrai parmi vous la malédiction, et je maudirai vos bénédictions; Oui, je les maudirai, parce que vous ne l'avez pas à coeur."],[2,3,"Voici, je détruirai vos semences, Et je vous jetterai des excréments au visage, Les excréments des victimes que vous sacrifiez, Et on vous emportera avec eux.","Voici, je détruirai vos semences, Et je vous jetterai des excréments au visage, Les excréments des victimes que vous sacrifiez, Et on vous emportera avec eux."],[2,4,"Vous saurez alors que je vous ai adressé cet ordre, Afin que mon alliance avec Lévi subsiste, Dit l'Éternel des armées.","Vous saurez alors que je vous ai adressé cet ordre, Afin que mon alliance avec Lévi subsiste, Dit l'Éternel des armées."],[2,5,"Mon alliance avec lui était une alliance de vie et de paix, Ce que je lui accordai pour qu'il me craignît; Et il a eu pour moi de la crainte, Il a tremblé devant mon nom.","Mon alliance avec lui était une alliance de vie et de paix, Ce que je lui accordai pour qu'il me craignît; Et il a eu pour moi de la crainte, Il a tremblé devant mon nom."],[2,6,"La loi de la vérité était dans sa bouche, Et l'iniquité ne s'est point trouvée sur ses lèvres; Il a marché avec moi dans la paix et dans la droiture, Et il a détourné du mal beaucoup d'hommes.","La loi de la vérité était dans sa bouche, Et l'iniquité ne s'est point trouvée sur ses lèvres; Il a marché avec moi dans la paix et dans la droiture, Et il a détourné du mal beaucoup d'hommes."],[2,7,"Car les lèvres du sacrificateur doivent garder la science, Et c'est à sa bouche qu'on demande la loi, Parce qu'il est un envoyé de l'Éternel des armées.","Car les lèvres du sacrificateur doivent garder la science, Et c'est à sa bouche qu'on demande la loi, Parce qu'il est un envoyé de l'Éternel des armées."],[2,8,"Mais vous, vous vous êtes écartés de la voie, Vous avez fait de la loi une occasion de chute pour plusieurs, Vous avez violé l'alliance de Lévi, Dit l'Éternel des armées.","Mais vous, vous vous êtes écartés de la voie, Vous avez fait de la loi une occasion de chute pour plusieurs, Vous avez violé l'alliance de Lévi, Dit l'Éternel des armées."],[2,9,"Et moi, je vous rendrai méprisables et vils Aux yeux de tout le peuple, Parce que vous n'avez pas gardé mes voies, Et que vous avez égard à l'apparence des personnes Quand vous interprétez la loi.","Et moi, je vous rendrai méprisables et vils Aux yeux de tout le peuple, Parce que vous n'avez pas gardé mes voies, Et que vous avez égard à l'apparence des personnes Quand vous interprétez la loi."],[2,10,"N'avons-nous pas tous un seul père? N'est-ce pas un seul Dieu qui nous a créés? Pourquoi donc sommes-nous infidèles l'un envers l'autre, En profanant l'alliance de nos pères?","N'avons-nous pas tous un seul père? N'est-ce pas un seul Dieu qui nous a créés? Pourquoi donc sommes-nous infidèles l'un envers l'autre, En profanant l'alliance de nos pères?"],[2,11,"Juda s'est montré infidèle, Et une abomination a été commise en Israël et à Jérusalem; Car Juda a profané ce qui est consacré à l'Éternel, ce qu'aime l'Éternel, Il s'est uni à la fille d'un dieu étranger.","Juda s'est montré infidèle, Et une abomination a été commise en Israël et à Jérusalem; Car Juda a profané ce qui est consacré à l'Éternel, ce qu'aime l'Éternel, Il s'est uni à la fille d'un dieu étranger."],[2,12,"L'Éternel retranchera l'homme qui fait cela, celui qui veille et qui répond, Il le retranchera des tentes de Jacob, Et il retranchera celui qui présente une offrande À l'Éternel des armées.","L'Éternel retranchera l'homme qui fait cela, celui qui veille et qui répond, Il le retranchera des tentes de Jacob, Et il retranchera celui qui présente une offrande À l'Éternel des armées."],[2,13,"Voici encore ce que vous faites: Vous couvrez de larmes l'autel de l'Éternel, De pleurs et de gémissements, En sorte qu'il n'a plus égard aux offrandes Et qu'il ne peut rien agréer de vos mains.","Voici encore ce que vous faites: Vous couvrez de larmes l'autel de l'Éternel, De pleurs et de gémissements, En sorte qu'il n'a plus égard aux offrandes Et qu'il ne peut rien agréer de vos mains."],[2,14,"Et vous dites: Pourquoi?... Parce que l'Éternel a été témoin entre toi et la femme de ta jeunesse, À laquelle tu es infidèle, Bien qu'elle soit ta compagne et la femme de ton alliance.","Et vous dites: Pourquoi?... Parce que l'Éternel a été témoin entre toi et la femme de ta jeunesse, À laquelle tu es infidèle, Bien qu'elle soit ta compagne et la femme de ton alliance."],[2,15,"Nul n'a fait cela, avec un reste de bon sens. Un seul l'a fait, et pourquoi? Parce qu'il cherchait la postérité que Dieu lui avait promise. Prenez donc garde en votre esprit, Et qu'aucun ne soit infidèle à la femme de sa jeunesse!","Nul n'a fait cela, avec un reste de bon sens. Un seul l'a fait, et pourquoi? Parce qu'il cherchait la postérité que Dieu lui avait promise. Prenez donc garde en votre esprit, Et qu'aucun ne soit infidèle à la femme de sa jeunesse!"],[2,16,"Car je hais la répudiation, Dit l'Éternel, le Dieu d'Israël, Et celui qui couvre de violence son vêtement, Dit l'Éternel des armées. Prenez donc garde en votre esprit, Et ne soyez pas infidèles!","Car je hais la répudiation, Dit l'Éternel, le Dieu d'Israël, Et celui qui couvre de violence son vêtement, Dit l'Éternel des armées. Prenez donc garde en votre esprit, Et ne soyez pas infidèles!"],[2,17,"Vous fatiguez l'Éternel par vos paroles, Et vous dites: En quoi l'avons-nous fatigué? C'est en disant: Quiconque fait le mal est bon aux yeux de l'Éternel, Et c'est en lui qu'il prend plaisir! Ou bien: Où est le Dieu de la justice?","Vous fatiguez l'Éternel par vos paroles, Et vous dites: En quoi l'avons-nous fatigué? C'est en disant: Quiconque fait le mal est bon aux yeux de l'Éternel, Et c'est en lui qu'il prend plaisir! Ou bien: Où est le Dieu de la justice?"],[3,1,"Voici, j'enverrai mon messager; Il préparera le chemin devant moi. Et soudain entrera dans son temple le Seigneur que vous cherchez; Et le messager de l'alliance que vous désirez, voici, il vient, Dit l'Éternel des armées.","Voici, j'enverrai mon messager; Il préparera le chemin devant moi. Et soudain entrera dans son temple le Seigneur que vous cherchez; Et le messager de l'alliance que vous désirez, voici, il vient, Dit l'Éternel des armées."],[3,2,"Qui pourra soutenir le jour de sa venue? Qui restera debout quand il paraîtra? Car il sera comme le feu du fondeur, Comme la potasse des foulons.","Qui pourra soutenir le jour de sa venue? Qui restera debout quand il paraîtra? Car il sera comme le feu du fondeur, Comme la potasse des foulons."],[3,3,"Il s'assiéra, fondra et purifiera l'argent; Il purifiera les fils de Lévi, Il les épurera comme on épure l'or et l'argent, Et ils présenteront à l'Éternel des offrandes avec justice.","Il s'assiéra, fondra et purifiera l'argent; Il purifiera les fils de Lévi, Il les épurera comme on épure l'or et l'argent, Et ils présenteront à l'Éternel des offrandes avec justice."],[3,4,"Alors l'offrande de Juda et de Jérusalem sera agréable à l'Éternel, Comme aux anciens jours, comme aux années d'autrefois.","Alors l'offrande de Juda et de Jérusalem sera agréable à l'Éternel, Comme aux anciens jours, comme aux années d'autrefois."],[3,5,"Je m'approcherai de vous pour le jugement, Et je me hâterai de témoigner contre les enchanteurs et les adultères, Contre ceux qui jurent faussement, Contre ceux qui retiennent le salaire du mercenaire, Qui oppriment la veuve et l'orphelin, Qui font tort à l'étranger, et ne me craignent pas, Dit l'Éternel des armées.","Je m'approcherai de vous pour le jugement, Et je me hâterai de témoigner contre les enchanteurs et les adultères, Contre ceux qui jurent faussement, Contre ceux qui retiennent le salaire du mercenaire, Qui oppriment la veuve et l'orphelin, Qui font tort à l'étranger, et ne me craignent pas, Dit l'Éternel des armées."],[3,6,"Car je suis l'Éternel, je ne change pas; Et vous, enfants de Jacob, vous n'avez pas été consumés.","Car je suis l'Éternel, je ne change pas; Et vous, enfants de Jacob, vous n'avez pas été consumés."],[3,7,"Depuis le temps de vos pères, vous vous êtes écartés de mes ordonnances, Vous ne les avez point observées. Revenez à moi, et je reviendrai à vous, dit l'Éternel des armées. Et vous dites: En quoi devons-nous revenir?","Depuis le temps de vos pères, vous vous êtes écartés de mes ordonnances, Vous ne les avez point observées. Revenez à moi, et je reviendrai à vous, dit l'Éternel des armées. Et vous dites: En quoi devons-nous revenir?"],[3,8,"Un homme trompe-t-il Dieu? Car vous me trompez, Et vous dites: En quoi t'avons-nous trompé? Dans les dîmes et les offrandes.","Un homme trompe-t-il Dieu? Car vous me trompez, Et vous dites: En quoi t'avons-nous trompé? Dans les dîmes et les offrandes."],[3,9,"Vous êtes frappés par la malédiction, Et vous me trompez, La nation tout entière!","Vous êtes frappés par la malédiction, Et vous me trompez, La nation tout entière!"],[3,10,"Apportez à la maison du trésor toutes les dîmes, Afin qu'il y ait de la nourriture dans ma maison; Mettez-moi de la sorte à l'épreuve, Dit l'Éternel des armées. Et vous verrez si je n'ouvre pas pour vous les écluses des cieux, Si je ne répands pas sur vous la bénédiction en abondance.","Apportez à la maison du trésor toutes les dîmes, Afin qu'il y ait de la nourriture dans ma maison; Mettez-moi de la sorte à l'épreuve, Dit l'Éternel des armées. Et vous verrez si je n'ouvre pas pour vous les écluses des cieux, Si je ne répands pas sur vous la bénédiction en abondance."],[3,11,"Pour vous je menacerai celui qui dévore, Et il ne vous détruira pas les fruits de la terre, Et la vigne ne sera pas stérile dans vos campagnes, Dit l'Éternel des armées.","Pour vous je menacerai celui qui dévore, Et il ne vous détruira pas les fruits de la terre, Et la vigne ne sera pas stérile dans vos campagnes, Dit l'Éternel des armées."],[3,12,"Toutes les nations vous diront heureux, Car vous serez un pays de délices, Dit l'Éternel des armées.","Toutes les nations vous diront heureux, Car vous serez un pays de délices, Dit l'Éternel des armées."],[3,13,"Vos paroles sont rudes contre moi, dit l'Éternel. Et vous dites: Qu'avons-nous dit contre toi?","Vos paroles sont rudes contre moi, dit l'Éternel. Et vous dites: Qu'avons-nous dit contre toi?"],[3,14,"Vous avez dit: C'est en vain que l'on sert Dieu; Qu'avons-nous gagné à observer ses préceptes, Et à marcher avec tristesse À cause de l'Éternel des armées?","Vous avez dit: C'est en vain que l'on sert Dieu; Qu'avons-nous gagné à observer ses préceptes, Et à marcher avec tristesse À cause de l'Éternel des armées?"],[3,15,"Maintenant nous estimons heureux les hautains; Oui, les méchants prospèrent; Oui, ils tentent Dieu, et ils échappent!","Maintenant nous estimons heureux les hautains; Oui, les méchants prospèrent; Oui, ils tentent Dieu, et ils échappent!"],[3,16,"Alors ceux qui craignent l'Éternel se parlèrent l'un à l'autre; L'Éternel fut attentif, et il écouta; Et un livre de souvenir fut écrit devant lui Pour ceux qui craignent l'Éternel Et qui honorent son nom.","Alors ceux qui craignent l'Éternel se parlèrent l'un à l'autre; L'Éternel fut attentif, et il écouta; Et un livre de souvenir fut écrit devant lui Pour ceux qui craignent l'Éternel Et qui honorent son nom."],[3,17,"Ils seront à moi, dit l'Éternel des armées, Ils m'appartiendront, au jour que je prépare; J'aurai compassion d'eux, Comme un homme a compassion de son fils qui le sert.","Ils seront à moi, dit l'Éternel des armées, Ils m'appartiendront, au jour que je prépare; J'aurai compassion d'eux, Comme un homme a compassion de son fils qui le sert."],[3,18,"Et vous verrez de nouveau la différence Entre le juste et le méchant, Entre celui qui sert Dieu Et celui qui ne le sert pas.","Et vous verrez de nouveau la différence Entre le juste et le méchant, Entre celui qui sert Dieu Et celui qui ne le sert pas."],[4,1,"Car voici, le jour vient, Ardent comme une fournaise. Tous les hautains et tous les méchants seront comme du chaume; Le jour qui vient les embrasera, Dit l'Éternel des armées, Il ne leur laissera ni racine ni rameau.","Car voici, le jour vient, Ardent comme une fournaise. Tous les hautains et tous les méchants seront comme du chaume; Le jour qui vient les embrasera, Dit l'Éternel des armées, Il ne leur laissera ni racine ni rameau."],[4,2,"Mais pour vous qui craignez mon nom, se lèvera Le soleil de la justice, Et la guérison sera sous ses ailes; Vous sortirez, et vous sauterez comme les veaux d'une étable,","Mais pour vous qui craignez mon nom, se lèvera Le soleil de la justice, Et la guérison sera sous ses ailes; Vous sortirez, et vous sauterez comme les veaux d'une étable,"],[4,3,"Et vous foulerez les méchants, Car ils seront comme de la cendre Sous la plante de vos pieds, Au jour que je prépare, Dit l'Éternel des armées.","Et vous foulerez les méchants, Car ils seront comme de la cendre Sous la plante de vos pieds, Au jour que je prépare, Dit l'Éternel des armées."],[4,4,"Souvenez-vous de la loi de Moïse, mon serviteur, Auquel j'ai prescrit en Horeb, pour tout Israël, Des préceptes et des ordonnances.","Souvenez-vous de la loi de Moïse, mon serviteur, Auquel j'ai prescrit en Horeb, pour tout Israël, Des préceptes et des ordonnances."],[4,5,"Voici, je vous enverrai Élie, le prophète, Avant que le jour de l'Éternel arrive, Ce jour grand et redoutable.","Voici, je vous enverrai Élie, le prophète, Avant que le jour de l'Éternel arrive, Ce jour grand et redoutable."],[4,6,"Il ramènera le coeur des pères à leurs enfants, Et le coeur des enfants à leurs pères, De peur que je ne vienne frapper le pays d'interdit.","Il ramènera le coeur des pères à leurs enfants, Et le coeur des enfants à leurs pères, De peur que je ne vienne frapper le pays d'interdit."]],"spa-rv1909":[[1,1,"CARGAde la palabrade JehovácontraIsrael, por manode Malaquías.","CARGAde la palabrade JehovácontraIsrael, por manode Malaquías."],[1,2,"Yo os he amado, diceJehová: y dijisteis: ¿En quénos amaste? ¿Noera Esaúhermanode Jacob, diceJehová, y améá Jacob,","Yo os he amado, diceJehová: y dijisteis: ¿En quénos amaste? ¿Noera Esaúhermanode Jacob, diceJehová, y améá Jacob,"],[1,3,"Y á Esaúaborrecí, y tornésus montesen asolamiento, y su posesiónpara los chacales del desierto?","Y á Esaúaborrecí, y tornésus montesen asolamiento, y su posesiónpara los chacales del desierto?"],[1,4,"CuandoEdomdijere: Nos hemos empobrecido, mas tornemos á edificarlo arruinado; asíha dichoJehováde los ejércitos: Ellosedificarán, y yodestruiré: y les llamaránProvincia de impiedad, y, Pueblocontra quien Jehováse airó parasiempre.","CuandoEdomdijere: Nos hemos empobrecido, mas tornemos á edificarlo arruinado; asíha dichoJehováde los ejércitos: Ellosedificarán, y yodestruiré: y les llamaránProvincia de impiedad, y, Pueblocontra quien Jehováse airó parasiempre."],[1,5,"Y vuestrosojoslo verán, y diréis: Sea Jehováengrandecidosobre la provincia de Israel.","Y vuestrosojoslo verán, y diréis: Sea Jehováengrandecidosobre la provincia de Israel."],[1,6,"El hijohonraal padre, y el siervoá su señor: sipuessoy yopadre, ¿quées de mihonra? y sisoyseñor, ¿quées de mitemor?, diceJehováde los ejércitosá vosotros, oh sacerdotes, que menospreciáisminombre. Y decís: ¿En quéhemos menospreciadotu nombre?","El hijohonraal padre, y el siervoá su señor: sipuessoy yopadre, ¿quées de mihonra? y sisoyseñor, ¿quées de mitemor?, diceJehováde los ejércitosá vosotros, oh sacerdotes, que menospreciáisminombre. Y decís: ¿En quéhemos menospreciadotu nombre?"],[1,7,"Que ofrecéissobremi altarpaninmundo. Y dijisteis: ¿En quéte hemos amancillado? En que decís: La mesade Jehováes despreciable.","Que ofrecéissobremi altarpaninmundo. Y dijisteis: ¿En quéte hemos amancillado? En que decís: La mesade Jehováes despreciable."],[1,8,"Y cuandoofrecéisel animalciegopara sacrificar, ¿noes malo? asimismo cuandoofrecéisel cojoó el enfermo, ¿noes malo? Preséntalopuesá tu príncipe: ¿acaso se agradaráde ti, óle serás acepto? diceJehováde los ejércitos.","Y cuandoofrecéisel animalciegopara sacrificar, ¿noes malo? asimismo cuandoofrecéisel cojoó el enfermo, ¿noes malo? Preséntalopuesá tu príncipe: ¿acaso se agradaráde ti, óle serás acepto? diceJehováde los ejércitos."],[1,9,"Ahorapues, oradá la faz de Diosque tenga piedad de nosotros: estodevuestra manovino: ¿le seréis agradables? diceJehováde los ejércitos.","Ahorapues, oradá la faz de Diosque tenga piedad de nosotros: estodevuestra manovino: ¿le seréis agradables? diceJehováde los ejércitos."],[1,10,"¿Quiéntambiénhay de vosotros que cierrelas puertasó alumbremi altarde balde? Yo no recibocontentamientoen vosotros, diceJehováde los ejércitos, nide vuestra manome será agradableel presente.","¿Quiéntambiénhay de vosotros que cierrelas puertasó alumbremi altarde balde? Yo no recibocontentamientoen vosotros, diceJehováde los ejércitos, nide vuestra manome será agradableel presente."],[1,11,"Porquedesde donde el solnacehastadonde se pone, es grandemi nombreentre las gentes; y en todolugarse ofreceá mi nombreperfume, y presentelimpio: porquegrandees mi nombreentre las gentes, diceJehováde los ejércitos.","Porquedesde donde el solnacehastadonde se pone, es grandemi nombreentre las gentes; y en todolugarse ofreceá mi nombreperfume, y presentelimpio: porquegrandees mi nombreentre las gentes, diceJehováde los ejércitos."],[1,12,"Y vosotroslo habéis profanadocuando decís: Inmundaes la mesade Jehová; y cuando hablan quesualimentoes despreciable.","Y vosotroslo habéis profanadocuando decís: Inmundaes la mesade Jehová; y cuando hablan quesualimentoes despreciable."],[1,13,"Habéis además dicho: ¡Oh quétrabajo! y lo desechasteis, diceJehováde los ejércitos; y trajisteislo hurtado, ó cojo, ó enfermo, y presentasteisofrenda. ¿Seráme acepto eso de vuestra mano? diceJehová.","Habéis además dicho: ¡Oh quétrabajo! y lo desechasteis, diceJehováde los ejércitos; y trajisteislo hurtado, ó cojo, ó enfermo, y presentasteisofrenda. ¿Seráme acepto eso de vuestra mano? diceJehová."],[1,14,"Malditoel engañoso, que tiene macho en su rebaño, y promete, y sacrificalo dañadoá Jehová: porqueyosoy GranRey, diceJehováde los ejércitos, y minombrees formidable entre las gentes.","Malditoel engañoso, que tiene macho en su rebaño, y promete, y sacrificalo dañadoá Jehová: porqueyosoy GranRey, diceJehováde los ejércitos, y minombrees formidable entre las gentes."],[2,1,"AHORApues, oh sacerdotes, á vosotros es este mandamiento.","AHORApues, oh sacerdotes, á vosotros es este mandamiento."],[2,2,"Sinooyereis, y sinoacordareisdargloriaá mi nombre, ha dichoJehováde los ejércitos, enviarémaldiciónsobre vosotros, y maldecirévuestras bendiciones; y aunlas he maldecido, porquenolo ponéisenvuestro corazón.","Sinooyereis, y sinoacordareisdargloriaá mi nombre, ha dichoJehováde los ejércitos, enviarémaldiciónsobre vosotros, y maldecirévuestras bendiciones; y aunlas he maldecido, porquenolo ponéisenvuestro corazón."],[2,3,"He aquí, yo os dañola sementera, y esparciréel estiércolsobrevuestros rostros, el estiércolde vuestras solemnidades, y conél seréis removidos.","He aquí, yo os dañola sementera, y esparciréel estiércolsobrevuestros rostros, el estiércolde vuestras solemnidades, y conél seréis removidos."],[2,4,"Y sabréisqueyo osenviéeste mandamiento, para quefuesemi pactoconLeví, ha dichoJehováde los ejércitos.","Y sabréisqueyo osenviéeste mandamiento, para quefuesemi pactoconLeví, ha dichoJehováde los ejércitos."],[2,5,"Mi pactofuéconélde viday de paz, las cuales cosas yo le dípor el temor; porque me temió, y delantede mi nombreestuvo humillado.","Mi pactofuéconélde viday de paz, las cuales cosas yo le dípor el temor; porque me temió, y delantede mi nombreestuvo humillado."],[2,6,"La leyde verdadestuvoen su boca, é iniquidadnofué halladaen sus labios: en pazy en justiciaanduvoconmigo, y á muchoshizo apartarde la iniquidad.","La leyde verdadestuvoen su boca, é iniquidadnofué halladaen sus labios: en pazy en justiciaanduvoconmigo, y á muchoshizo apartarde la iniquidad."],[2,7,"Porquelos labiosde los sacerdoteshan de guardarla sabiduría, y de subocabuscaránla ley; porquemensajeroes de Jehováde los ejércitos.","Porquelos labiosde los sacerdoteshan de guardarla sabiduría, y de subocabuscaránla ley; porquemensajeroes de Jehováde los ejércitos."],[2,8,"Mas vosotrosos habéis apartadodelcamino; habéis hecho tropezará muchosen la ley; habéis corrompidoel pactode Leví, diceJehováde los ejércitos.","Mas vosotrosos habéis apartadodelcamino; habéis hecho tropezará muchosen la ley; habéis corrompidoel pactode Leví, diceJehováde los ejércitos."],[2,9,"Por tanto, yotambiénos torné vilesy bajosá todoel pueblo, según que vosotrosnohabéis guardadomiscaminos, y en la leytenéis acepciónde personas.","Por tanto, yotambiénos torné vilesy bajosá todoel pueblo, según que vosotrosnohabéis guardadomiscaminos, y en la leytenéis acepciónde personas."],[2,10,"¿Notenemos todosunmismopadre? ¿Nonosha criadounmismoDios? ¿Porqué menospreciaremoscada unoá su hermano, quebrantandoel pactode nuestrospadres?","¿Notenemos todosunmismopadre? ¿Nonosha criadounmismoDios? ¿Porqué menospreciaremoscada unoá su hermano, quebrantandoel pactode nuestrospadres?"],[2,11,"PrevaricóJudá, y en Israely en Jerusalemha sido cometidaabominación; porqueJudáha profanadola santidadde Jehováqueamó, y casádosecon hijade diosextraño.","PrevaricóJudá, y en Israely en Jerusalemha sido cometidaabominación; porqueJudáha profanadola santidadde Jehováqueamó, y casádosecon hijade diosextraño."],[2,12,"Jehovátalaráde las tiendasde Jacobal hombrequehiciereesto, al quevela, y al queresponde, y al queofrecepresenteá Jehováde los ejércitos.","Jehovátalaráde las tiendasde Jacobal hombrequehiciereesto, al quevela, y al queresponde, y al queofrecepresenteá Jehováde los ejércitos."],[2,13,"Y estaotravez haréiscubrirel altarde Jehováde lágrimas, de llanto, y de clamor; así que nomirarémásápresente, para aceptarlocon gustode vuestra mano.","Y estaotravez haréiscubrirel altarde Jehováde lágrimas, de llanto, y de clamor; así que nomirarémásápresente, para aceptarlocon gustode vuestra mano."],[2,14,"Mas diréis: ¿Porqué? PorqueJehováha atestiguado entretiy la mujerde tumocedad, contra la cualtú has sido desleal, siendo ellatucompañera, y la mujerde tupacto.","Mas diréis: ¿Porqué? PorqueJehováha atestiguado entretiy la mujerde tumocedad, contra la cualtú has sido desleal, siendo ellatucompañera, y la mujerde tupacto."],[2,15,"Pues qué¿nohizoél uno soloaunque tenía la abundanciadel espíritu? ¿Y por quéuno? Para que procurara una simientede Dios. Guardaospues en vuestros espíritus, y contra la mujerde vuestra mocedadnoseáis desleales.","Pues qué¿nohizoél uno soloaunque tenía la abundanciadel espíritu? ¿Y por quéuno? Para que procurara una simientede Dios. Guardaospues en vuestros espíritus, y contra la mujerde vuestra mocedadnoseáis desleales."],[2,16,"PorqueJehováDiosde Israelha dichoque él aborreceque sea repudiada; y cubra la iniquidadcon su vestido, dijoJehováde los ejércitos. Guardaospues en vuestros espíritus, y noseáis desleales.","PorqueJehováDiosde Israelha dichoque él aborreceque sea repudiada; y cubra la iniquidadcon su vestido, dijoJehováde los ejércitos. Guardaospues en vuestros espíritus, y noseáis desleales."],[2,17,"Habéis hecho cansará Jehovácon vuestras palabras. Y diréis: ¿En qué lehemos cansado? Cuando decís: Cualquieraque malhaceagradaá Jehová, y en los talestoma contentamiento: de otra manera, ¿dóndeestá el Diosde juicio?","Habéis hecho cansará Jehovácon vuestras palabras. Y diréis: ¿En qué lehemos cansado? Cuando decís: Cualquieraque malhaceagradaá Jehová, y en los talestoma contentamiento: de otra manera, ¿dóndeestá el Diosde juicio?"],[3,1,"HE aquí, yo envíomi mensajero, el cual prepararáel caminodelantede mí: y luego vendráá su temploel Señorá quienvosotrosbuscáis, y el ángeldel pacto, á quiendeseáisvosotros. He aquíviene, ha dichoJehováde los ejércitos.","HE aquí, yo envíomi mensajero, el cual prepararáel caminodelantede mí: y luego vendráá su temploel Señorá quienvosotrosbuscáis, y el ángeldel pacto, á quiendeseáisvosotros. He aquíviene, ha dichoJehováde los ejércitos."],[3,2,"¿Y quiénpodrá sufrirel tiempode suvenida? ó ¿quiénpodrá estarcuando élse mostrará? Porqueéles como fuegopurificador, y como jabónde lavadores.","¿Y quiénpodrá sufrirel tiempode suvenida? ó ¿quiénpodrá estarcuando élse mostrará? Porqueéles como fuegopurificador, y como jabónde lavadores."],[3,3,"Y sentarseha para afinary limpiarla plata: porque limpiarálos hijosde Leví, los afinarácomo á oroy como á plata; y ofreceráná Jehováofrendacon justicia.","Y sentarseha para afinary limpiarla plata: porque limpiarálos hijosde Leví, los afinarácomo á oroy como á plata; y ofreceráná Jehováofrendacon justicia."],[3,4,"Y será suaveá Jehovála ofrendade Judáy de Jerusalem, como en los díaspasados, y como en los añosantiguos.","Y será suaveá Jehovála ofrendade Judáy de Jerusalem, como en los díaspasados, y como en los añosantiguos."],[3,5,"Y llegarmehe ávosotros á juicio; y seréprontotestigocontra los hechicerosy adúlteros; y contra los que juranmentira, y los que detienenel salariodel jornalero, de la viuda, y del huérfano, y los que hacen agravioal extranjero, noteniendo temorde mí, diceJehováde los ejércitos.","Y llegarmehe ávosotros á juicio; y seréprontotestigocontra los hechicerosy adúlteros; y contra los que juranmentira, y los que detienenel salariodel jornalero, de la viuda, y del huérfano, y los que hacen agravioal extranjero, noteniendo temorde mí, diceJehováde los ejércitos."],[3,6,"PorqueyoJehová, nome mudo; y así vosotros, hijosde Jacob, nohabéis sido consumidos.","PorqueyoJehová, nome mudo; y así vosotros, hijosde Jacob, nohabéis sido consumidos."],[3,7,"Desde los díasde vuestros padresos habéis apartadode mis leyes, y nolas guardasteis. Tornaosá mí, y yo me tornaréávosotros, ha dichoJehováde los ejércitos. Mas dijisteis: ¿En quéhemos de tornar?","Desde los díasde vuestros padresos habéis apartadode mis leyes, y nolas guardasteis. Tornaosá mí, y yo me tornaréávosotros, ha dichoJehováde los ejércitos. Mas dijisteis: ¿En quéhemos de tornar?"],[3,8,"¿Robaráel hombre á Dios? Puesvosotrosme habéis robado. Y dijisteis: ¿En quétehemos robado? Los diezmosy las primicias.","¿Robaráel hombre á Dios? Puesvosotrosme habéis robado. Y dijisteis: ¿En quétehemos robado? Los diezmosy las primicias."],[3,9,"Malditossois con maldición, porque vosotros, la nacióntoda, me habéis robado.","Malditossois con maldición, porque vosotros, la nacióntoda, me habéis robado."],[3,10,"Traedtodoslos diezmosalalfolí, y hayaalimentoen mi casa; y probadmeahoraen esto, diceJehováde los ejércitos, sinoos abrirélas ventanasde los cielos, y vaciarésobre vosotros bendiciónhastaque sobreabunde.","Traedtodoslos diezmosalalfolí, y hayaalimentoen mi casa; y probadmeahoraen esto, diceJehováde los ejércitos, sinoos abrirélas ventanasde los cielos, y vaciarésobre vosotros bendiciónhastaque sobreabunde."],[3,11,"Increparétambién por vosotros al devorador, y noos corromperá el frutode la tierra; nivuestra viden el campoabortará, diceJehováde los ejércitos.","Increparétambién por vosotros al devorador, y noos corromperá el frutode la tierra; nivuestra viden el campoabortará, diceJehováde los ejércitos."],[3,12,"Y todaslas gentesos dirán bienaventurados; porqueseréistierradeseable, diceJehováde los ejércitos.","Y todaslas gentesos dirán bienaventurados; porqueseréistierradeseable, diceJehováde los ejércitos."],[3,13,"Vuestraspalabras han prevalecidocontramí, diceJehová. Y dijisteis: ¿Quéhemos habladocontrati?","Vuestraspalabras han prevalecidocontramí, diceJehová. Y dijisteis: ¿Quéhemos habladocontrati?"],[3,14,"Habéis dicho: Por demáses servirá Dios; ¿y quéaprovechaqueguardemossu ley, y queandemostristesdelantede Jehováde los ejércitos?","Habéis dicho: Por demáses servirá Dios; ¿y quéaprovechaqueguardemossu ley, y queandemostristesdelantede Jehováde los ejércitos?"],[3,15,"Decimos pues ahora, que bienaventuradoslos soberbios, y también que los que hacenimpiedadson los prosperados: bien quetentaroná Dios, escaparon.","Decimos pues ahora, que bienaventuradoslos soberbios, y también que los que hacenimpiedadson los prosperados: bien quetentaroná Dios, escaparon."],[3,16,"Entonceslos que temená Jehováhablaroncada unoá su compañero; y Jehováescuchóy oyó, y fué escritolibrode memoriadelantede él para los que temená Jehová, y para los que piensanen su nombre.","Entonceslos que temená Jehováhablaroncada unoá su compañero; y Jehováescuchóy oyó, y fué escritolibrode memoriadelantede él para los que temená Jehová, y para los que piensanen su nombre."],[3,17,"Y seránpara míespecial tesoro, ha dichoJehováde los ejércitos, en el díaqueyotengo de hacer: y perdonaréloscomo el hombrequeperdonaásu hijoquele sirve.","Y seránpara míespecial tesoro, ha dichoJehováde los ejércitos, en el díaqueyotengo de hacer: y perdonaréloscomo el hombrequeperdonaásu hijoquele sirve."],[3,18,"Entonces os tornaréis, y echaréisde ver la diferencia entreel justoy el malo, entreel que sirveá Diosy el quenole sirve.","Entonces os tornaréis, y echaréisde ver la diferencia entreel justoy el malo, entreel que sirveá Diosy el quenole sirve."],[4,1,"PORQUEhe aquí, vieneel díaardientecomo un horno; y todoslos soberbios, y todoslos que hacenmaldad, seránestopa; y aquel díaque vendrá, los abrasará, ha dichoJehováde los ejércitos, el cual noles dejaráni raízni rama.","PORQUEhe aquí, vieneel díaardientecomo un horno; y todoslos soberbios, y todoslos que hacenmaldad, seránestopa; y aquel díaque vendrá, los abrasará, ha dichoJehováde los ejércitos, el cual noles dejaráni raízni rama."],[4,2,"Mas á vosotros los que teméismi nombre, naceráel Solde justicia, y en sus alastraerásalud: y saldréis, y saltaréiscomo becerrosde la manada.","Mas á vosotros los que teméismi nombre, naceráel Solde justicia, y en sus alastraerásalud: y saldréis, y saltaréiscomo becerrosde la manada."],[4,3,"Y hollaréisá los malos, los cuales seráncenizabajolas plantasde vuestros pies, en el díaqueyohago, ha dichoJehováde los ejércitos.","Y hollaréisá los malos, los cuales seráncenizabajolas plantasde vuestros pies, en el díaqueyohago, ha dichoJehováde los ejércitos."],[4,4,"Acordaosde la leyde Moisésmi siervo, al cual encarguéen Horebordenanzasy leyesparatodoIsrael.","Acordaosde la leyde Moisésmi siervo, al cual encarguéen Horebordenanzasy leyesparatodoIsrael."],[4,5,"He aquí, yoosenvíoá Elíasel profeta, antesque vengael díade Jehovágrandey terrible.","He aquí, yoosenvíoá Elíasel profeta, antesque vengael díade Jehovágrandey terrible."],[4,6,"El convertiráel corazónde los padresá los hijos, y el corazónde los hijosá los padres: nosea que yo venga, y con destrucciónhierala tierra.","El convertiráel corazónde los padresá los hijos, y el corazónde los hijosá los padres: nosea que yo venga, y con destrucciónhierala tierra."]],"rus-synodal":[[1,1,"Пророческое слово Господа к Израилю через Малахию.","Proročeskoe slovo Gospoda k Izrailû čerez Malahiû."],[1,2,"Я возлюбил вас, говорит Господь. А вы говорите: «в чем явил Ты любовь к нам?» – Не брат ли Исав Иакову? говорит Господь; и однако же Я возлюбил Иакова,","Â vozlûbil vas, govorit Gospodʹ. A vy govorite: «v čem âvil Ty lûbovʹ k nam?» – Ne brat li Isav Iakovu? govorit Gospodʹ; i odnako že Â vozlûbil Iakova,"],[1,3,"а Исава возненавидел и предал горы его опустошению, и владения его – шакалам пустыни.","a Isava voznenavidel i predal gory ego opustošeniû, i vladeniâ ego – šakalam pustyni."],[1,4,"Если Едом скажет: «мы разорены, но мы восстановим разрушенное», то Господь Саваоф говорит: они построят, а Я разрушу, и прозовут их областью нечестивою, народом, на который Господь прогневался навсегда.","Esli Edom skažet: «my razoreny, no my vosstanovim razrušennoe», to Gospodʹ Savaof govorit: oni postroât, a Â razrušu, i prozovut ih oblastʹû nečestivoû, narodom, na kotoryj Gospodʹ prognevalsâ navsegda."],[1,5,"И увидят это глаза ваши, и вы скажете: «возвеличился Господь над пределами Израиля!»","I uvidât éto glaza vaši, i vy skažete: «vozveličilsâ Gospodʹ nad predelami Izrailâ!»"],[1,6,"Сын чтит отца, и раб – господина своего; если Я – отец, то где почтение ко Мне? и если Я – Господь, то где благоговение предо Мною? говорит Господь Саваоф вам, священники, бесславящие имя Мое. Вы говорите: «чем мы бесславим имя Твое?»","Syn čtit otca, i rab – gospodina svoego; esli Â – otec, to gde počtenie ko Mne? i esli Â – Gospodʹ, to gde blagogovenie predo Mnoû? govorit Gospodʹ Savaof vam, svâŝenniki, besslavâŝie imâ Moe. Vy govorite: «čem my besslavim imâ Tvoe?»"],[1,7,"Вы приносите на жертвенник Мой нечистый хлеб, а говорите: «чем мы бесславим Тебя?» – Тем, что говорите: «трапеза Господня не стоит уважения».","Vy prinosite na žertvennik Moj nečistyj hleb, a govorite: «čem my besslavim Tebâ?» – Tem, čto govorite: «trapeza Gospodnâ ne stoit uvaženiâ»."],[1,8,"И когда приносите в жертву слепое, не худо ли это? или когда приносите хромое и больное, не худо ли это? Поднеси это твоему князю; будет ли он доволен тобою и благосклонно ли примет тебя? говорит Господь Саваоф.","I kogda prinosite v žertvu slepoe, ne hudo li éto? ili kogda prinosite hromoe i bolʹnoe, ne hudo li éto? Podnesi éto tvoemu knâzû; budet li on dovolen toboû i blagosklonno li primet tebâ? govorit Gospodʹ Savaof."],[1,9,"Итак молитесь Богу, чтобы помиловал нас; а когда такое исходит из рук ваших, то может ли Он милостиво принимать вас? говорит Господь Саваоф.","Itak molitesʹ Bogu, čtoby pomiloval nas; a kogda takoe ishodit iz ruk vaših, to možet li On milostivo prinimatʹ vas? govorit Gospodʹ Savaof."],[1,10,"Лучше кто-нибудь из вас запер бы двери, чтобы напрасно не держали огня на жертвеннике Моем. Нет Моего благоволения к вам, говорит Господь Саваоф, и приношение из рук ваших неблагоугодно Мне.","Lučše kto-nibudʹ iz vas zaper by dveri, čtoby naprasno ne deržali ognâ na žertvennike Moem. Net Moego blagovoleniâ k vam, govorit Gospodʹ Savaof, i prinošenie iz ruk vaših neblagougodno Mne."],[1,11,"Ибо от востока солнца до запада велико будет имя Мое между народами, и на всяком месте будут приносить фимиам имени Моему, чистую жертву; велико будет имя Мое между народами, говорит Господь Саваоф.","Ibo ot vostoka solnca do zapada veliko budet imâ Moe meždu narodami, i na vsâkom meste budut prinositʹ fimiam imeni Moemu, čistuû žertvu; veliko budet imâ Moe meždu narodami, govorit Gospodʹ Savaof."],[1,12,"А вы хулите его тем, что говорите: «трапеза Господня не стоит уважения, и доход от нее – пища ничтожная».","A vy hulite ego tem, čto govorite: «trapeza Gospodnâ ne stoit uvaženiâ, i dohod ot nee – piŝa ničtožnaâ»."],[1,13,"Притом говорите: «вот сколько труда!» и пренебрегаете ею, говорит Господь Саваоф, и приносите украденное, хромое и больное, и такого же свойства приносите хлебный дар: могу ли с благоволением принимать это из рук ваших? говорит Господь.","Pritom govorite: «vot skolʹko truda!» i prenebregaete eû, govorit Gospodʹ Savaof, i prinosite ukradennoe, hromoe i bolʹnoe, i takogo že svojstva prinosite hlebnyj dar: mogu li s blagovoleniem prinimatʹ éto iz ruk vaših? govorit Gospodʹ."],[1,14,"Проклят лживый, у которого в стаде есть неиспорченный самец, и он дал обет, а приносит в жертву Господу поврежденное: ибо Я – Царь великий, и имя Мое страшно у народов.","Proklât lživyj, u kotorogo v stade estʹ neisporčennyj samec, i on dal obet, a prinosit v žertvu Gospodu povreždennoe: ibo Â – Carʹ velikij, i imâ Moe strašno u narodov."],[2,1,"Итак для вас, священники, эта заповедь:","Itak dlâ vas, svâŝenniki, éta zapovedʹ:"],[2,2,"если вы не послушаетесь и если не примете к сердцу, чтобы воздавать славу имени Моему, говорит Господь Саваоф, то Я пошлю на вас проклятие и прокляну ваши благословения, и уже проклинаю, потому что вы не хотите приложить к тому сердца.","esli vy ne poslušaetesʹ i esli ne primete k serdcu, čtoby vozdavatʹ slavu imeni Moemu, govorit Gospodʹ Savaof, to Â pošlû na vas proklâtie i proklânu vaši blagosloveniâ, i uže proklinaû, potomu čto vy ne hotite priložitʹ k tomu serdca."],[2,3,"Вот, Я отниму у вас плечо и помет раскидаю на лица ваши, помет праздничных жертв ваших, и выбросят вас вместе с ним.","Vot, Â otnimu u vas plečo i pomet raskidaû na lica vaši, pomet prazdničnyh žertv vaših, i vybrosât vas vmeste s nim."],[2,4,"И вы узнаете, что Я дал эту заповедь для сохранения завета Моего с Левием, говорит Господь Саваоф.","I vy uznaete, čto Â dal étu zapovedʹ dlâ sohraneniâ zaveta Moego s Leviem, govorit Gospodʹ Savaof."],[2,5,"Завет Мой с ним был завет жизни и мира, и Я дал его ему для страха, и он боялся Меня и благоговел пред именем Моим.","Zavet Moj s nim byl zavet žizni i mira, i Â dal ego emu dlâ straha, i on boâlsâ Menâ i blagogovel pred imenem Moim."],[2,6,"Закон истины был в устах его, и неправды не обреталось на языке его; в мире и правде он ходил со Мною и многих отвратил от греха.","Zakon istiny byl v ustah ego, i nepravdy ne obretalosʹ na âzyke ego; v mire i pravde on hodil so Mnoû i mnogih otvratil ot greha."],[2,7,"Ибо уста священника должны хранить ведение, и закона ищут от уст его, потому что он вестник Господа Саваофа.","Ibo usta svâŝennika dolžny hranitʹ vedenie, i zakona iŝut ot ust ego, potomu čto on vestnik Gospoda Savaofa."],[2,8,"Но вы уклонились от пути сего, для многих послужили соблазном в законе, разрушили завет Левия, говорит Господь Саваоф.","No vy uklonilisʹ ot puti sego, dlâ mnogih poslužili soblaznom v zakone, razrušili zavet Leviâ, govorit Gospodʹ Savaof."],[2,9,"За то и Я сделаю вас презренными и униженными перед всем народом, так как вы не соблюдаете путей Моих, лицеприятствуете в делах закона.","Za to i Â sdelaû vas prezrennymi i unižennymi pered vsem narodom, tak kak vy ne soblûdaete putej Moih, licepriâtstvuete v delah zakona."],[2,10,"Не один ли у всех нас Отец? Не один ли Бог сотворил нас? Почему же мы вероломно поступаем друг против друга, нарушая тем завет отцов наших?","Ne odin li u vseh nas Otec? Ne odin li Bog sotvoril nas? Počemu že my verolomno postupaem drug protiv druga, narušaâ tem zavet otcov naših?"],[2,11,"Вероломно поступает Иуда, и мерзость совершается в Израиле и в Иерусалиме; ибо унизил Иуда святыню Господню, которую любил, и женился на дочери чужого бога.","Verolomno postupaet Iuda, i merzostʹ soveršaetsâ v Izraile i v Ierusalime; ibo unizil Iuda svâtynû Gospodnû, kotoruû lûbil, i ženilsâ na dočeri čužogo boga."],[2,12,"У того, кто делает это, истребит Господь из шатров Иаковлевых бдящего на страже и отвечающего, и приносящего жертву Господу Саваофу.","U togo, kto delaet éto, istrebit Gospodʹ iz šatrov Iakovlevyh bdâŝego na straže i otvečaûŝego, i prinosâŝego žertvu Gospodu Savaofu."],[2,13,"И вот еще что вы делаете: вы заставляете обливать слезами жертвенник Господа с рыданием и воплем, так что Он уже не призирает более на приношение и не принимает умилостивительной жертвы из рук ваших.","I vot eŝe čto vy delaete: vy zastavlâete oblivatʹ slezami žertvennik Gospoda s rydaniem i voplem, tak čto On uže ne priziraet bolee na prinošenie i ne prinimaet umilostivitelʹnoj žertvy iz ruk vaših."],[2,14,"Вы скажете: «за что?» За то, что Господь был свидетелем между тобою и женою юности твоей, против которой ты поступил вероломно, между тем как она подруга твоя и законная жена твоя.","Vy skažete: «za čto?» Za to, čto Gospodʹ byl svidetelem meždu toboû i ženoû ûnosti tvoej, protiv kotoroj ty postupil verolomno, meždu tem kak ona podruga tvoâ i zakonnaâ žena tvoâ."],[2,15,"Но не сделал ли того же один, и в нем пребывал превосходный дух? что же сделал этот один? он желал получить от Бога потомство. Итак берегите дух ваш, и никто не поступай вероломно против жены юности своей.","No ne sdelal li togo že odin, i v nem prebyval prevoshodnyj duh? čto že sdelal étot odin? on želal polučitʹ ot Boga potomstvo. Itak beregite duh vaš, i nikto ne postupaj verolomno protiv ženy ûnosti svoej."],[2,16,"Если ты ненавидишь ее, отпусти, говорит Господь Бог Израилев; обида покроет одежду его, говорит Господь Саваоф; посему наблюдайте за духом вашим и не поступайте вероломно.","Esli ty nenavidišʹ ee, otpusti, govorit Gospodʹ Bog Izrailev; obida pokroet odeždu ego, govorit Gospodʹ Savaof; posemu nablûdajte za duhom vašim i ne postupajte verolomno."],[2,17,"Вы прогневляете Господа словами вашими и говорите: «чем прогневляем мы Его?» Тем, что говорите: «всякий, делающий зло, хорош пред очами Господа, и к таким Он благоволит», или: «где Бог правосудия?»","Vy prognevlâete Gospoda slovami vašimi i govorite: «čem prognevlâem my Ego?» Tem, čto govorite: «vsâkij, delaûŝij zlo, horoš pred očami Gospoda, i k takim On blagovolit», ili: «gde Bog pravosudiâ?»"],[3,1,"Вот, Я посылаю Ангела Моего, и он приготовит путь предо Мною, и внезапно придет в храм Свой Господь, Которого вы ищете, и Ангел завета, Которого вы желаете; вот, Он идет, говорит Господь Саваоф.","Vot, Â posylaû Angela Moego, i on prigotovit putʹ predo Mnoû, i vnezapno pridet v hram Svoj Gospodʹ, Kotorogo vy iŝete, i Angel zaveta, Kotorogo vy želaete; vot, On idet, govorit Gospodʹ Savaof."],[3,2,"И кто выдержит день пришествия Его, и кто устоит, когда Он явится? Ибо Он – как огонь расплавляющий и как щелок очищающий,","I kto vyderžit denʹ prišestviâ Ego, i kto ustoit, kogda On âvitsâ? Ibo On – kak ogonʹ rasplavlâûŝij i kak ŝelok očiŝaûŝij,"],[3,3,"и сядет переплавлять и очищать серебро, и очистит сынов Левия и переплавит их, как золото и как серебро, чтобы приносили жертву Господу в правде.","i sâdet pereplavlâtʹ i očiŝatʹ serebro, i očistit synov Leviâ i pereplavit ih, kak zoloto i kak serebro, čtoby prinosili žertvu Gospodu v pravde."],[3,4,"Тогда благоприятна будет Господу жертва Иуды и Иерусалима, как во дни древние и как в лета прежние.","Togda blagopriâtna budet Gospodu žertva Iudy i Ierusalima, kak vo dni drevnie i kak v leta prežnie."],[3,5,"И приду к вам для суда и буду скорым обличителем чародеев и прелюбодеев и тех, которые клянутся ложно и удерживают плату у наемника, притесняют вдову и сироту, и отталкивают пришельца, и Меня не боятся, говорит Господь Саваоф.","I pridu k vam dlâ suda i budu skorym obličitelem čarodeev i prelûbodeev i teh, kotorye klânutsâ ložno i uderživaût platu u naemnika, pritesnâût vdovu i sirotu, i ottalkivaût prišelʹca, i Menâ ne boâtsâ, govorit Gospodʹ Savaof."],[3,6,"Ибо Я – Господь, Я не изменяюсь; посему вы, сыны Иакова, не уничтожились.","Ibo Â – Gospodʹ, Â ne izmenâûsʹ; posemu vy, syny Iakova, ne uničtožilisʹ."],[3,7,"Со дней отцов ваших вы отступили от уставов Моих и не соблюдаете их; обратитесь ко Мне, и Я обращусь к вам, говорит Господь Саваоф. Вы скажете: «как нам обратиться?»","So dnej otcov vaših vy otstupili ot ustavov Moih i ne soblûdaete ih; obratitesʹ ko Mne, i Â obraŝusʹ k vam, govorit Gospodʹ Savaof. Vy skažete: «kak nam obratitʹsâ?»"],[3,8,"Можно ли человеку обкрадывать Бога? А вы обкрадываете Меня. Скажете: «чем обкрадываем мы Тебя?» Десятиною и приношениями.","Možno li čeloveku obkradyvatʹ Boga? A vy obkradyvaete Menâ. Skažete: «čem obkradyvaem my Tebâ?» Desâtinoû i prinošeniâmi."],[3,9,"Проклятием вы прокляты, потому что вы – весь народ – обкрадываете Меня.","Proklâtiem vy proklâty, potomu čto vy – vesʹ narod – obkradyvaete Menâ."],[3,10,"Принесите все десятины в дом хранилища, чтобы в доме Моем была пища, и хотя в этом испытайте Меня, говорит Господь Саваоф: не открою ли Я для вас отверстий небесных и не изолью ли на вас благословения до избытка?","Prinesite vse desâtiny v dom hraniliŝa, čtoby v dome Moem byla piŝa, i hotâ v étom ispytajte Menâ, govorit Gospodʹ Savaof: ne otkroû li Â dlâ vas otverstij nebesnyh i ne izolʹû li na vas blagosloveniâ do izbytka?"],[3,11,"Я для вас запрещу пожирающим истреблять у вас плоды земные, и виноградная лоза на поле у вас не лишится плодов своих, говорит Господь Саваоф.","Â dlâ vas zapreŝu požiraûŝim istreblâtʹ u vas plody zemnye, i vinogradnaâ loza na pole u vas ne lišitsâ plodov svoih, govorit Gospodʹ Savaof."],[3,12,"И блаженными называть будут вас все народы, потому что вы будете землею вожделенною, говорит Господь Саваоф.","I blažennymi nazyvatʹ budut vas vse narody, potomu čto vy budete zemleû voždelennoû, govorit Gospodʹ Savaof."],[3,13,"Дерзостны предо Мною слова ваши, говорит Господь. Вы скажете: «что мы говорим против Тебя?»","Derzostny predo Mnoû slova vaši, govorit Gospodʹ. Vy skažete: «čto my govorim protiv Tebâ?»"],[3,14,"Вы говорите: «тщетно служение Богу, и что пользы, что мы соблюдали постановления Его и ходили в печальной одежде пред лицом Господа Саваофа?","Vy govorite: «tŝetno služenie Bogu, i čto polʹzy, čto my soblûdali postanovleniâ Ego i hodili v pečalʹnoj odežde pred licom Gospoda Savaofa?"],[3,15,"И ныне мы считаем надменных счастливыми: лучше устраивают себя делающие беззакония, и хотя искушают Бога, но остаются целы».","I nyne my sčitaem nadmennyh sčastlivymi: lučše ustraivaût sebâ delaûŝie bezzakoniâ, i hotâ iskušaût Boga, no ostaûtsâ cely»."],[3,16,"Но боящиеся Бога говорят друг другу: «внимает Господь и слышит это, и пред лицом Его пишется памятная книга о боящихся Господа и чтущих имя Его».","No boâŝiesâ Boga govorât drug drugu: «vnimaet Gospodʹ i slyšit éto, i pred licom Ego pišetsâ pamâtnaâ kniga o boâŝihsâ Gospoda i čtuŝih imâ Ego»."],[3,17,"И они будут Моими, говорит Господь Саваоф, собственностью Моею в тот день, который Я соделаю, и буду миловать их, как милует человек сына своего, служащего ему.","I oni budut Moimi, govorit Gospodʹ Savaof, sobstvennostʹû Moeû v tot denʹ, kotoryj Â sodelaû, i budu milovatʹ ih, kak miluet čelovek syna svoego, služaŝego emu."],[3,18,"И тогда снова увидите различие между праведником и нечестивым, между служащим Богу и не служащим Ему.","I togda snova uvidite različie meždu pravednikom i nečestivym, meždu služaŝim Bogu i ne služaŝim Emu."],[4,1,"Ибо вот, придет день, пылающий как печь; тогда все надменные и поступающие нечестиво будут как солома, и попалит их грядущий день, говорит Господь Саваоф, так что не оставит у них ни корня, ни ветвей.","Ibo vot, pridet denʹ, pylaûŝij kak pečʹ; togda vse nadmennye i postupaûŝie nečestivo budut kak soloma, i popalit ih grâduŝij denʹ, govorit Gospodʹ Savaof, tak čto ne ostavit u nih ni kornâ, ni vetvej."],[4,2,"А для вас, благоговеющие пред именем Моим, взойдет солнце правды и исцеление в лучах его, и вы выйдете и взыграете, как тельцы упитанные;","A dlâ vas, blagogoveûŝie pred imenem Moim, vzojdet solnce pravdy i iscelenie v lučah ego, i vy vyjdete i vzygraete, kak telʹcy upitannye;"],[4,3,"и будете попирать нечестивых, ибо они будут прахом под стопами ног ваших в тот день, который Я соделаю, говорит Господь Саваоф.","i budete popiratʹ nečestivyh, ibo oni budut prahom pod stopami nog vaših v tot denʹ, kotoryj Â sodelaû, govorit Gospodʹ Savaof."],[4,4,"Помните закон Моисея, раба Моего, который Я заповедал ему на Хориве для всего Израиля, равно как и правила и уставы.","Pomnite zakon Moiseâ, raba Moego, kotoryj Â zapovedal emu na Horive dlâ vsego Izrailâ, ravno kak i pravila i ustavy."],[4,5,"Вот, Я пошлю к вам Илию пророка пред наступлением дня Господня, великого и страшного.","Vot, Â pošlû k vam Iliû proroka pred nastupleniem dnâ Gospodnâ, velikogo i strašnogo."],[4,6,"И он обратит сердца отцов к детям и сердца детей к отцам их, чтобы Я, придя, не поразил земли проклятием.","I on obratit serdca otcov k detâm i serdca detej k otcam ih, čtoby Â, pridâ, ne porazil zemli proklâtiem."]],"cmn-cuv-hant":[[1,1,"耶和華藉 瑪拉基傳給 以色列的默示。","yé hé huá jí mǎ lā jī chuán gěi yǐ sè liè de mò shì."],[1,2,"耶和華說：「我曾愛你們。」你們卻說：「你在何事上愛我們呢？」耶和華說：「 以掃不是 雅各的哥哥嗎？我卻愛 雅各，","yé hé huá shuō：‘wǒ céng ài nǐ men.’ nǐ men què shuō：‘nǐ zài hé shì shàng ài wǒ men ne？’ yé hé huá shuō：‘ yǐ sǎo bù shì yǎ gè de gē gē ma？ wǒ què ài yǎ gè，"],[1,3,"惡 以掃，使他的山嶺荒涼，把他的地業 交給曠野的野狗。」","è yǐ sǎo， shǐ tā de shān lǐng huāng liáng， bǎ tā de de yè jiāo gěi kuàng yě de yě gǒu.’"],[1,4,"以東人說：「我們現在雖被毀壞，卻要重建荒廢之處。」萬軍之耶和華如此說：「任他們建造，我必拆毀；人必稱他們的地為『罪惡之境』；稱他們的民為『耶和華永遠惱怒之民』。」","yǐ dōng rén shuō：‘wǒ men xiàn zài suī bèi huǐ huài， què yào zhòng jiàn huāng fèi zhī chù.’ wàn jūn zhī yé hé huá rú cǐ shuō：‘rèn tā men jiàn zào， wǒ bì chāi huǐ； rén bì chēng tā men de de wèi“zuì è zhī jìng”； chēng tā men de mín wèi“yé hé huá yǒng yuǎn nǎo nù zhī mín”.’"],[1,5,"你們必親眼看見，也必說：「願耶和華在 以色列境界之外被尊為大！」","nǐ men bì qīn yǎn kàn jiàn， yě bì shuō：‘yuàn yé hé huá zài yǐ sè liè jìng jiè zhī wài bèi zūn wèi dà！’"],[1,6,"「藐視我名的祭司啊，萬軍之耶和華對你們說：兒子尊敬父親，僕人敬畏主人；我既為父親，尊敬我的在哪裏呢？我既為主人，敬畏我的在哪裏呢？你們卻說：『我們在何事上藐視你的名呢？』","‘miǎo shì wǒ míng de jì sī a， wàn jūn zhī yé hé huá duì nǐ men shuō： ér zǐ zūn jìng fù qīn， pú rén jìng wèi zhǔ rén； wǒ jì wèi fù qīn， zūn jìng wǒ de zài nǎ lǐ ne？ wǒ jì wèi zhǔ rén， jìng wèi wǒ de zài nǎ lǐ ne？ nǐ men què shuō：“wǒ men zài hé shì shàng miǎo shì nǐ de míng ne？”"],[1,7,"你們將污穢的食物獻在我的壇上，且說：『我們在何事上污穢你呢？』因你們說，耶和華的桌子是可藐視的。","nǐ men jiāng wū huì de shí wù xiàn zài wǒ de tán shàng， qiě shuō：“wǒ men zài hé shì shàng wū huì nǐ ne？” yīn nǐ men shuō， yé hé huá de zhuō zǐ shì kě miǎo shì de."],[1,8,"你們將瞎眼的獻為祭物，這不為惡嗎？將瘸腿的、有病的獻上，這不為惡嗎？你獻給你的省長，他豈喜悅你，豈能看你的情面嗎？這是萬軍之耶和華說的。","nǐ men jiāng xiā yǎn de xiàn wèi jì wù， zhè bù wèi è ma？ jiāng qué tuǐ de, yǒu bìng de xiàn shàng， zhè bù wèi è ma？ nǐ xiàn gěi nǐ de shěng zhǎng， tā qǐ xǐ yuè nǐ， qǐ néng kàn nǐ de qíng miàn ma？ zhè shì wàn jūn zhī yé hé huá shuō de."],[1,9,"「現在我勸你們懇求神，他好施恩與我們。這 妄獻的事，既由你們經手，他豈能看你們的情面嗎？這是萬軍之耶和華說的。","‘xiàn zài wǒ quàn nǐ men kěn qiú shén， tā hǎo shī ēn yǔ wǒ men. zhè wàng xiàn de shì， jì yóu nǐ men jīng shǒu， tā qǐ néng kàn nǐ men de qíng miàn ma？ zhè shì wàn jūn zhī yé hé huá shuō de."],[1,10,"甚願你們中間有一人關上 殿門，免得你們徒然在我壇上燒 火。萬軍之耶和華說：我不喜悅你們，也不從你們手中收納供物。","shèn yuàn nǐ men zhōng jiān yǒu yī rén guān shàng diàn mén， miǎn dé nǐ men tú rán zài wǒ tán shàng shāo huǒ. wàn jūn zhī yé hé huá shuō： wǒ bù xǐ yuè nǐ men， yě bù cóng nǐ men shǒu zhōng shōu nà gōng wù."],[1,11,"萬軍之耶和華說：從日出之地到日落之處，我的名在外邦中必尊為大。在各處，人必奉我的名燒香，獻潔淨的供物，因為我的名在外邦中必尊為大。","wàn jūn zhī yé hé huá shuō： cóng rì chū zhī de dào rì luò zhī chù， wǒ de míng zài wài bāng zhōng bì zūn wèi dà. zài gè chù， rén bì fèng wǒ de míng shāo xiāng， xiàn jié jìng de gōng wù， yīn wèi wǒ de míng zài wài bāng zhōng bì zūn wèi dà."],[1,12,"你們卻褻瀆我的名，說：『耶和華的桌子是污穢的，其上的食物是可藐視的。』","nǐ men què xiè dú wǒ de míng， shuō：“yé hé huá de zhuō zǐ shì wū huì de， qí shàng de shí wù shì kě miǎo shì de.”"],[1,13,"你們又說：『這些事何等煩瑣！』並嗤之以鼻。這是萬軍之耶和華說的。你們把搶奪的、瘸腿的、有病的拿來獻上為祭。我豈能從你們手中收納呢？這是耶和華說的。","nǐ men yòu shuō：“zhè xiē shì hé děng fán suǒ！” bìng chī zhī yǐ bí. zhè shì wàn jūn zhī yé hé huá shuō de. nǐ men bǎ qiǎng duó de, qué tuǐ de, yǒu bìng de ná lái xiàn shàng wèi jì. wǒ qǐ néng cóng nǐ men shǒu zhōng shōu nà ne？ zhè shì yé hé huá shuō de."],[1,14,"行詭詐的在群中有公羊，他許願卻用有殘疾的獻給主，這人是可咒詛的。因為我是大君王，我的名在外邦中是可畏的。這是萬軍之耶和華說的。","xíng guǐ zhà de zài qún zhōng yǒu gōng yáng， tā xǔ yuàn què yòng yǒu cán jí de xiàn gěi zhǔ， zhè rén shì kě zhòu zǔ de. yīn wèi wǒ shì dà jūn wáng， wǒ de míng zài wài bāng zhōng shì kě wèi de. zhè shì wàn jūn zhī yé hé huá shuō de."],[2,1,"「眾祭司啊，這誡命是傳給你們的。","‘zhòng jì sī a， zhè jiè mìng shì chuán gěi nǐ men de."],[2,2,"萬軍之耶和華說：你們若不聽從，也不放在心上，將榮耀歸與我的名，我就使咒詛臨到你們，使你們的福分變為咒詛；因你們不把誡命放在心上，我已經咒詛你們了。","wàn jūn zhī yé hé huá shuō： nǐ men ruò bù tīng cóng， yě bù fàng zài xīn shàng， jiāng róng yào guī yǔ wǒ de míng， wǒ jiù shǐ zhòu zǔ lín dào nǐ men， shǐ nǐ men de fú fēn biàn wèi zhòu zǔ； yīn nǐ men bù bǎ jiè mìng fàng zài xīn shàng， wǒ yǐ jīng zhòu zǔ nǐ men le."],[2,3,"我必斥責你們的種子，又把你們犧牲的糞抹在你們的臉上；你們要與糞一同除掉。","wǒ bì chì zé nǐ men de zhǒng zǐ， yòu bǎ nǐ men xī shēng de fèn mǒ zài nǐ men de liǎn shàng； nǐ men yào yǔ fèn yī tóng chú diào."],[2,4,"你們就知道我傳這誡命給你們，使我與 利未所立的約可以常存。這是萬軍之耶和華說的。","nǐ men jiù zhī dào wǒ chuán zhè jiè mìng gěi nǐ men， shǐ wǒ yǔ lì wèi suǒ lì de yuē kě yǐ cháng cún. zhè shì wàn jūn zhī yé hé huá shuō de."],[2,5,"我曾與他立生命和平安的約。我將這兩樣賜給他，使他存敬畏的心，他就敬畏我，懼怕我的名。","wǒ céng yǔ tā lì shēng mìng hé píng ān de yuē. wǒ jiāng zhè liǎng yàng cì gěi tā， shǐ tā cún jìng wèi de xīn， tā jiù jìng wèi wǒ， jù pà wǒ de míng."],[2,6,"真實的律法在他口中，他嘴裏沒有不義的話。他以平安和正直與我同行，使多人回頭離開罪孽。","zhēn shí de lǜ fǎ zài tā kǒu zhōng， tā zuǐ lǐ méi yǒu bù yì de huà. tā yǐ píng ān hé zhèng zhí yǔ wǒ tóng xíng， shǐ duō rén huí tóu lí kāi zuì niè."],[2,7,"祭司的嘴裏當存知識，人也當由他口中尋求律法，因為他是萬軍之耶和華的使者。","jì sī de zuǐ lǐ dāng cún zhī shí， rén yě dāng yóu tā kǒu zhōng xún qiú lǜ fǎ， yīn wèi tā shì wàn jūn zhī yé hé huá de shǐ zhě."],[2,8,"你們卻偏離正道，使許多人在律法上跌倒。你們廢棄 我與 利未所立的約。這是萬軍之耶和華說的。","nǐ men què piān lí zhèng dào， shǐ xǔ duō rén zài lǜ fǎ shàng diē dào. nǐ men fèi qì wǒ yǔ lì wèi suǒ lì de yuē. zhè shì wàn jūn zhī yé hé huá shuō de."],[2,9,"所以我使你們被眾人藐視，看為下賤；因你們不守我的道，竟在律法上瞻徇情面。」","suǒ yǐ wǒ shǐ nǐ men bèi zhòng rén miǎo shì， kàn wèi xià jiàn； yīn nǐ men bù shǒu wǒ de dào， jìng zài lǜ fǎ shàng zhān xùn qíng miàn.’"],[2,10,"我們豈不都是一位父嗎？豈不是一位神所造的嗎？我們各人怎麼以詭詐待弟兄，背棄了 神與我們列祖所立的約呢？","wǒ men qǐ bù dōu shì yī wèi fù ma？ qǐ bù shì yī wèi shén suǒ zào de ma？ wǒ men gè rén zěn me yǐ guǐ zhà dài dì xiōng， bèi qì le shén yǔ wǒ men liè zǔ suǒ lì de yuē ne？"],[2,11,"猶大人行事詭詐，並且在 以色列和 耶路撒冷中行一件可憎的事；因為 猶大人褻瀆耶和華所喜愛的聖潔，娶 事奉外邦神的女子為妻。","yóu dà rén xíng shì guǐ zhà， bìng qiě zài yǐ sè liè hé yé lù sā lěng zhōng xíng yī jiàn kě zēng de shì； yīn wèi yóu dà rén xiè dú yé hé huá suǒ xǐ ài de shèng jié， qǔ shì fèng wài bāng shén de nǚ zǐ wèi qī."],[2,12,"凡行這事的，無論何人，就是獻供物給萬軍之耶和華，耶和華也必從 雅各的帳棚中剪除他。","fán xíng zhè shì de， wú lùn hé rén， jiù shì xiàn gōng wù gěi wàn jūn zhī yé hé huá， yé hé huá yě bì cóng yǎ gè de zhàng péng zhōng jiǎn chú tā."],[2,13,"你們又行了一件這樣的事，使 前妻歎息哭泣的眼淚遮蓋耶和華的壇，以致耶和華不再看顧那供物，也不樂意從你們手中收納。","nǐ men yòu xíng le yī jiàn zhè yàng de shì， shǐ qián qī tàn xī kū qì de yǎn lèi zhē gài yé hé huá de tán， yǐ zhì yé hé huá bù zài kàn gù nà gōng wù， yě bù lè yì cóng nǐ men shǒu zhōng shōu nà."],[2,14,"你們還說：「這是為甚麼呢？」因耶和華在你和你幼年所娶的妻中間作見證。她雖是你的配偶，又是你盟約的妻，你卻以詭詐待她。","nǐ men hái shuō：‘zhè shì wèi shèn me ne？’ yīn yé hé huá zài nǐ hé nǐ yòu nián suǒ qǔ de qī zhōng jiān zuò jiàn zhèng. tā suī shì nǐ de pèi ǒu， yòu shì nǐ méng yuē de qī， nǐ què yǐ guǐ zhà dài tā."],[2,15,"雖然神有靈的餘 力能造多人，他不是單造一人嗎？為何只造一人呢？乃是他願人得虔誠的後裔。所以當謹守你們的心，誰也不可以詭詐待幼年所娶的妻。","suī rán shén yǒu líng de yú lì néng zào duō rén， tā bù shì dān zào yī rén ma？ wèi hé zhǐ zào yī rén ne？ nǎi shì tā yuàn rén dé qián chéng de hòu yì. suǒ yǐ dāng jǐn shǒu nǐ men de xīn， shuí yě bù kě yǐ guǐ zhà dài yòu nián suǒ qǔ de qī."],[2,16,"耶和華－ 以色列的神說：「休妻的事和以強暴待妻的人都是我所恨惡的！所以當謹守你們的心，不可行詭詐。」這是萬軍之耶和華說的。","yé hé huá－ yǐ sè liè de shén shuō：‘xiū qī de shì hé yǐ qiáng bào dài qī de rén dōu shì wǒ suǒ hèn è de！ suǒ yǐ dāng jǐn shǒu nǐ men de xīn， bù kě xíng guǐ zhà.’ zhè shì wàn jūn zhī yé hé huá shuō de."],[2,17,"你們用言語煩瑣耶和華，你們還說：「我們在何事上煩瑣他呢？」因為你們說：「凡行惡的，耶和華眼看為善，並且他喜悅他們」；或說：「公義的神在哪裏呢？」","nǐ men yòng yán yǔ fán suǒ yé hé huá， nǐ men hái shuō：‘wǒ men zài hé shì shàng fán suǒ tā ne？’ yīn wèi nǐ men shuō：‘fán xíng è de， yé hé huá yǎn kàn wèi shàn， bìng qiě tā xǐ yuè tā men’； huò shuō：‘gōng yì de shén zài nǎ lǐ ne？’"],[3,1,"萬軍之耶和華說：「我要差遣我的使者在我前面預備道路。你們所尋求的主必忽然進入他的殿；立約的使者，就是你們所仰慕的，快要來到。」","wàn jūn zhī yé hé huá shuō：‘wǒ yào chà qiǎn wǒ de shǐ zhě zài wǒ qián miàn yù bèi dào lù. nǐ men suǒ xún qiú de zhǔ bì hū rán jìn rù tā de diàn； lì yuē de shǐ zhě， jiù shì nǐ men suǒ yǎng mù de， kuài yào lái dào.’"],[3,2,"他來的日子，誰能當得起呢？他顯現的時候，誰能立得住呢？因為他如煉 金之人的火，如漂布之人的鹼。","tā lái de rì zǐ， shuí néng dāng dé qǐ ne？ tā xiǎn xiàn de shí hòu， shuí néng lì dé zhù ne？ yīn wèi tā rú liàn jīn zhī rén de huǒ， rú piào bù zhī rén de jiǎn."],[3,3,"他必坐下如煉淨銀子的，必潔淨 利未人，熬煉他們像金銀一樣；他們就憑公義獻供物給耶和華。","tā bì zuò xià rú liàn jìng yín zǐ de， bì jié jìng lì wèi rén， áo liàn tā men xiàng jīn yín yī yàng； tā men jiù píng gōng yì xiàn gōng wù gěi yé hé huá."],[3,4,"那時， 猶大和 耶路撒冷所獻的供物必蒙耶和華悅納，彷彿古時之日、上古之年。","nà shí， yóu dà hé yé lù sā lěng suǒ xiàn de gōng wù bì méng yé hé huá yuè nà， páng fú gǔ shí zhī rì, shàng gǔ zhī nián."],[3,5,"萬軍之耶和華說：「我必臨近你們，施行審判。我必速速作見證，警戒行邪術的、犯姦淫的、起假誓的、虧負人之工價的、欺壓寡婦孤兒的、屈枉寄居的，和不敬畏我的。」","wàn jūn zhī yé hé huá shuō：‘wǒ bì lín jìn nǐ men， shī xíng shěn pàn. wǒ bì sù sù zuò jiàn zhèng， jǐng jiè xíng xié shù de, fàn jiān yín de, qǐ jiǎ shì de, kuī fù rén zhī gōng jià de, qī yā guǎ fù gū ér de, qū wǎng jì jū de， hé bù jìng wèi wǒ de.’"],[3,6,"「因我－耶和華是不改變的，所以你們 雅各之子沒有滅亡。","‘yīn wǒ－yé hé huá shì bù gǎi biàn de， suǒ yǐ nǐ men yǎ gè zhī zǐ méi yǒu miè wáng."],[3,7,"萬軍之耶和華說：從你們列祖的日子以來，你們常常偏離我的典章而不遵守。現在你們要轉向我，我就轉向你們。你們卻問說：『我們如何才是轉向呢？』","wàn jūn zhī yé hé huá shuō： cóng nǐ men liè zǔ de rì zǐ yǐ lái， nǐ men cháng cháng piān lí wǒ de diǎn zhāng ér bù zūn shǒu. xiàn zài nǐ men yào zhuǎn xiàng wǒ， wǒ jiù zhuǎn xiàng nǐ men. nǐ men què wèn shuō：“wǒ men rú hé cái shì zhuǎn xiàng ne？”"],[3,8,"人豈可奪取神之物呢？你們竟奪取我 的供物。你們卻說：『我們在何事上奪取你 的供物呢？』就是你們在當納的十分之一和當獻的供物上。","rén qǐ kě duó qǔ shén zhī wù ne？ nǐ men jìng duó qǔ wǒ de gōng wù. nǐ men què shuō：“wǒ men zài hé shì shàng duó qǔ nǐ de gōng wù ne？” jiù shì nǐ men zài dāng nà de shí fēn zhī yī hé dāng xiàn de gōng wù shàng."],[3,9,"因你們通國的人都奪取我 的供物，咒詛就臨到你們身上。","yīn nǐ men tōng guó de rén dōu duó qǔ wǒ de gōng wù， zhòu zǔ jiù lín dào nǐ men shēn shàng."],[3,10,"萬軍之耶和華說：你們要將當納的十分之一全然送入倉庫，使我家有糧，以此試試我，是否為你們敞開天上的窗戶，傾福與你們，甚至無處可容。","wàn jūn zhī yé hé huá shuō： nǐ men yào jiāng dāng nà de shí fēn zhī yī quán rán sòng rù cāng kù， shǐ wǒ jiā yǒu liáng， yǐ cǐ shì shì wǒ， shì fǒu wèi nǐ men chǎng kāi tiān shàng de chuāng hù， qīng fú yǔ nǐ men， shèn zhì wú chù kě róng."],[3,11,"萬軍之耶和華說：我必為你們斥責蝗蟲，不容牠毀壞你們的土產。你們田間的葡萄樹在未熟之先也不掉果子。","wàn jūn zhī yé hé huá shuō： wǒ bì wèi nǐ men chì zé huáng chóng， bù róng tā huǐ huài nǐ men de tǔ chǎn. nǐ men tián jiān de pú táo shù zài wèi shú zhī xiān yě bù diào guǒ zǐ."],[3,12,"萬軍之耶和華說：萬國必稱你們為有福的，因你們的地必成為喜樂之地。」","wàn jūn zhī yé hé huá shuō： wàn guó bì chēng nǐ men wèi yǒu fú de， yīn nǐ men de de bì chéng wèi xǐ lè zhī de.’"],[3,13,"耶和華說：「你們用話頂撞我，你們還說：『我們用甚麼話頂撞了你呢？』","yé hé huá shuō：‘nǐ men yòng huà dǐng zhuàng wǒ， nǐ men hái shuō：“wǒ men yòng shèn me huà dǐng zhuàng le nǐ ne？”"],[3,14,"你們說：『事奉神是徒然的，遵守神所吩咐的，在萬軍之耶和華面前苦苦齋戒，有甚麼益處呢？","nǐ men shuō：“shì fèng shén shì tú rán de， zūn shǒu shén suǒ fēn fù de， zài wàn jūn zhī yé hé huá miàn qián kǔ kǔ zhāi jiè， yǒu shèn me yì chù ne？"],[3,15,"如今我們稱狂傲的人為有福，並且行惡的人得建立；他們雖然試探神，卻得脫離 災難。』」","rú jīn wǒ men chēng kuáng ào de rén wèi yǒu fú， bìng qiě xíng è de rén dé jiàn lì； tā men suī rán shì tàn shén， què dé tuō lí zāi nán.”’"],[3,16,"那時，敬畏耶和華的彼此談論，耶和華側耳而聽，且有紀念冊在他面前，記錄那敬畏耶和華、思念他名的人。","nà shí， jìng wèi yé hé huá de bǐ cǐ tán lùn， yé hé huá cè ěr ér tīng， qiě yǒu jì niàn cè zài tā miàn qián， jì lù nà jìng wèi yé hé huá, sī niàn tā míng de rén."],[3,17,"萬軍之耶和華說：「在我所定的日子，他們必屬我，特特歸我。我必憐恤他們，如同人憐恤服事自己的兒子。","wàn jūn zhī yé hé huá shuō：‘zài wǒ suǒ dìng de rì zǐ， tā men bì shǔ wǒ， tè tè guī wǒ. wǒ bì lián xù tā men， rú tóng rén lián xù fú shì zì jǐ de ér zǐ."],[3,18,"那時你們必歸回，將善人和惡人，事奉神的和不事奉神的，分別出來。」","nà shí nǐ men bì guī huí， jiāng shàn rén hé è rén， shì fèng shén de hé bù shì fèng shén de， fēn bié chū lái.’"],[4,1,"萬軍之耶和華說：「那日臨近，勢如燒着的火爐，凡狂傲的和行惡的必如碎詡，在那日必被燒盡，根本枝條一無存留。","wàn jūn zhī yé hé huá shuō：‘nà rì lín jìn， shì rú shāo zhe de huǒ lú， fán kuáng ào de hé xíng è de bì rú suì xǔ， zài nà rì bì bèi shāo jǐn， gēn běn zhī tiáo yī wú cún liú."],[4,2,"但向你們敬畏我名的人必有公義的日頭出現，其光線有醫治之能。你們必出來跳躍如圈裏的肥犢。","dàn xiàng nǐ men jìng wèi wǒ míng de rén bì yǒu gōng yì de rì tóu chū xiàn， qí guāng xiàn yǒu yī zhì zhī néng. nǐ men bì chū lái tiào yuè rú quān lǐ de féi dú."],[4,3,"你們必踐踏惡人；在我所定的日子，他們必如灰塵在你們腳掌之下。這是萬軍之耶和華說的。","nǐ men bì jiàn tà è rén； zài wǒ suǒ dìng de rì zǐ， tā men bì rú huī chén zài nǐ men jiǎo zhǎng zhī xià. zhè shì wàn jūn zhī yé hé huá shuō de."],[4,4,"「你們當記念我僕人 摩西的律法，就是我在 何烈 山為 以色列眾人所吩咐他的律例典章。","‘nǐ men dāng jì niàn wǒ pú rén mó xī de lǜ fǎ， jiù shì wǒ zài hé liè shān wèi yǐ sè liè zhòng rén suǒ fēn fù tā de lǜ lì diǎn zhāng."],[4,5,"「看哪，耶和華大而可畏之日未到以前，我必差遣先知 以利亞到你們那裏去。","‘kàn nǎ， yé hé huá dà ér kě wèi zhī rì wèi dào yǐ qián， wǒ bì chà qiǎn xiān zhī yǐ lì yà dào nǐ men nà lǐ qù."],[4,6,"他必使父親的心轉向兒女，兒女的心轉向父親，免得我來咒詛遍地。」","tā bì shǐ fù qīn de xīn zhuǎn xiàng ér nǚ， ér nǚ de xīn zhuǎn xiàng fù qīn， miǎn dé wǒ lái zhòu zǔ biàn de.’"]],"arb-vandyck":[[1,1,"وَحْيُ كَلِمَةِ ٱلرَّبِّ لِإِسْرَائِيلَ عَنْ يَدِ مَلَاخِي:","waḥ̊yu kalimaẗi ٱlrãbĩ liại̹s̊rāyỉyla ʿan̊ yadi malākẖī:"],[1,2,"«أَحْبَبْتُكُمْ، قَالَ ٱلرَّبُّ. وَقُلْتُمْ: بِمَ أَحْبَبْتَنَا؟ أَلَيْسَ عِيسُو أَخًا لِيَعْقُوبَ، يَقُولُ ٱلرَّبُّ، وَأَحْبَبْتُ يَعْقُوبَ","«ạảḥ̊bab̊tukum̊, qāla ٱlrãbũ. waqul̊tum̊: bima ạảḥ̊bab̊tanā? ạảlaẙsa ʿīsū ạảkẖaⁿạ līaʿ̊qūba, yaqūlu ٱlrãbũ, wāảḥ̊bab̊tu yaʿ̊qūba"],[1,3,"وَأَبْغَضْتُ عِيسُوَ، وَجَعَلْتُ جِبَالَهُ خَرَابًا وَمِيرَاثَهُ لِذِئَابِ ٱلْبَرِّيَّةِ؟","wāảb̊gẖaḍ̊tu ʿīsūa, wajaʿal̊tu jibālahu kẖarābaⁿạ wamīrātẖahu lidẖīảạbi ٱl̊barĩyãẗi?"],[1,4,"لِأَنَّ أَدُومَ قَالَ: قَدْ هُدِمْنَا، فَنَعُودُ وَنَبْنِي ٱلْخِرَبُ. هَكَذَا قَالَ رَبُّ ٱلْجُنُودِ: هُمْ يَبْنُونَ وَأَنَا أَهْدِمُ. وَيَدْعُونَهُمْ تُخُومَ ٱلشَّرِّ، وَٱلشَّعْبَ ٱلَّذِي غَضِبَ عَلَيْهِ ٱلرَّبُّ إِلَى ٱلْأَبَدِ.","liạảnã ạảdūma qāla: qad̊ hudim̊nā, fanaʿūdu wanab̊nī ٱl̊kẖirabu. hakadẖā qāla rabũ ٱl̊junūdi: hum̊ yab̊nūna wāảnā ạảh̊dimu. wayad̊ʿūnahum̊ tukẖūma ٱlsẖãrĩ, waٱlsẖãʿ̊ba ٱlãdẖī gẖaḍiba ʿalaẙhi ٱlrãbũ ại̹lay̱ ٱl̊ạảbadi."],[1,5,"فَتَرَى أَعْيُنُكُمْ وَتَقُولُونَ: لِيَتَعَظَّمِ ٱلرَّبُّ مِنْ عِنْدِ تُخْمِ إِسْرَائِيلَ.","fataray̱ ạảʿ̊yunukum̊ wataqūlūna: līataʿaẓãmi ٱlrãbũ min̊ ʿin̊di tukẖ̊mi ại̹s̊rāyỉyla."],[1,6,"«ٱلِٱبْنُ يُكْرِمُ أَبَاهُ، وَٱلْعَبْدُ يُكْرِمُ سَيِّدَهُ. فَإِنْ كُنْتُ أَنَا أَبًا، فَأَيْنَ كَرَامَتِي؟ وَإِنْ كُنْتُ سَيِّدًا، فَأَيْنَ هَيْبَتِي؟ قَالَ لَكُمْ رَبُّ ٱلْجُنُودِ. أَيُّهَا ٱلْكَهَنَةُ ٱلْمُحْتَقِرُونَ ٱسْمِي. وَتَقُولُونَ: بِمَ ٱحْتَقَرْنَا ٱسْمَكَ؟","«ٱliٱb̊nu yuk̊rimu ạảbāhu, waٱl̊ʿab̊du yuk̊rimu sayĩdahu. fāi̹n̊ kun̊tu ạảnā ạảbaⁿạ, fāảẙna karāmatī? wāi̹n̊ kun̊tu sayĩdaⁿạ, fāảẙna haẙbatī? qāla lakum̊ rabũ ٱl̊junūdi. ạảyũhā ٱl̊kahanaẗu ٱl̊muḥ̊taqirūna ٱs̊mī. wataqūlūna: bima ٱḥ̊taqar̊nā ٱs̊maka?"],[1,7,"تُقَرِّبُونَ خُبْزًا نَجِسًا عَلَى مَذْبَحِي. وَتَقُولُونَ: بِمَ نَجَّسْنَاكَ؟ بِقَوْلِكُمْ: إِنَّ مَائِدَةَ ٱلرَّبِّ مُحْتَقَرَةٌ.","tuqarĩbūna kẖub̊zaⁿạ najisaⁿạ ʿalay̱ madẖ̊baḥī. wataqūlūna: bima najãs̊nāka? biqaẘlikum̊: ại̹nã māyỉdaẗa ٱlrãbĩ muḥ̊taqaraẗuⁿ."],[1,8,"وَإِنْ قَرَّبْتُمُ ٱلْأَعْمَى ذَبِيحَةً، أَفَلَيْسَ ذَلِكَ شَرًّا؟ وَإِنْ قَرَّبْتُمُ ٱلْأَعْرَجَ وَٱلسَّقِيمَ، أَفَلَيْسَ ذَلِكَ شَرًّا؟ قَرِّبْهُ لِوَالِيكَ، أَفَيَرْضَى عَلَيْكَ أَوْ يَرْفَعُ وَجْهَكَ؟ قَالَ رَبُّ ٱلْجُنُودِ.","wāi̹n̊ qarãb̊tumu ٱl̊ạảʿ̊may̱ dẖabīḥaẗaⁿ, ạảfalaẙsa dẖalika sẖaraⁿ̃ạ? wāi̹n̊ qarãb̊tumu ٱl̊ạảʿ̊raja waٱlsãqīma, ạảfalaẙsa dẖalika sẖaraⁿ̃ạ? qarĩb̊hu liwālīka, ạảfayar̊ḍay̱ ʿalaẙka ạảẘ yar̊faʿu waj̊haka? qāla rabũ ٱl̊junūdi."],[1,9,"وَٱلْآنَ تَرَضَّوْا وَجْهَ ٱللهِ فَيَتَرَاءَفَ عَلَيْنَا. هَذِهِ كَانَتْ مِنْ يَدِكُمْ. هَلْ يَرْفَعُ وَجْهَكُمْ؟ قَالَ رَبُّ ٱلْجُنُودِ.","waٱl̊ậna taraḍãẘạ waj̊ha ٱllhi fayatarāʾafa ʿalaẙnā. hadẖihi kānat̊ min̊ yadikum̊. hal̊ yar̊faʿu waj̊hakum̊? qāla rabũ ٱl̊junūdi."],[1,10,"«مَنْ فِيكُمْ يُغْلِقُ ٱلْبَابَ! بَلْ لَا تُوقِدُونَ عَلَى مَذْبَحِي مَجَّانًا. لَيْسَتْ لِي مَسَّرَةٌ بِكُمْ، قَالَ رَبُّ ٱلْجُنُودِ، وَلَا أَقْبَلُ تَقْدِمَةً مِنْ يَدِكُمْ.","«man̊ fīkum̊ yugẖ̊liqu ٱl̊bāba! bal̊ lā tūqidūna ʿalay̱ madẖ̊baḥī majãạnaⁿạ. laẙsat̊ lī masãraẗuⁿ bikum̊, qāla rabũ ٱl̊junūdi, walā ạảq̊balu taq̊dimaẗaⁿ min̊ yadikum̊."],[1,11,"لِأَنَّهُ مِنْ مَشْرِقِ ٱلشَّمْسِ إِلَى مَغْرِبِهَا ٱسْمِي عَظِيمٌ بَيْنَ ٱلْأُمَمِ، وَفِي كُلِّ مَكَانٍ يُقَرَّبُ لِٱسْمِي بَخُورٌ وَتَقْدِمَةٌ طَاهِرَةٌ، لِأَنَّ ٱسْمِي عَظِيمٌ بَيْنَ ٱلْأُمَمِ، قَالَ رَبُّ ٱلْجُنُودِ.","liạảnãhu min̊ masẖ̊riqi ٱlsẖãm̊si ại̹lay̱ magẖ̊ribihā ٱs̊mī ʿaẓīmuⁿ baẙna ٱl̊ạủmami, wafī kulĩ makāniⁿ yuqarãbu liٱs̊mī bakẖūruⁿ wataq̊dimaẗuⁿ ṭāhiraẗuⁿ, liạảnã ٱs̊mī ʿaẓīmuⁿ baẙna ٱl̊ạủmami, qāla rabũ ٱl̊junūdi."],[1,12,"أَمَّا أَنْتُمْ فَمُنَجِّسُوهُ، بِقَوْلِكُمْ: إِنَّ مَائِدَةَ ٱلرَّبِّ تَنَجَّسَتْ، وَثَمَرَتَهَا مُحْتَقَرٌ طَعَامُهَا.","ạảmãạ ạản̊tum̊ famunajĩsūhu, biqaẘlikum̊: ại̹nã māyỉdaẗa ٱlrãbĩ tanajãsat̊, watẖamaratahā muḥ̊taqaruⁿ ṭaʿāmuhā."],[1,13,"وَقُلْتُمْ: مَا هَذِهِ ٱلْمَشَقَّةُ؟ وَتَأَفَّفْتُمْ عَلَيْهِ، قَالَ رَبُّ ٱلْجُنُودِ. وَجِئْتُمْ بِٱلْمُغْتَصَبِ وَٱلْأَعْرَجِ وَٱلسَّقِيمِ، فَأَتَيْتُمْ بِٱلتَّقْدِمَةِ. فَهَلْ أَقْبَلُهَا مِنْ يَدِكُمْ؟ قَالَ ٱلرَّبُّ.","waqul̊tum̊: mā hadẖihi ٱl̊masẖaqãẗu? watāảfãf̊tum̊ ʿalaẙhi, qāla rabũ ٱl̊junūdi. wajī̊̉tum̊ biٱl̊mugẖ̊taṣabi waٱl̊ạảʿ̊raji waٱlsãqīmi, fāảtaẙtum̊ biٱltãq̊dimaẗi. fahal̊ ạảq̊baluhā min̊ yadikum̊? qāla ٱlrãbũ."],[1,14,"وَمَلْعُونٌ ٱلْمَاكِرُ ٱلَّذِي يُوجَدُ فِي قَطِيعِهِ ذَكَرٌ وَيَنْذُرُ وَيَذْبَحُ لِلسَّيِّدِ عَائِبًا. لِأَنِّي أَنَا مَلِكٌ عَظِيمٌ، قَالَ رَبُّ ٱلْجُنُودِ، وَٱسْمِي مَهِيبٌ بَيْنَ ٱلْأُمَمِ.","wamal̊ʿūnuⁿ ٱl̊mākiru ٱlãdẖī yūjadu fī qaṭīʿihi dẖakaruⁿ wayan̊dẖuru wayadẖ̊baḥu lilsãyĩdi ʿāyỉbaⁿạ. liạảnĩy ạảnā malikuⁿ ʿaẓīmuⁿ, qāla rabũ ٱl̊junūdi, waٱs̊mī mahībuⁿ baẙna ٱl̊ạủmami."],[2,1,"«وَٱلْآنَ إِلَيْكُمْ هَذِهِ ٱلْوَصِيَّةُ أَيُّهَا ٱلْكَهَنَةُ:","«waٱl̊ậna ại̹laẙkum̊ hadẖihi ٱl̊waṣīãẗu ạảyũhā ٱl̊kahanaẗu:"],[2,2,"إِنْ كُنْتُمْ لَا تَسْمَعُونَ وَلَا تَجْعَلُونَ فِي ٱلْقَلْبِ لِتُعْطُوا مَجْدًا لِٱسْمِي، قَالَ رَبُّ ٱلْجُنُودِ. فَإِنِّي أُرْسِلُ عَلَيْكُمُ ٱللَّعْنَ، وَأَلْعَنُ بَرَكَاتِكُمْ، بَلْ قَدْ لَعَنْتُهَا، لِأَنَّكُمْ لَسْتُمْ جَاعِلِينَ فِي ٱلْقَلْبِ.","ại̹n̊ kun̊tum̊ lā tas̊maʿūna walā taj̊ʿalūna fī ٱl̊qal̊bi lituʿ̊ṭūạ maj̊daⁿạ liٱs̊mī, qāla rabũ ٱl̊junūdi. fāi̹nĩy ạủr̊silu ʿalaẙkumu ٱllãʿ̊na, wāảl̊ʿanu barakātikum̊, bal̊ qad̊ laʿan̊tuhā, liạảnãkum̊ las̊tum̊ jāʿilīna fī ٱl̊qal̊bi."],[2,3,"هَأَنَذَا أَنْتَهِرُ لَكُمُ ٱلزَّرْعَ، وَأَمُدُّ ٱلْفَرْثَ عَلَى وُجُوهِكُمْ، فَرْثَ أَعْيَادِكُمْ، فَتُنْزَعُونَ مَعَهُ.","hāảnadẖā ạản̊tahiru lakumu ٱlzãr̊ʿa, wāảmudũ ٱl̊far̊tẖa ʿalay̱ wujūhikum̊, far̊tẖa ạảʿ̊yādikum̊, fatun̊zaʿūna maʿahu."],[2,4,"فَتَعْلَمُونَ أَنِّي أَرْسَلْتُ إِلَيْكُمْ هَذِهِ ٱلْوَصِيَّةَ لِكَوْنِ عَهْدِي مَعَ لَاوِي، قَالَ رَبُّ ٱلْجُنُودِ.","fataʿ̊lamūna ạảnĩy ạảr̊sal̊tu ại̹laẙkum̊ hadẖihi ٱl̊waṣīãẗa likaẘni ʿah̊dī maʿa lāwī, qāla rabũ ٱl̊junūdi."],[2,5,"كَانَ عَهْدِي مَعَهُ لِلْحَيَاةِ وَٱلسَّلَامِ، وَأَعْطَيْتُهُ إِيَّاهُمَا لِلتَّقْوَى. فَٱتَّقَانِي، وَمِنِ ٱسْمِي ٱرْتَاعَ هُوَ.","kāna ʿah̊dī maʿahu lil̊ḥayāẗi waٱlsãlāmi, wāảʿ̊ṭaẙtuhu ại̹yãạhumā liltãq̊way̱. faٱtãqānī, wamini ٱs̊mī ٱr̊tāʿa hūa."],[2,6,"شَرِيعَةُ ٱلْحَقِّ كَانَتْ فِي فِيهِ، وَإِثْمٌ لَمْ يُوجَدْ فِي شَفَتَيْهِ. سَلَكَ مَعِي فِي ٱلسَّلَامِ وَٱلِٱسْتِقَامَةِ، وَأَرْجَعَ كَثِيرِينَ عَنِ ٱلْإِثْمِ.","sẖarīʿaẗu ٱl̊ḥaqĩ kānat̊ fī fīhi, wāi̹tẖ̊muⁿ lam̊ yūjad̊ fī sẖafataẙhi. salaka maʿī fī ٱlsãlāmi waٱliٱs̊tiqāmaẗi, wāảr̊jaʿa katẖīrīna ʿani ٱl̊ại̹tẖ̊mi."],[2,7,"لِأَنَّ شَفَتَيِ ٱلْكَاهِنِ تَحْفَظَانِ مَعْرِفَةً، وَمِنْ فَمِهِ يَطْلُبُونَ ٱلشَّرِيعَةَ، لِأَنَّهُ رَسُولُ رَبِّ ٱلْجُنُودِ.","liạảnã sẖafatayi ٱl̊kāhini taḥ̊faẓāni maʿ̊rifaẗaⁿ, wamin̊ famihi yaṭ̊lubūna ٱlsẖãrīʿaẗa, liạảnãhu rasūlu rabĩ ٱl̊junūdi."],[2,8,"أَمَّا أَنْتُمْ فَحِدْتُمْ عَنِ ٱلطَّرِيقِ وَأَعْثَرْتُمْ كَثِيرِينَ بِٱلشَّرِيعَةِ. أَفْسَدْتُمْ عَهْدَ لَاوِي، قَالَ رَبُّ ٱلْجُنُودِ.","ạảmãạ ạản̊tum̊ faḥid̊tum̊ ʿani ٱlṭãrīqi wāảʿ̊tẖar̊tum̊ katẖīrīna biٱlsẖãrīʿaẗi. ạảf̊sad̊tum̊ ʿah̊da lāwī, qāla rabũ ٱl̊junūdi."],[2,9,"فَأَنَا أَيْضًا صَيَّرْتُكُمْ مُحْتَقَرِينَ وَدَنِيئِينَ عِنْدَ كُلِّ ٱلشَّعْبِ، كَمَا أَنَّكُمْ لَمْ تَحْفَظُوا طُرُقِي بَلْ حَابَيْتُمْ فِي ٱلشَّرِيعَةِ».","fāảnā ạảẙḍaⁿạ ṣayãr̊tukum̊ muḥ̊taqarīna wadanīyỉyna ʿin̊da kulĩ ٱlsẖãʿ̊bi, kamā ạảnãkum̊ lam̊ taḥ̊faẓūạ ṭuruqī bal̊ ḥābaẙtum̊ fī ٱlsẖãrīʿaẗi»."],[2,10,"أَلَيْسَ أَبٌ وَاحِدٌ لِكُلِّنَا؟ أَلَيْسَ إِلَهٌ وَاحِدٌ خَلَقَنَا؟ فَلِمَ نَغْدُرُ ٱلرَّجُلُ بِأَخِيهِ لِتَدْنِيسِ عَهْدِ آبَائِنَا؟","ạảlaẙsa ạảbuⁿ wāḥiduⁿ likulĩnā? ạảlaẙsa ại̹lahuⁿ wāḥiduⁿ kẖalaqanā? falima nagẖ̊duru ٱlrãjulu biạảkẖīhi litad̊nīsi ʿah̊di ậbāyỉnā?"],[2,11,"غَدَرَ يَهُوذَا، وَعُمِلَ ٱلرِّجْسُ فِي إِسْرَائِيلَ وَفِي أُورُشَلِيمَ. لِأَنَّ يَهُوذَا قَدْ نَجَّسَ قُدْسَ ٱلرَّبِّ ٱلَّذِي أَحَبَّهُ، وَتَزَوَّجَ بِنْتَ إِلَهٍ غَرِيبٍ.","gẖadara yahūdẖā, waʿumila ٱlrĩj̊su fī ại̹s̊rāyỉyla wafī ạủwrusẖalīma. liạảnã yahūdẖā qad̊ najãsa qud̊sa ٱlrãbĩ ٱlãdẖī ạảḥabãhu, watazawãja bin̊ta ại̹lahiⁿ gẖarībiⁿ."],[2,12,"يَقْطَعُ ٱلرَّبُّ ٱلرَّجُلَ ٱلَّذِي يَفْعَلُ هَذَا، ٱلسَّاهِرَ وَٱلْمُجِيبَ مِنْ خِيَامِ يَعْقُوبَ، وَمَنْ يُقَرِّبُ تَقْدِمَةً لِرَبِّ ٱلْجُنُودِ.","yaq̊ṭaʿu ٱlrãbũ ٱlrãjula ٱlãdẖī yaf̊ʿalu hadẖā, ٱlsãạhira waٱl̊mujība min̊ kẖīāmi yaʿ̊qūba, waman̊ yuqarĩbu taq̊dimaẗaⁿ lirabĩ ٱl̊junūdi."],[2,13,"وَقَدْ فَعَلْتُمْ هَذَا ثَانِيَةً مُغَطِّينَ مَذْبَحَ ٱلرَّبِّ بِٱلدُّمُوعِ، بِٱلْبُكَاءِ وَٱلصُّرَاخِ، فَلَا تُرَاعَى ٱلتَّقْدِمَةُ بَعْدُ، وَلَا يُقْبَلُ ٱلْمُرْضِي مِنْ يَدِكُمْ.","waqad̊ faʿal̊tum̊ hadẖā tẖānīaẗaⁿ mugẖaṭĩyna madẖ̊baḥa ٱlrãbĩ biٱldũmūʿi, biٱl̊bukāʾi waٱlṣũrākẖi, falā turāʿay̱ ٱltãq̊dimaẗu baʿ̊du, walā yuq̊balu ٱl̊mur̊ḍī min̊ yadikum̊."],[2,14,"فَقُلْتُمْ: «لِمَاذَا؟» مِنْ أَجْلِ أَنَّ ٱلرَّبَّ هُوَ ٱلشَّاهِدُ بَيْنَكَ وَبَيْنَ ٱمْرَأَةِ شَبَابِكَ ٱلَّتِي أَنْتَ غَدَرْتَ بِهَا، وَهِيَ قَرِينَتُكَ وَٱمْرَأَةُ عَهْدِكَ.","faqul̊tum̊: «limādẖā?» min̊ ạảj̊li ạảnã ٱlrãbã hūa ٱlsẖãạhidu baẙnaka wabaẙna ٱm̊rāảẗi sẖabābika ٱlãtī ạản̊ta gẖadar̊ta bihā, wahīa qarīnatuka waٱm̊rāảẗu ʿah̊dika."],[2,15,"أَفَلَمْ يَفْعَلْ وَاحِدٌ وَلَهُ بَقِيَّةُ ٱلرُّوحِ؟ وَلِمَاذَا ٱلْوَاحِدُ؟ طَالِبًا زَرْعَ ٱللهِ. فَٱحْذَرُوا لِرُوحِكُمْ وَلَا يَغْدُرْ أَحَدٌ بِٱمْرَأَةِ شَبَابِهِ.","ạảfalam̊ yaf̊ʿal̊ wāḥiduⁿ walahu baqīãẗu ٱlrũwḥi? walimādẖā ٱl̊wāḥidu? ṭālibaⁿạ zar̊ʿa ٱllhi. faٱḥ̊dẖarūạ lirūḥikum̊ walā yagẖ̊dur̊ ạảḥaduⁿ biٱm̊rāảẗi sẖabābihi."],[2,16,"«لِأَنَّهُ يَكْرَهُ ٱلطَّلَاقَ، قَالَ ٱلرَّبُّ إِلَهُ إِسْرَائِيلَ، وَأَنْ يُغَطِّيَ أَحَدٌ ٱلظُّلْمَ بِثَوْبِهِ، قَالَ رَبُّ ٱلْجُنُودِ. فَٱحْذَرُوا لِرُوحِكُمْ لِئَلَّا تَغْدُرُوا».","«liạảnãhu yak̊rahu ٱlṭãlāqa, qāla ٱlrãbũ ại̹lahu ại̹s̊rāyỉyla, wāản̊ yugẖaṭĩya ạảḥaduⁿ ٱlẓũl̊ma bitẖaẘbihi, qāla rabũ ٱl̊junūdi. faٱḥ̊dẖarūạ lirūḥikum̊ līảlãạ tagẖ̊durūạ»."],[2,17,"لَقَدْ أَتْعَبْتُمُ ٱلرَّبَّ بِكَلَامِكُمْ. وَقُلْتُمْ: «بِمَ أَتْعَبْنَاهُ؟» بِقَوْلِكُمْ: «كُلُّ مَنْ يَفْعَلُ ٱلشَّرَّ فَهُوَ صَالِحٌ فِي عَيْنَيِ ٱلرَّبِّ، وَهُوَ يُسَرُّ بِهِمْ». أَوْ: «أَيْنَ إِلَهُ ٱلْعَدْلِ؟».","laqad̊ ạảt̊ʿab̊tumu ٱlrãbã bikalāmikum̊. waqul̊tum̊: «bima ạảt̊ʿab̊nāhu?» biqaẘlikum̊: «kulũ man̊ yaf̊ʿalu ٱlsẖãrã fahūa ṣāliḥuⁿ fī ʿaẙnayi ٱlrãbĩ, wahūa yusarũ bihim̊». ạảẘ: «ạảẙna ại̹lahu ٱl̊ʿad̊li?»."],[3,1,"«هَأَنَذَا أُرْسِلُ مَلَاكِي فَيُهَيِّئُ ٱلطَّرِيقَ أَمَامِي. وَيَأْتِي بَغْتَةً إِلَى هَيْكَلِهِ ٱلسَّيِّدُ ٱلَّذِي تَطْلُبُونَهُ، وَمَلَاكُ ٱلْعَهْدِ ٱلَّذِي تُسَرُّونَ بِهِ. هُوَذَا يَأْتِي، قَالَ رَبُّ ٱلْجُنُودِ»","«hāảnadẖā ạủr̊silu malākī fayuhayĩyủ ٱlṭãrīqa ạảmāmī. wayā̊̉tī bagẖ̊taẗaⁿ ại̹lay̱ haẙkalihi ٱlsãyĩdu ٱlãdẖī taṭ̊lubūnahu, wamalāku ٱl̊ʿah̊di ٱlãdẖī tusarũwna bihi. hūadẖā yā̊̉tī, qāla rabũ ٱl̊junūdi»"],[3,2,"وَمَنْ يَحْتَمِلُ يَوْمَ مَجِيئِهِ؟ وَمَنْ يَثْبُتُ عِنْدَ ظُهُورِهِ؟ لِأَنَّهُ مِثْلُ نَارِ ٱلْمُمَحِّصِ، وَمِثْلُ أَشْنَانِ ٱلْقَصَّارِ.","waman̊ yaḥ̊tamilu yaẘma majīyỉhi? waman̊ yatẖ̊butu ʿin̊da ẓuhūrihi? liạảnãhu mitẖ̊lu nāri ٱl̊mumaḥĩṣi, wamitẖ̊lu ạảsẖ̊nāni ٱl̊qaṣãạri."],[3,3,"فَيَجْلِسُ مُمَحِّصًا وَمُنَقِّيًا لِلْفِضَّةِ. فَيُنَقِّي بَنِي لَاوِي وَيُصَفِّيهِمْ كَٱلذَّهَبِ وَٱلْفِضَّةِ، لِيَكُونُوا مُقَرَّبِينَ لِلرَّبِّ، تَقْدِمَةً بِٱلْبِرِّ.","fayaj̊lisu mumaḥĩṣaⁿạ wamunaqĩyaⁿạ lil̊fiḍãẗi. fayunaqĩy banī lāwī wayuṣafĩyhim̊ kaٱldẖãhabi waٱl̊fiḍãẗi, līakūnūạ muqarãbīna lilrãbĩ, taq̊dimaẗaⁿ biٱl̊birĩ."],[3,4,"فَتَكُونُ تَقْدِمَةُ يَهُوذَا وَأُورُشَلِيمَ مَرْضِيَّةً لِلرَّبِّ كَمَا فِي أَيَّامِ ٱلْقِدَمِ وَكَمَا فِي ٱلسِّنِينَ ٱلْقَدِيمَةِ.","fatakūnu taq̊dimaẗu yahūdẖā wāủwrusẖalīma mar̊ḍīãẗaⁿ lilrãbĩ kamā fī ạảyãạmi ٱl̊qidami wakamā fī ٱlsĩnīna ٱl̊qadīmaẗi."],[3,5,"«وَأَقْتَرِبُ إِلَيْكُمْ لِلْحُكْمِ، وَأَكُونُ شَاهِدًا سَرِيعًا عَلَى ٱلسَّحَرَةِ وَعَلَى ٱلْفَاسِقِينَ وَعَلَى ٱلْحَالِفِينَ زُورًا وَعَلَى ٱلسَّالِبِينَ أُجْرَةَ ٱلْأَجِيرِ: ٱلْأَرْمَلَةِ وَٱلْيَتِيمِ، وَمَنْ يَصُدُّ ٱلْغَرِيبَ وَلَا يَخْشَانِي، قَالَ رَبُّ ٱلْجُنُودِ.","«wāảq̊taribu ại̹laẙkum̊ lil̊ḥuk̊mi, wāảkūnu sẖāhidaⁿạ sarīʿaⁿạ ʿalay̱ ٱlsãḥaraẗi waʿalay̱ ٱl̊fāsiqīna waʿalay̱ ٱl̊ḥālifīna zūraⁿạ waʿalay̱ ٱlsãạlibīna ạủj̊raẗa ٱl̊ạảjīri: ٱl̊ạảr̊malaẗi waٱl̊yatīmi, waman̊ yaṣudũ ٱl̊gẖarība walā yakẖ̊sẖānī, qāla rabũ ٱl̊junūdi."],[3,6,"لِأَنِّي أَنَا ٱلرَّبُّ لَا أَتَغَيَّرُ فَأَنْتُمْ يَا بَنِي يَعْقُوبَ لَمْ تَفْنَوْا.","liạảnĩy ạảnā ٱlrãbũ lā ạảtagẖayãru fāản̊tum̊ yā banī yaʿ̊qūba lam̊ taf̊naẘạ."],[3,7,"«مِنْ أَيَّامِ آبَائِكُمْ حِدْتُمْ عَنْ فَرَائِضِي وَلَمْ تَحْفَظُوهَا. ٱرْجِعُوا إِلَيَّ أَرْجِعْ إِلَيْكُمْ، قَالَ رَبُّ ٱلْجُنُودِ. فَقُلْتُمْ: بِمَاذَا نَرْجِعُ؟","«min̊ ạảyãạmi ậbāyỉkum̊ ḥid̊tum̊ ʿan̊ farāyỉḍī walam̊ taḥ̊faẓūhā. ٱr̊jiʿūạ ại̹layã ạảr̊jiʿ̊ ại̹laẙkum̊, qāla rabũ ٱl̊junūdi. faqul̊tum̊: bimādẖā nar̊jiʿu?"],[3,8,"أَيَسْلُبُ ٱلْإِنْسَانُ ٱللهَ؟ فَإِنَّكُمْ سَلَبْتُمُونِي. فَقُلْتُمْ: بِمَ سَلَبْنَاكَ؟ فِي ٱلْعُشُورِ وَٱلتَّقْدِمَةِ.","ạảyas̊lubu ٱl̊ại̹n̊sānu ٱllha? fāi̹nãkum̊ salab̊tumūnī. faqul̊tum̊: bima salab̊nāka? fī ٱl̊ʿusẖūri waٱltãq̊dimaẗi."],[3,9,"قَدْ لُعِنْتُمْ لَعْنًا وَإِيَّايَ أَنْتُمْ سَالِبُونَ، هَذِهِ ٱلْأُمَّةُ كُلُّهَا.","qad̊ luʿin̊tum̊ laʿ̊naⁿạ wāi̹yãạya ạản̊tum̊ sālibūna, hadẖihi ٱl̊ạủmãẗu kulũhā."],[3,10,"هَاتُوا جَمِيعَ ٱلْعُشُورِ إِلَى ٱلْخَزْنَةِ لِيَكُونَ فِي بَيْتِي طَعَامٌ، وَجَرِّبُونِي بِهَذَا، قَالَ رَبُّ ٱلْجُنُودِ، إِنْ كُنْتُ لَا أَفْتَحُ لَكُمْ كُوَى ٱلسَّمَاوَاتِ، وَأَفِيضُ عَلَيْكُمْ بَرَكَةً حَتَّى لَا تُوسَعَ.","hātūạ jamīʿa ٱl̊ʿusẖūri ại̹lay̱ ٱl̊kẖaz̊naẗi līakūna fī baẙtī ṭaʿāmuⁿ, wajarĩbūnī bihadẖā, qāla rabũ ٱl̊junūdi, ại̹n̊ kun̊tu lā ạảf̊taḥu lakum̊ kūay̱ ٱlsãmāwāti, wāảfīḍu ʿalaẙkum̊ barakaẗaⁿ ḥatãy̱ lā tūsaʿa."],[3,11,"وَأَنْتَهِرُ مِنْ أَجْلِكُمْ ٱلْآكِلَ فَلَا يُفْسِدُ لَكُمْ ثَمَرَ ٱلْأَرْضِ، وَلَا يُعْقَرُ لَكُمُ ٱلْكَرْمُ فِي ٱلْحَقْلِ، قَالَ رَبُّ ٱلْجُنُودِ.","wāản̊tahiru min̊ ạảj̊likum̊ ٱl̊ậkila falā yuf̊sidu lakum̊ tẖamara ٱl̊ạảr̊ḍi, walā yuʿ̊qaru lakumu ٱl̊kar̊mu fī ٱl̊ḥaq̊li, qāla rabũ ٱl̊junūdi."],[3,12,"وَيُطَوِّبُكُمْ كُلُّ ٱلْأُمَمِ، لِأَنَّكُمْ تَكُونُونَ أَرْضَ مَسَرَّةٍ، قَالَ رَبُّ ٱلْجُنُودِ.","wayuṭawĩbukum̊ kulũ ٱl̊ạủmami, liạảnãkum̊ takūnūna ạảr̊ḍa masarãẗiⁿ, qāla rabũ ٱl̊junūdi."],[3,13,"«أَقْوَالُكُمُ ٱشْتَدَّتْ عَلَيَّ، قَالَ ٱلرَّبُّ. وَقُلْتُمْ: مَاذَا قُلْنَا عَلَيْكَ؟","«ạảq̊wālukumu ٱsẖ̊tadãt̊ ʿalayã, qāla ٱlrãbũ. waqul̊tum̊: mādẖā qul̊nā ʿalaẙka?"],[3,14,"قُلْتُمْ: عِبَادَةُ ٱللهِ بَاطِلَةٌ، وَمَا ٱلْمَنْفَعَةُ مِنْ أَنَّنَا حَفِظْنَا شَعَائِرَهُ، وَأَنَّنَا سَلَكْنَا بِٱلْحُزْنِ قُدَّامَ رَبِّ ٱلْجُنُودِ؟","qul̊tum̊: ʿibādaẗu ٱllhi bāṭilaẗuⁿ, wamā ٱl̊man̊faʿaẗu min̊ ạảnãnā ḥafiẓ̊nā sẖaʿāyỉrahu, wāảnãnā salak̊nā biٱl̊ḥuz̊ni qudãạma rabĩ ٱl̊junūdi?"],[3,15,"وَٱلْآنَ نَحْنُ مُطَوِّبُونَ ٱلْمُسْتَكْبِرِينَ وَأَيْضًا فَاعِلُو ٱلشَّرِّ يُبْنَوْنَ. بَلْ جَرَّبُوا ٱللهَ وَنَجَوْا».","waٱl̊ậna naḥ̊nu muṭawĩbūna ٱl̊mus̊tak̊birīna wāảẙḍaⁿạ fāʿilū ٱlsẖãrĩ yub̊naẘna. bal̊ jarãbūạ ٱllha wanajaẘạ»."],[3,16,"حِينَئِذٍ كَلَّمَ مُتَّقُو ٱلرَّبِّ كُلُّ وَاحِدٍ قَرِيبَهُ، وَٱلرَّبُّ أَصْغَى وَسَمِعَ، وَكُتِبَ أَمَامَهُ سِفْرُ تَذْكَرَةٍ لِلَّذِينَ ٱتَّقُوا ٱلرَّبَّ وَلِلْمُفَكِّرِينَ فِي ٱسْمِهِ.","ḥīnayỉdẖiⁿ kalãma mutãqū ٱlrãbĩ kulũ wāḥidiⁿ qarībahu, waٱlrãbũ ạảṣ̊gẖay̱ wasamiʿa, wakutiba ạảmāmahu sif̊ru tadẖ̊karaẗiⁿ lilãdẖīna ٱtãqūạ ٱlrãbã walil̊mufakĩrīna fī ٱs̊mihi."],[3,17,"«وَيَكُونُونَ لِي، قَالَ رَبُّ ٱلْجُنُودِ، فِي ٱلْيَوْمِ ٱلَّذِي أَنَا صَانِعٌ خَاصَّةً، وَأُشْفِقُ عَلَيْهِمْ كَمَا يُشْفِقُ ٱلْإِنْسَانُ عَلَى ٱبْنِهِ ٱلَّذِي يَخْدِمُهُ.","«wayakūnūna lī, qāla rabũ ٱl̊junūdi, fī ٱl̊yaẘmi ٱlãdẖī ạảnā ṣāniʿuⁿ kẖāṣãẗaⁿ, wāủsẖ̊fiqu ʿalaẙhim̊ kamā yusẖ̊fiqu ٱl̊ại̹n̊sānu ʿalay̱ ٱb̊nihi ٱlãdẖī yakẖ̊dimuhu."],[3,18,"فَتَعُودُونَ وَتُمَيِّزُونَ بَيْنَ ٱلصِّدِّيقِ وَٱلشِّرِّيرِ، بَيْنَ مَنْ يَعْبُدُ ٱللهَ وَمَنْ لَا يَعْبُدُهُ.","fataʿūdūna watumayĩzūna baẙna ٱlṣĩdĩyqi waٱlsẖĩrĩyri, baẙna man̊ yaʿ̊budu ٱllha waman̊ lā yaʿ̊buduhu."],[4,1,"«فَهُوَذَا يَأْتِي ٱلْيَوْمُ ٱلْمُتَّقِدُ كَٱلتَّنُّورِ، وَكُلُّ ٱلْمُسْتَكْبِرِينَ وَكُلُّ فَاعِلِي ٱلشَّرِّ يَكُونُونَ قَشًّا، وَيُحْرِقُهُمُ ٱلْيَوْمُ ٱلْآتِي، قَالَ رَبُّ ٱلْجُنُودِ، فَلَا يُبْقِي لَهُمْ أَصْلًا وَلَا فَرْعًا.","«fahūadẖā yā̊̉tī ٱl̊yaẘmu ٱl̊mutãqidu kaٱltãnũwri, wakulũ ٱl̊mus̊tak̊birīna wakulũ fāʿilī ٱlsẖãrĩ yakūnūna qasẖaⁿ̃ạ, wayuḥ̊riquhumu ٱl̊yaẘmu ٱl̊ậtī, qāla rabũ ٱl̊junūdi, falā yub̊qī lahum̊ ạảṣ̊laⁿạ walā far̊ʿaⁿạ."],[4,2,"«وَلَكُمْ أَيُّهَا ٱلْمُتَّقُونَ ٱسْمِي تُشْرِقُ شَمْسُ ٱلْبِرِّ وَٱلشِّفَاءُ فِي أَجْنِحَتِهَا، فَتَخْرُجُونَ وَتَنْشَأُونَ كَعُجُولِ ٱلصِّيرَةِ.","«walakum̊ ạảyũhā ٱl̊mutãqūna ٱs̊mī tusẖ̊riqu sẖam̊su ٱl̊birĩ waٱlsẖĩfāʾu fī ạảj̊niḥatihā, fatakẖ̊rujūna watan̊sẖāủwna kaʿujūli ٱlṣĩyraẗi."],[4,3,"وَتَدُوسُونَ ٱلْأَشْرَارَ لِأَنَّهُمْ يَكُونُونَ رَمَادًا تَحْتَ بُطُونِ أَقْدَامِكُمْ يَوْمَ أَفْعَلُ هَذَا، قَالَ رَبُّ ٱلْجُنُودِ.","watadūsūna ٱl̊ạảsẖ̊rāra liạảnãhum̊ yakūnūna ramādaⁿạ taḥ̊ta buṭūni ạảq̊dāmikum̊ yaẘma ạảf̊ʿalu hadẖā, qāla rabũ ٱl̊junūdi."],[4,4,"«اُذْكُرُوا شَرِيعَةَ مُوسَى عَبْدِي ٱلَّتِي أَمَرْتُهُ بِهَا فِي حُورِيبَ عَلَى كُلِّ إِسْرَائِيلَ. ٱلْفَرَائِضَ وَٱلْأَحْكَامَ.","«ạudẖ̊kurūạ sẖarīʿaẗa mūsay̱ ʿab̊dī ٱlãtī ạảmar̊tuhu bihā fī ḥūrība ʿalay̱ kulĩ ại̹s̊rāyỉyla. ٱl̊farāyỉḍa waٱl̊ạảḥ̊kāma."],[4,5,"«هَأَنَذَا أُرْسِلُ إِلَيْكُمْ إِيلِيَّا ٱلنَّبِيَّ قَبْلَ مَجِيءِ يَوْمِ ٱلرَّبِّ، ٱلْيَوْمِ ٱلْعَظِيمِ وَٱلْمَخُوفِ،","«hāảnadẖā ạủr̊silu ại̹laẙkum̊ ại̹ylīãạ ٱlnãbīã qab̊la majīʾi yaẘmi ٱlrãbĩ, ٱl̊yaẘmi ٱl̊ʿaẓīmi waٱl̊makẖūfi,"],[4,6,"فَيَرُدُّ قَلْبَ ٱلْآبَاءِ عَلَى ٱلْأَبْنَاءِ، وَقَلْبَ ٱلْأَبْنَاءِ عَلَى آبَائِهِمْ. لِئَلَّا آتِيَ وَأَضْرِبَ ٱلْأَرْضَ بِلَعْنٍ».","fayarudũ qal̊ba ٱl̊ậbāʾi ʿalay̱ ٱl̊ạảb̊nāʾi, waqal̊ba ٱl̊ạảb̊nāʾi ʿalay̱ ậbāyỉhim̊. līảlãạ ậtīa wāảḍ̊riba ٱl̊ạảr̊ḍa bilaʿ̊niⁿ»."]],"bis-obbr":[[1,1,"Ol tok blong buk ya, Hae God i givim long Profet Malakae, blong hem i go talemaot long ol laen* blong Isrel.*","Ol tok blong buk ya, Hae God i givim long Profet Malakae, blong hem i go talemaot long ol laen* blong Isrel.*"],[1,2,"Nao Profet Malakae i talem se, “Olgeta. Hae God i talem long yumi se, ‘Ol laen* blong Isrel.* Oltaem mi mi lavem yufala.’ “Be yufala i stap talem long hem se, ‘?Yu yu soemaot olsem wanem long mifala se yu lavem mifala tumas?’ “Nao hem i talem long yufala se, ‘Bifo, i gat tufala brata i stap, wan, nem blong hem Esao, mo narawan, nem blong hem Jekob.* Jekob wetem olgeta we oli kamaot biaen long hem, mi mi lavem olgeta moa.","Nao Profet Malakae i talem se, “Olgeta. Hae God i talem long yumi se, ‘Ol laen* blong Isrel.* Oltaem mi mi lavem yufala.’ “Be yufala i stap talem long hem se, ‘?Yu yu soemaot olsem wanem long mifala se yu lavem mifala tumas?’ “Nao hem i talem long yufala se, ‘Bifo, i gat tufala brata i stap, wan, nem blong hem Esao, mo narawan, nem blong hem Jekob.* Jekob wetem olgeta we oli kamaot biaen long hem, mi mi lavem olgeta moa."],[1,3,"Be Esao, wetem olgeta we oli kamaot biaen long hem, mi mi no laekem olgeta nating, mi agens long olgeta. Taswe kantri ya blong olgeta we i ples blong hil, mi mi spolemgud, mi mekem i stap nating, i kam ples blong ol wael anamol.’ ”","Be Esao, wetem olgeta we oli kamaot biaen long hem, mi mi no laekem olgeta nating, mi agens long olgeta. Taswe kantri ya blong olgeta we i ples blong hil, mi mi spolemgud, mi mekem i stap nating, i kam ples blong ol wael anamol.’ ”"],[1,4,"Mo profet i talem se, “Olgeta ya oli man Edom, mo sipos oli talem se, ‘Naoia Hae God i spolem finis ol taon ya blong yumi, be bambae yumi wokemgud olgeta bakegen,’ be Hae God i gat olgeta paoa, mo bambae hem i talem se, ‘Nating sipos oli stanemap ol taon blong olgeta bakegen be mi bambae mi spolem olgeta yet. Nao ol man bambae oli singaot olgeta, se “Ol man blong mekem nogud”, mo “Ol man we oltaem Hae God i stap kros long olgeta”.","Mo profet i talem se, “Olgeta ya oli man Edom, mo sipos oli talem se, ‘Naoia Hae God i spolem finis ol taon ya blong yumi, be bambae yumi wokemgud olgeta bakegen,’ be Hae God i gat olgeta paoa, mo bambae hem i talem se, ‘Nating sipos oli stanemap ol taon blong olgeta bakegen be mi bambae mi spolem olgeta yet. Nao ol man bambae oli singaot olgeta, se “Ol man blong mekem nogud”, mo “Ol man we oltaem Hae God i stap kros long olgeta”."],[1,5,"“ ‘Ol laen blong Isrel. Ol samting ya bambae yufala i luk stret long ae blong yufala. Mo taem yufala i luk, bambae yufala i save talem se, “!I tru tumas! Hae God i stap soemaot paoa blong hem long ples blong yumi ol laen blong Isrel, be i no long ples blong yumi nomo, hem i stap soemaot paoa blong hem long ol narafala ples tu.” ’ ”","“ ‘Ol laen blong Isrel. Ol samting ya bambae yufala i luk stret long ae blong yufala. Mo taem yufala i luk, bambae yufala i save talem se, “!I tru tumas! Hae God i stap soemaot paoa blong hem long ples blong yumi ol laen blong Isrel, be i no long ples blong yumi nomo, hem i stap soemaot paoa blong hem long ol narafala ples tu.” ’ ”"],[1,6,"Nao Profet Malakae i talem se, “Hae God i gat olgeta paoa, mo hem i talem se, ‘Ol pris. Oltaem, pikinini i save ona long papa blong hem, mo man blong wok i save ona gud long masta blong hem. Mi mi papa blong yufala. ?Be from wanem yufala i no save ona long mi? Mo mi mi Masta* blong yufala. ?Be from wanem yufala i no save obei long mi? Oltaem yufala i stap lukluk rabis long mi. Be yufala i girap, yufala i stap talem se, “?Mifala i lukluk rabis long yu olsem wanem?”","Nao Profet Malakae i talem se, “Hae God i gat olgeta paoa, mo hem i talem se, ‘Ol pris. Oltaem, pikinini i save ona long papa blong hem, mo man blong wok i save ona gud long masta blong hem. Mi mi papa blong yufala. ?Be from wanem yufala i no save ona long mi? Mo mi mi Masta* blong yufala. ?Be from wanem yufala i no save obei long mi? Oltaem yufala i stap lukluk rabis long mi. Be yufala i girap, yufala i stap talem se, “?Mifala i lukluk rabis long yu olsem wanem?”"],[1,7,"Taem yufala i stap tekem ol kakae we i nogud i kam, blong mekem sakrefaes long mi long olta blong mi, be long fasin ya nao, yufala i stap lukluk rabis long mi. Mo yufala i stap talem se, “?Mifala i no stap tinghevi long yu olsem wanem?” Mi mi talem stret long yufala. Yufala i no stap tinghevi long mi, long fasin ya we yufala i stap lukluk rabis long olta blong mi.","Taem yufala i stap tekem ol kakae we i nogud i kam, blong mekem sakrefaes long mi long olta blong mi, be long fasin ya nao, yufala i stap lukluk rabis long mi. Mo yufala i stap talem se, “?Mifala i no stap tinghevi long yu olsem wanem?” Mi mi talem stret long yufala. Yufala i no stap tinghevi long mi, long fasin ya we yufala i stap lukluk rabis long olta blong mi."],[1,8,"Oltaem yufala i stap tekem anamol we i blaen, no we i sik, no wansaed leg blong hem i nogud, yufala i karem i kam long olta blong mi blong mekem sakrefaes long hem. ?Weswe? ?Yufala i ting se fasin ya i stret ya? Yufala i traem tekem wan anamol olsem, nao yufala i go givim long haeman blong yufala. ?Yufala i ting se hem bambae i glad long hem?’ ”","Oltaem yufala i stap tekem anamol we i blaen, no we i sik, no wansaed leg blong hem i nogud, yufala i karem i kam long olta blong mi blong mekem sakrefaes long hem. ?Weswe? ?Yufala i ting se fasin ya i stret ya? Yufala i traem tekem wan anamol olsem, nao yufala i go givim long haeman blong yufala. ?Yufala i ting se hem bambae i glad long hem?’ ”"],[1,9,"Mo profet i talem se, “Yufala ol pris.* Yufala i traem prea long Hae God blong i mekem i gud long yumi. Hem bambae i no save ansa long yufala, from we yufala i stap givim ol rabis presen ya long hem.","Mo profet i talem se, “Yufala ol pris.* Yufala i traem prea long Hae God blong i mekem i gud long yumi. Hem bambae i no save ansa long yufala, from we yufala i stap givim ol rabis presen ya long hem."],[1,10,"Hem i talem se, ‘I moa gud wan long yufala i satem ol doa blong yad blong haos* ya blong mi, blong yufala i no moa save go insaed blong bonem ol sakrefaes blong yufala long olta blong mi, we oli blong nating nomo. Mi mi no glad nating long yufala, nao from samting ya, bambae mi no save tekem sakrefaes we yufala i bonem i kam long mi.","Hem i talem se, ‘I moa gud wan long yufala i satem ol doa blong yad blong haos* ya blong mi, blong yufala i no moa save go insaed blong bonem ol sakrefaes blong yufala long olta blong mi, we oli blong nating nomo. Mi mi no glad nating long yufala, nao from samting ya, bambae mi no save tekem sakrefaes we yufala i bonem i kam long mi."],[1,11,"Olbaot long olgeta ples long wol ya i gat fulap man we oli stap ona long mi. Mo long olgeta ples, ol insens* mo ol sakrefaes we ol man oli stap bonem i kam long mi, oltaem mi mi glad long olgeta. Olgeta ya evriwan oli stap ona long mi.","Olbaot long olgeta ples long wol ya i gat fulap man we oli stap ona long mi. Mo long olgeta ples, ol insens* mo ol sakrefaes we ol man oli stap bonem i kam long mi, oltaem mi mi glad long olgeta. Olgeta ya evriwan oli stap ona long mi."],[1,12,"Be fasin ya we yufala i stap talem se olta blong mi i nogud, mo yufala i stap tekem ol anamol we yufala i lukluk rabis long olgeta, yufala i bonem long olta ya blong mekem sakrefaes long mi, hem i soemaot we yufala i no ona long mi nating.","Be fasin ya we yufala i stap talem se olta blong mi i nogud, mo yufala i stap tekem ol anamol we yufala i lukluk rabis long olgeta, yufala i bonem long olta ya blong mekem sakrefaes long mi, hem i soemaot we yufala i no ona long mi nating."],[1,13,"Oltaem yufala i stap talem se, “Mifala i taed finis long ol samting ya,” nao yufala i stap spet long fes blong mi. Oltaem yufala i stap tekem anamol we yufala i stilim, no leg blong hem i nogud, no we i sik, nao yufala i stap bonem blong mekem sakrefaes long mi. ?Weswe? ?Yufala i ting se mi mi glad long samting olsem?","Oltaem yufala i stap talem se, “Mifala i taed finis long ol samting ya,” nao yufala i stap spet long fes blong mi. Oltaem yufala i stap tekem anamol we yufala i stilim, no leg blong hem i nogud, no we i sik, nao yufala i stap bonem blong mekem sakrefaes long mi. ?Weswe? ?Yufala i ting se mi mi glad long samting olsem?"],[1,14,"Man we i gat wan gudfala sipsip we i promes finis blong givim long mi, be hem i girap, i ravem mi, i tekem narawan we i nogud blong mekem sakrefaes long mi, man olsem bambae trabol i mas kasem hem from. Mi mi Hae God, mi gat olgeta paoa, mo mi talem olsem from we mi nomo mi Hae King we olgeta man long wol ya oli stap ona gud long mi.’ ”","Man we i gat wan gudfala sipsip we i promes finis blong givim long mi, be hem i girap, i ravem mi, i tekem narawan we i nogud blong mekem sakrefaes long mi, man olsem bambae trabol i mas kasem hem from. Mi mi Hae God, mi gat olgeta paoa, mo mi talem olsem from we mi nomo mi Hae King we olgeta man long wol ya oli stap ona gud long mi.’ ”"],[2,1,"Nao Profet Malakae i talemaot we Hae God we i gat olgeta paoa i talem se, “Ol pris.* Tok blong mi long yufala i olsem.","Nao Profet Malakae i talemaot we Hae God we i gat olgeta paoa i talem se, “Ol pris.* Tok blong mi long yufala i olsem."],[2,2,"Yufala i mas ona long mi long olgeta laef blong yufala. Sipos yufala i no harem tok blong mi, bambae mi mekem we trabol i kam kasem yufala. Bambae mi mekem we trabol i kam kasem ol gudgudfala samting we yufala i stap kasem. Tru mi talem long yufala, ol samting ya, trabol i kasem olgeta finis, from we yufala i no stap tinghevi long ol tok blong mi.","Yufala i mas ona long mi long olgeta laef blong yufala. Sipos yufala i no harem tok blong mi, bambae mi mekem we trabol i kam kasem yufala. Bambae mi mekem we trabol i kam kasem ol gudgudfala samting we yufala i stap kasem. Tru mi talem long yufala, ol samting ya, trabol i kasem olgeta finis, from we yufala i no stap tinghevi long ol tok blong mi."],[2,3,"Nao from samting ya, bambae mi tok strong long ol pikinini blong yufala blong stretem olgeta, mo bambae mi ravem fes blong yufala long ol doti blong ol anamol ya we yufala i mekem sakrefaes long olgeta. Mo bambae mi tekem yufala, mi sakem yufala i go long ples blong doti.","Nao from samting ya, bambae mi tok strong long ol pikinini blong yufala blong stretem olgeta, mo bambae mi ravem fes blong yufala long ol doti blong ol anamol ya we yufala i mekem sakrefaes long olgeta. Mo bambae mi tekem yufala, mi sakem yufala i go long ples blong doti."],[2,4,"Nao taem yufala i luk samting ya, bambae yufala i save we mi mi givim tok ya long yufala, blong promes blong mi i no save foldaon. Yufala i laen* blong Livae,* mo promes* ya, mi mi mekem wetem ol bubu blong yufala bifo.","Nao taem yufala i luk samting ya, bambae yufala i save we mi mi givim tok ya long yufala, blong promes blong mi i no save foldaon. Yufala i laen* blong Livae,* mo promes* ya, mi mi mekem wetem ol bubu blong yufala bifo."],[2,5,"“Long promes ya, mi mi promes blong givim laef mo pis long olgeta. Mi mekem olsem blong oli tinghevi long mi, mo long taem ya, oli ona gud long mi, oli tinghevi long mi.","“Long promes ya, mi mi promes blong givim laef mo pis long olgeta. Mi mekem olsem blong oli tinghevi long mi, mo long taem ya, oli ona gud long mi, oli tinghevi long mi."],[2,6,"Olgeta ya oli stap tijim ol man blong oli folem ol stret fasin nomo. Mo long taem ya, oltaem, olgeta oli stap fren gud wetem mi. Fasin blong olgeta i stret gud long fes blong mi, mo oltaem, oli stap givhan long ol narafala man blong oli lego ol rabis fasin blong olgeta.","Olgeta ya oli stap tijim ol man blong oli folem ol stret fasin nomo. Mo long taem ya, oltaem, olgeta oli stap fren gud wetem mi. Fasin blong olgeta i stret gud long fes blong mi, mo oltaem, oli stap givhan long ol narafala man blong oli lego ol rabis fasin blong olgeta."],[2,7,"Mi mi Hae God, mi gat olgeta paoa, mo wok blong yufala ol pris, i blong tijim ol man blong oli savegud mi. Mo from we yufala i man blong wok blong mi, i stret nomo blong ol man oli kam long yufala blong lanem fasin blong mi long yufala.","Mi mi Hae God, mi gat olgeta paoa, mo wok blong yufala ol pris, i blong tijim ol man blong oli savegud mi. Mo from we yufala i man blong wok blong mi, i stret nomo blong ol man oli kam long yufala blong lanem fasin blong mi long yufala."],[2,8,"“Be naoia, yufala ol pris, yufala i tanem baksaed finis long stret fasin. Mo ol samting we yufala i stap tijim ol man long hem, i mekem plante man oli gorong. Mo promes ya we mi mekem wetem yufala, yufala i brekem finis.","“Be naoia, yufala ol pris, yufala i tanem baksaed finis long stret fasin. Mo ol samting we yufala i stap tijim ol man long hem, i mekem plante man oli gorong. Mo promes ya we mi mekem wetem yufala, yufala i brekem finis."],[2,9,"Nao from we yufala i mekem olsem, bambae mi letem ol man blong yufala oli lukluk rabis long yufala, from we yufala i no obei long ol samting we mi mi talem. Mo taem yufala i stap tijim ol man blong mi, be fasin blong yufala, yufala i no stap mekem i sem mak long olgeta evriwan.”","Nao from we yufala i mekem olsem, bambae mi letem ol man blong yufala oli lukluk rabis long yufala, from we yufala i no obei long ol samting we mi mi talem. Mo taem yufala i stap tijim ol man blong mi, be fasin blong yufala, yufala i no stap mekem i sem mak long olgeta evriwan.”"],[2,10,"Nao Profet Malakae i talem se, “Yumi evriwan i kamaot long wan papa nomo. Mo God we i mekem yumi, hem i wan nomo. ?Sipos i olsem, be from wanem yumi stap brekem ol promes ya we yumi nomo i mekem long yumi? ?Mo from wanem yumi stap lukluk rabis long promes* ya we God i mekem wetem ol bubu blong yumi bifo?","Nao Profet Malakae i talem se, “Yumi evriwan i kamaot long wan papa nomo. Mo God we i mekem yumi, hem i wan nomo. ?Sipos i olsem, be from wanem yumi stap brekem ol promes ya we yumi nomo i mekem long yumi? ?Mo from wanem yumi stap lukluk rabis long promes* ya we God i mekem wetem ol bubu blong yumi bifo?"],[2,11,"Olgeta long Juda,* naoia oli brekem promes blong olgeta finis we oli mekem wetem God. Mo oli mekem wan fasin we i nogud we i nogud long Jerusalem,* mo long olgeta ples raonabaot long hem. Oli stap spolemgud haos* ya blong Hae God we hem i laekem tumas, long fasin ya we oli stap mared long ol woman blong ol narafala kantri we oli stap mekem wosip long ol narafala god.","Olgeta long Juda,* naoia oli brekem promes blong olgeta finis we oli mekem wetem God. Mo oli mekem wan fasin we i nogud we i nogud long Jerusalem,* mo long olgeta ples raonabaot long hem. Oli stap spolemgud haos* ya blong Hae God we hem i laekem tumas, long fasin ya we oli stap mared long ol woman blong ol narafala kantri we oli stap mekem wosip long ol narafala god."],[2,12,"Hae God i gat olgeta paoa, mo prea blong mi we olgeta we oli mekem fasin olsem, hem bambae i tekemaot olgeta i gowe long kampani blong yumi. Mo bambae i blokem olgeta, blong oli no moa joen bakegen wetem yumi blong go givim ol presen blong yumi long hem.”","Hae God i gat olgeta paoa, mo prea blong mi we olgeta we oli mekem fasin olsem, hem bambae i tekemaot olgeta i gowe long kampani blong yumi. Mo bambae i blokem olgeta, blong oli no moa joen bakegen wetem yumi blong go givim ol presen blong yumi long hem.”"],[2,13,"Mo Profet Malakae i gohed i talem se, “Narafala samting we yufala i bin mekem, i olsem. Taem yufala i luk we Hae God i no glad long ol presen we yufala i givim i go long hem, yufala i harem nogud, nao yufala i krae from. Mo yufala i krae gogo wota blong ae blong yufala i kavremapgud olta blong hem.","Mo Profet Malakae i gohed i talem se, “Narafala samting we yufala i bin mekem, i olsem. Taem yufala i luk we Hae God i no glad long ol presen we yufala i givim i go long hem, yufala i harem nogud, nao yufala i krae from. Mo yufala i krae gogo wota blong ae blong yufala i kavremapgud olta blong hem."],[2,14,"Taem yufala i luk olsem, yufala i stap asaskem se, ‘?From wanem hem i no save tekem presen ya blong yumi?’ Be hem i no save tekem, from we hem i luk we yufala i no holem ol promes ya we yufala i mekem long ol woman blong yufala. Taem we yufala i yangfala, yufala i mared, mo long taem ya, yufala i promes long fes blong God, se bambae yufala i holemtaet promes ya we yufala i mekem wetem ol woman ya blong yufala. Ol woman ya, oli blong yufala olwe, be yufala i girap, yufala i brekem promes blong yufala, we yufala i mekem wetem olgeta long fes blong God.","Taem yufala i luk olsem, yufala i stap asaskem se, ‘?From wanem hem i no save tekem presen ya blong yumi?’ Be hem i no save tekem, from we hem i luk we yufala i no holem ol promes ya we yufala i mekem long ol woman blong yufala. Taem we yufala i yangfala, yufala i mared, mo long taem ya, yufala i promes long fes blong God, se bambae yufala i holemtaet promes ya we yufala i mekem wetem ol woman ya blong yufala. Ol woman ya, oli blong yufala olwe, be yufala i girap, yufala i brekem promes blong yufala, we yufala i mekem wetem olgeta long fes blong God."],[2,15,"Be long taem ya we man i mekem promes wetem woman blong hem, God i joenem tufala i kam wan bodi nomo, mo tufala i gat wan tingting nomo. ?God i mekem olsem blong wanem? Hem i mekem olsem blong tufala i gat ol pikinini blong tufala, we bambae oli man blong God stret. Nao from samting ya, yufala i mas lukaot gud we i no gat wan long yufala, i brekem promes ya we hem i mekem wetem woman blong hem.","Be long taem ya we man i mekem promes wetem woman blong hem, God i joenem tufala i kam wan bodi nomo, mo tufala i gat wan tingting nomo. ?God i mekem olsem blong wanem? Hem i mekem olsem blong tufala i gat ol pikinini blong tufala, we bambae oli man blong God stret. Nao from samting ya, yufala i mas lukaot gud we i no gat wan long yufala, i brekem promes ya we hem i mekem wetem woman blong hem."],[2,16,"Yumi ol laen* blong Isrel,* mo Hae God i God blong yumi, mo hem i talem se, ‘Mi mi no laekem nating fasin ya we man i mekem divos long woman blong hem. Mi mi no laekem nating fasin ya we man i mekem i strong tumas long woman blong hem. Nao from samting ya, bambae yufala i no mas brekem promes ya we yufala i mekem wetem ol woman blong yufala.’ ”","Yumi ol laen* blong Isrel,* mo Hae God i God blong yumi, mo hem i talem se, ‘Mi mi no laekem nating fasin ya we man i mekem divos long woman blong hem. Mi mi no laekem nating fasin ya we man i mekem i strong tumas long woman blong hem. Nao from samting ya, bambae yufala i no mas brekem promes ya we yufala i mekem wetem ol woman blong yufala.’ ”"],[2,17,"Nao Profet Malakae i talem se, “Olgeta. Oltaem yufala i stap mekem Hae God i taed gud long ol toktok blong yufala. Be yufala i stap asaskem se, ‘?Mifala i mekem hem i taed gud olsem wanem?’ Yufala i mekem hem i taed gud long yufala long fasin ya we yufala i stap talem se, ‘Hae God i gat olgeta paoa, mo hem i luk se ol man blong mekem ol rabis fasin oli gud nomo, mo hem i laekem rabis fasin we oli stap mekem.’ Mo yufala i stap talem tu se, ‘?Wehem Hae God ya we oli stap tokbaot hem, se bambae i jajem man long stret fasin?’","Nao Profet Malakae i talem se, “Olgeta. Oltaem yufala i stap mekem Hae God i taed gud long ol toktok blong yufala. Be yufala i stap asaskem se, ‘?Mifala i mekem hem i taed gud olsem wanem?’ Yufala i mekem hem i taed gud long yufala long fasin ya we yufala i stap talem se, ‘Hae God i gat olgeta paoa, mo hem i luk se ol man blong mekem ol rabis fasin oli gud nomo, mo hem i laekem rabis fasin we oli stap mekem.’ Mo yufala i stap talem tu se, ‘?Wehem Hae God ya we oli stap tokbaot hem, se bambae i jajem man long stret fasin?’"],[3,1,"“Be Hae God i gat olgeta paoa, mo hem i talem se, ‘Bambae mi mi sanem wan man blong karem tok blong mi i kam fastaem, mo hem bambae i mekemrere rod blong mi. Nao biaen, Masta ya blong yufala we yufala i stap wet blong luk, hem bambae i kamtru long tabu haos* blong hem kwiktaem nomo, we bambae yufala i sek long hem. Man ya we yufala i wantem blong luk hem, bambae i kamtru, nao i talemaot promes* we mi mi mekem wetem yufala.’ ”","“Be Hae God i gat olgeta paoa, mo hem i talem se, ‘Bambae mi mi sanem wan man blong karem tok blong mi i kam fastaem, mo hem bambae i mekemrere rod blong mi. Nao biaen, Masta ya blong yufala we yufala i stap wet blong luk, hem bambae i kamtru long tabu haos* blong hem kwiktaem nomo, we bambae yufala i sek long hem. Man ya we yufala i wantem blong luk hem, bambae i kamtru, nao i talemaot promes* we mi mi mekem wetem yufala.’ ”"],[3,2,"Nao profet i gohed i talem se, “?Be taem hem i kam, hu nao bambae i naf blong stanap long dei ya? ?Taem we hem i kamtru, hu nao bambae i save stanap long fes blong hem? Taem hem i kam, wok blong hem, bambae i mekem man i klin, olsem we man i yusum sop blong wasem klos we i doti. Wok blong hem bambae i olsem faea we man i yusum blong bonem aean blong mekem i klin.","Nao profet i gohed i talem se, “?Be taem hem i kam, hu nao bambae i naf blong stanap long dei ya? ?Taem we hem i kamtru, hu nao bambae i save stanap long fes blong hem? Taem hem i kam, wok blong hem, bambae i mekem man i klin, olsem we man i yusum sop blong wasem klos we i doti. Wok blong hem bambae i olsem faea we man i yusum blong bonem aean blong mekem i klin."],[3,3,"Bambae hem i kam blong jajem olgeta man. Bambae hem i mekem olsem we man i bonem silva mo gol blong mekem i kam klin. Hem bambae i mekem laef blong ol pris* i klin long fes blong Hae God, blong oli save tekem ol presen we oli stret i kam long hem.","Bambae hem i kam blong jajem olgeta man. Bambae hem i mekem olsem we man i bonem silva mo gol blong mekem i kam klin. Hem bambae i mekem laef blong ol pris* i klin long fes blong Hae God, blong oli save tekem ol presen we oli stret i kam long hem."],[3,4,"Nao bambae ol presen ya we ol man Jerusalem* wetem ol narafala man Juda* oli tekem i kam long Hae God, bambae i save mekem hem i glad long olgeta, olsem we hem i stap glad long olgeta bifo.”","Nao bambae ol presen ya we ol man Jerusalem* wetem ol narafala man Juda* oli tekem i kam long Hae God, bambae i save mekem hem i glad long olgeta, olsem we hem i stap glad long olgeta bifo.”"],[3,5,"Nao profet i talemaot we Hae God i talem se, “Taem mi mi kamtru long yufala blong jajem ol man, bambae mi no save tektaem blong talemaot ol poen agens long olgeta. Hemia olgeta we oli stap wokem majik, mo olgeta we oli lego ol woman blong olgeta, oli go mared long ol narafala woman, mo olgeta we oli mekem ol giaman toktok, mo ol masta we oli ravem ol boe blong olgeta from pei blong olgeta, mo olgeta we oli stap spolem ol wido wetem ol pikinini we ol papa blong olgeta i ded, mo ol strenja. Bambae mi jajem olgeta man nogud ya we oli no ona long mi.”","Nao profet i talemaot we Hae God i talem se, “Taem mi mi kamtru long yufala blong jajem ol man, bambae mi no save tektaem blong talemaot ol poen agens long olgeta. Hemia olgeta we oli stap wokem majik, mo olgeta we oli lego ol woman blong olgeta, oli go mared long ol narafala woman, mo olgeta we oli mekem ol giaman toktok, mo ol masta we oli ravem ol boe blong olgeta from pei blong olgeta, mo olgeta we oli stap spolem ol wido wetem ol pikinini we ol papa blong olgeta i ded, mo ol strenja. Bambae mi jajem olgeta man nogud ya we oli no ona long mi.”"],[3,6,"Nao Profet Malakae i talemaot we Hae God i talem se, “Mi mi Hae God, mo mi no save jenis samtaem. Nao from samting ya, yufala ol laen* blong Isrel,* yufala i stap yet, yufala i no lus olgeta.","Nao Profet Malakae i talemaot we Hae God i talem se, “Mi mi Hae God, mo mi no save jenis samtaem. Nao from samting ya, yufala ol laen* blong Isrel,* yufala i stap yet, yufala i no lus olgeta."],[3,7,"Yufala i sem mak nomo long ol bubu blong yufala bifo, we oli tanem baksaed long ol loa blong mi, mo oli no bin holem olgeta. Naoia sipos yufala i tanem tingting blong yufala, yufala i kambak long mi, mi bambae mi save kambak long yufala bakegen. Be yufala i talem se, ‘?Be bambae mifala i kambak long yu olsem wanem?’","Yufala i sem mak nomo long ol bubu blong yufala bifo, we oli tanem baksaed long ol loa blong mi, mo oli no bin holem olgeta. Naoia sipos yufala i tanem tingting blong yufala, yufala i kambak long mi, mi bambae mi save kambak long yufala bakegen. Be yufala i talem se, ‘?Be bambae mifala i kambak long yu olsem wanem?’"],[3,8,"Yufala i traem tingbaot. ?I stret blong man i ravem mi? I no stret nating blong man i mekem olsem, be yufala i stap ravem mi ya. Be bakegen yufala i talem se, ‘?Mifala i ravem yu olsem wanem?’ Yufala i stap ravem mi long fasin ya we yufala i no moa stap givim ol taet* blong yufala mo ol presen blong yufala i kam long mi.","Yufala i traem tingbaot. ?I stret blong man i ravem mi? I no stret nating blong man i mekem olsem, be yufala i stap ravem mi ya. Be bakegen yufala i talem se, ‘?Mifala i ravem yu olsem wanem?’ Yufala i stap ravem mi long fasin ya we yufala i no moa stap givim ol taet* blong yufala mo ol presen blong yufala i kam long mi."],[3,9,"Mi bambae mi mekem we trabol i kam kasem yufala evriwan, from we yufala evriwan i stap ravem mi.","Mi bambae mi mekem we trabol i kam kasem yufala evriwan, from we yufala evriwan i stap ravem mi."],[3,10,"Yufala i mas tekem olgeta taet blong yufala i kam long haos* blong mi, blong bambae i save gat plante kakae long hem. Sipos yufala i mekem olsem, bambae yufala i luk paoa blong mi, we bambae mi openem skae, mi letem olgeta gudgudfala samting i kam long yufala we i plante we i plante.","Yufala i mas tekem olgeta taet blong yufala i kam long haos* blong mi, blong bambae i save gat plante kakae long hem. Sipos yufala i mekem olsem, bambae yufala i luk paoa blong mi, we bambae mi openem skae, mi letem olgeta gudgudfala samting i kam long yufala we i plante we i plante."],[3,11,"Bambae mi no moa save sanem ol lokis* i kam blong spolem ol garen blong yufala, mo ol plantesen blong ol grep* blong yufala bambae oli karem plante frut blong olgeta.","Bambae mi no moa save sanem ol lokis* i kam blong spolem ol garen blong yufala, mo ol plantesen blong ol grep* blong yufala bambae oli karem plante frut blong olgeta."],[3,12,"Nao from we ples blong yufala bambae i gudfala tumas, ol man blong ol narafala kantri bambae oli save talem se mi mi blesem yufala. Mi mi Hae God, mi gat olgeta paoa, mo hemia tok blong mi.”","Nao from we ples blong yufala bambae i gudfala tumas, ol man blong ol narafala kantri bambae oli save talem se mi mi blesem yufala. Mi mi Hae God, mi gat olgeta paoa, mo hemia tok blong mi.”"],[3,13,"Nao Profet Malakae i talemaot we Hae God i talem se, “I gat plante strong toktok we yufala i stap sakem long mi. Be yufala i girap, yufala i talem se, ‘?Wanem strong tok ya we mifala i sakem long yu?’","Nao Profet Malakae i talemaot we Hae God i talem se, “I gat plante strong toktok we yufala i stap sakem long mi. Be yufala i girap, yufala i talem se, ‘?Wanem strong tok ya we mifala i sakem long yu?’"],[3,14,"Ol tok we yufala i sakem, i olsem. Yufala i stap talem se, ‘Yumi stap mekem wok blong Hae God, be blong nating nomo. Sipos yumi mekem ol samting we hem i stap talem, no sipos yumi soemaot long hem we yumi tanem tingting blong yumi from ol samting nogud we yumi bin mekem, be ol samting ya tu i no save givhan long yumi.","Ol tok we yufala i sakem, i olsem. Yufala i stap talem se, ‘Yumi stap mekem wok blong Hae God, be blong nating nomo. Sipos yumi mekem ol samting we hem i stap talem, no sipos yumi soemaot long hem we yumi tanem tingting blong yumi from ol samting nogud we yumi bin mekem, be ol samting ya tu i no save givhan long yumi."],[3,15,"Long lukluk blong yumi, yumi luk se ol praod man nao oli stap harem gud. Mo ol man nogud oli gat plante samting. Be i no hemia nomo. Oltaem oli stap traem God long ol rabis fasin blong olgeta blong faenemaot se tingting blong hem i longfala no nogat, be oli no kasem panis from.’ ”","Long lukluk blong yumi, yumi luk se ol praod man nao oli stap harem gud. Mo ol man nogud oli gat plante samting. Be i no hemia nomo. Oltaem oli stap traem God long ol rabis fasin blong olgeta blong faenemaot se tingting blong hem i longfala no nogat, be oli no kasem panis from.’ ”"],[3,16,"Nao profet i talem se, “Be ol man we oli ona gud long Hae God, mo oli tinghevi long hem, oli stap toktok gud wetem olgeta bakegen. Nao Hae God i stap lesin long olgeta, mo i harem ol samting we oli stap talem. Nao long fes blong hem, ol man blong hem oli raetemdaon long wan buk, ol nem blong olgeta ya we oli ona gud long hem, mo oli tinghevi long hem.","Nao profet i talem se, “Be ol man we oli ona gud long Hae God, mo oli tinghevi long hem, oli stap toktok gud wetem olgeta bakegen. Nao Hae God i stap lesin long olgeta, mo i harem ol samting we oli stap talem. Nao long fes blong hem, ol man blong hem oli raetemdaon long wan buk, ol nem blong olgeta ya we oli ona gud long hem, mo oli tinghevi long hem."],[3,17,"Nao hem i talem se, ‘Olgeta ya bambae oli man blong mi, mo long taem ya we bambae mi jajem ol man, bambae mi mekem olgeta oli spesel man blong mi. Mi bambae mi gat sore long olgeta, mi givhan long olgeta, stret olsem we wan papa i gat sore long pikinini blong hem, we i stap wok blong hem.","Nao hem i talem se, ‘Olgeta ya bambae oli man blong mi, mo long taem ya we bambae mi jajem ol man, bambae mi mekem olgeta oli spesel man blong mi. Mi bambae mi gat sore long olgeta, mi givhan long olgeta, stret olsem we wan papa i gat sore long pikinini blong hem, we i stap wok blong hem."],[3,18,"Mo bakegen, long taem ya, ol man blong mi bambae oli luksave fasin we bambae mi mekem long ol man. Ol stret man oli stap mekem wok blong mi, mo bambae mi mekem i stret long olgeta. Be ol man nogud, oli no stap mekem wok blong mi, nao bambae mi mekem i narafala long olgeta. Mi mi Hae God, mi gat olgeta paoa, mo hemia tok blong mi.’ ”","Mo bakegen, long taem ya, ol man blong mi bambae oli luksave fasin we bambae mi mekem long ol man. Ol stret man oli stap mekem wok blong mi, mo bambae mi mekem i stret long olgeta. Be ol man nogud, oli no stap mekem wok blong mi, nao bambae mi mekem i narafala long olgeta. Mi mi Hae God, mi gat olgeta paoa, mo hemia tok blong mi.’ ”"],[4,1,"Nao Profet Malakae i talemaot we Hae God i talem se, “I gat dei i stap kam, we mi bambae mi bonem ol praod man mo ol man nogud long faea, olsem we man i bonem gras, we i bon we i bon olgeta, i no moa save gru bakegen. Long taem ya, bambae mi bonem olgeta evriwan, we bambae i no moa gat wan i stap.","Nao Profet Malakae i talemaot we Hae God i talem se, “I gat dei i stap kam, we mi bambae mi bonem ol praod man mo ol man nogud long faea, olsem we man i bonem gras, we i bon we i bon olgeta, i no moa save gru bakegen. Long taem ya, bambae mi bonem olgeta evriwan, we bambae i no moa gat wan i stap."],[4,2,"Be yufala ya we yufala i stap ona long mi, bambae paoa blong mi blong sevem man mo blong mekem hem i stret man long fes blong mi, bambae i kavremap yufala olsem san we i girap, nao laet blong hem i saen, i kavremap olgeta samting, nao bambae yufala i kam gud bakegen. Bambae yufala i fri, yufala i glad, olsem smol buluk we man i tekemaot long fenis, i letem hem i gofri, i stap jamjam.","Be yufala ya we yufala i stap ona long mi, bambae paoa blong mi blong sevem man mo blong mekem hem i stret man long fes blong mi, bambae i kavremap yufala olsem san we i girap, nao laet blong hem i saen, i kavremap olgeta samting, nao bambae yufala i kam gud bakegen. Bambae yufala i fri, yufala i glad, olsem smol buluk we man i tekemaot long fenis, i letem hem i gofri, i stap jamjam."],[4,3,"Long dei ya, taem we mi mi jajem ol man, bambae yufala i winim ol man nogud, nao yufala i stap purumpurumbut long olgeta i godaon long graon. Mi mi Hae God, mi gat olgeta paoa, mo hemia tok blong mi.","Long dei ya, taem we mi mi jajem ol man, bambae yufala i winim ol man nogud, nao yufala i stap purumpurumbut long olgeta i godaon long graon. Mi mi Hae God, mi gat olgeta paoa, mo hemia tok blong mi."],[4,4,"“Bambae yufala i no fogetem ol loa mo ol tok, we Moses, man blong wok blong mi, i tijim yufala long hem. Ol tok ya, mi bin givim long hem long Hil ya Sinae, blong yufala ol laen* blong Isrel* i folem.","“Bambae yufala i no fogetem ol loa mo ol tok, we Moses, man blong wok blong mi, i tijim yufala long hem. Ol tok ya, mi bin givim long hem long Hil ya Sinae, blong yufala ol laen* blong Isrel* i folem."],[4,5,"“Bambae mi sanem Profet Elaeja i kamtru long yufala fastaem, nao biaen, bigfala Dei blong mi, bambae i jes kamtru we olgeta man bambae oli fraet long hem.","“Bambae mi sanem Profet Elaeja i kamtru long yufala fastaem, nao biaen, bigfala Dei blong mi, bambae i jes kamtru we olgeta man bambae oli fraet long hem."],[4,6,"Taem profet ya i kamtru, hem bambae i mekem we ol papa wetem ol pikinini blong olgeta we oli stap seraot, oli joen gud bakegen, oli stap gud. Sipos i no olsem, bambae mi mas kam spolemgud ples blong yufala.”","Taem profet ya i kamtru, hem bambae i mekem we ol papa wetem ol pikinini blong olgeta we oli stap seraot, oli joen gud bakegen, oli stap gud. Sipos i no olsem, bambae mi mas kam spolemgud ples blong yufala.”"]]}};